/*
 * logo-premium-laque.js — Logo Dent All Group, style « Laque brillante » (Pack Tablettes)
 *
 * Pourquoi : l'ancien logo CSS 3D (≈ 80 plans empilés) laissait voir à travers
 * pendant la rotation (tri des plans imparfait sur tablette). Ici le logo est
 * un VRAI solide : la silhouette (alpha > 0,5) est extrudée (épaisseur 8 % de
 * la largeur) avec des arêtes arrondies, puis rendue par lancer de rayon
 * (sphere tracing) dans un champ de distance signée (SDF). Le résultat est
 * opaque sous tous les angles, profil compris.
 *
 * Un seul canvas + un seul contexte WebGL1, simplement déplacé à chaque rendu
 * de la page (les navigateurs limitent le nombre de contextes WebGL).
 *
 * API
 *   LogoPremium.monter(conteneur, urlImage[, options]) -> boolean
 *     options.mat (Lynk, 2026-11-05) : rendu MAT, sans reflets (ni spéculaire,
 *     ni vernis, ni studio) : seulement la couleur éclairée. Sans options :
 *     l'aspect « laque brillante » d'origine (logo choisi dans Apparence).
 *     false : WebGL indisponible (ou rendu logiciel trop lent), pas de highp,
 *             shader refusé, contexte perdu depuis plus de 5 s, ou image
 *             constatée illisible -> l'appelant affiche son repli CSS.
 *     urlImage : de préférence une URL data: (seule lisible par getImageData
 *     quelle que soit l'origine de la page : file://, content://).
 *   LogoPremium._angleFixe = null | degrés   (débogage ; null = animation)
 *   Si l'échec survient APRÈS monter() (image illisible, contexte jamais rendu),
 *   le canvas est remplacé aussitôt par le logo plat (img.logo-premium-plat) et
 *   l'événement window « logopremium-erreur » (detail.url, detail.message) est émis.
 *   Pause automatique : onglet caché, canvas détaché, hors de l'écran, ou
 *   recouvert par une iframe (appli du Pack ouverte par-dessus l'accueil).
 *
 * JavaScript classique (ES5), sans dépendance ni accès réseau.
 */
(function () {
  'use strict';

  // Script inclus deux fois : on garde le premier (un seul contexte WebGL).
  if (window.LogoPremium && typeof window.LogoPremium.monter === 'function') return;

  // ------------------------------------------------------------------ réglages
  var N_SDF = 256;         // texture de distance 256 × 256
  var SUR = 2;             // distances calculées sur 512 × 512 puis moyennées : contours plus fidèles
  var ETENDUE = 1.2;       // la grille couvre l'image + 10 % de marge de chaque côté
  var N_COUL = 512;        // texture de couleur ≈ 1 texel par pixel affiché (300 px × DPR 2)
  var PLAGE_FIN = 8;       // canal R : ±8 texels -> ≈ 1/16 de texel de précision près de la surface
  var PLAGE_GROS = 64;     // canal G : ±64 texels -> grands pas loin de la surface
  var EPAISSEUR = 0.12;    // épaisseur totale / largeur du logo (0,08 jugé trop fin : « un peu d'épaisseur »)
  var ARRONDI = 0.02;      // rayon du biseau / largeur du logo
  var DIST_CAM = 3.2;      // perspective légère (champ ≈ 18°)
  var PERIODE = 7000;      // un tour en 7 s
  var ANGLE_REDUIT = -25;  // vue fixe légèrement de biais (prefers-reduced-motion)
  var INF = 1e20;

  // ------------------------------------------------------------------ shaders
  // Les commentaires restent côté JS : le source GLSL est en ASCII pur
  // (certains pilotes refusent tout autre caractère, même en commentaire).
  function nb(x) { return (Math.abs(x) < 5e-5 ? 0 : x).toFixed(4); }
  function v3(x, y, z) { return 'vec3(' + nb(x) + ', ' + nb(y) + ', ' + nb(z) + ')'; }
  function v3u(x, y, z) { var l = Math.sqrt(x * x + y * y + z * z); return v3(x / l, y / l, z / l); }
  function v2u(x, y) { var l = Math.sqrt(x * x + y * y); return 'vec2(' + nb(x / l) + ', ' + nb(y / l) + ')'; }
  function lin(hex) { // sRGB -> linéaire approché (gamma 2, l'inverse exact de la sortie sqrt)
    var r = parseInt(hex.slice(1, 3), 16) / 255, g = parseInt(hex.slice(3, 5), 16) / 255, b = parseInt(hex.slice(5, 7), 16) / 255;
    return v3(r * r, g * g, b * b);
  }

  var VS = [
    'attribute vec2 aPos;',
    'void main() { gl_Position = vec4(aPos, 0.0, 1.0); }'   // un seul grand triangle couvre le canvas
  ].join('\n');

  // highp exigé (pas de repli mediump) : en fp16, t ≈ 3 n'avance plus près de la
  // surface et le logo se troue. Sans highp la compilation échoue -> repli CSS.
  var FS = [
    'precision highp float;',
    'uniform sampler2D uSdf;',      // R : distance fine, G : distance grossière
    'uniform sampler2D uCoul;',     // couleurs du logo, opaques et étendues hors silhouette
    'uniform vec2 uReso;',          // taille du canvas en pixels
    'uniform vec2 uRot;',           // cos, sin de l'angle de rotation
    'uniform float uDist;',         // distance caméra - axe de rotation
    'uniform float uTan;',          // tangente du demi-champ (plus petite dimension)
    'uniform vec2 uCentre;',        // centre de la silhouette dans l'image (y vers le haut)
    'uniform vec3 uBoite;',         // demi-côtés de la boîte englobante (repère de l'objet)
    'uniform float uInvS;',         // 1 / étendue de la grille de distance
    'uniform float uTexel;',        // côté d'un texel de distance
    'uniform float uH;',            // demi-épaisseur
    'uniform float uR;',            // rayon du biseau
    'uniform float uMat;',          // 1 : mat (Lynk), 0 : laque brillante
    'const float PLAGE_FIN = ' + nb(PLAGE_FIN) + ';',
    'const float PLAGE_GROS = ' + nb(PLAGE_GROS) + ';',
    // Matière : bleu-vert profond (#0b8a96) assombri vers le milieu de la tranche.
    'const vec3 TEAL = ' + lin('#0b8a96') + ';',
    'const vec3 TEAL_SOMBRE = ' + lin('#066f7a') + ';',
    // Éclairage de studio chaleureux : clé chaude en haut à gauche, contre froid à droite.
    'const vec3 L1 = ' + v3u(-0.50, 0.62, 0.60) + ';',
    'const vec3 C1 = ' + v3(0.85, 0.79, 0.714) + ';',
    'const vec3 L2 = ' + v3u(0.75, 0.15, 0.35) + ';',
    'const vec3 C2 = ' + v3(0.28, 0.315, 0.35) + ';',
    'const vec3 AMB_SOL = ' + v3(0.22, 0.20, 0.18) + ';',
    'const vec3 AMB_CIEL = ' + v3(0.40, 0.42, 0.45) + ';',
    // Environnement réfléchi par le vernis : sol chaud, ciel clair, grande boîte à
    // lumière, et deux bandes verticales étroites qui balaient les faces en tournant.
    'const vec3 SOL = ' + v3(0.15, 0.13, 0.11) + ';',
    'const vec3 CIEL = ' + v3(0.82, 0.86, 0.90) + ';',
    'const vec3 BOITE = ' + v3(1.20, 1.10, 0.95) + ';',
    'const vec3 DIR_BOITE = ' + v3u(-0.46, 0.72, 0.52) + ';',
    'const vec2 B1 = ' + v2u(-0.574, 0.819) + ';',      // bande chaude, 35° à gauche
    'const vec3 I1 = ' + v3(16.0, 15.0, 13.5) + ';',
    'const vec2 B2 = ' + v2u(0.819, 0.574) + ';',       // bande froide, 55° à droite
    'const vec3 I2 = ' + v3(9.0, 9.6, 10.5) + ';',

    // Distance 2D signée à la silhouette (unités objet) : UNE lecture de texture.
    // Près du bord on prend le canal fin ; plus loin le canal grossier, minoré
    // d'un demi-texel pour rester prudent malgré sa quantification.
    'float sdf2(vec2 p) {',
    '  vec2 q = p + uCentre;',
    '  vec4 s = texture2D(uSdf, vec2(0.5 + q.x * uInvS, 0.5 - q.y * uInvS));',
    '  float fin = (s.r * 2.0 - 1.0) * PLAGE_FIN;',
    '  float gros = (s.g * 2.0 - 1.0) * PLAGE_GROS - 0.5;',
    '  return mix(gros, fin, step(abs(fin), PLAGE_FIN - 2.0)) * uTexel;',
    '}',

    // Extrusion arrondie : épaisseur 2h, arêtes de rayon r ; la silhouette
    // d'origine est conservée au milieu de l'épaisseur.
    'float carte(float d2, float z) {',
    '  vec2 w = vec2(d2 + uR, abs(z) - uH + uR);',
    '  return min(max(w.x, w.y), 0.0) + length(max(w, 0.0)) - uR;',
    '}',

    // Intersection avec la boîte englobante (méthode des dalles), sans division par zéro.
    'vec2 boite(vec3 ro, vec3 rd) {',
    '  vec3 sg = vec3(greaterThanEqual(rd, vec3(0.0))) * 2.0 - 1.0;',
    '  vec3 inv = sg / max(abs(rd), vec3(1e-4));',
    '  vec3 t1 = (-uBoite - ro) * inv;',
    '  vec3 t2 = (uBoite - ro) * inv;',
    '  vec3 tn = min(t1, t2);',
    '  vec3 tf = max(t1, t2);',
    '  return vec2(max(max(tn.x, tn.y), tn.z), min(min(tf.x, tf.y), tf.z));',
    '}',

    // Bande lumineuse verticale vue dans la direction h (plan horizontal).
    // Profil net (exp(-x^4)) ; élargie quand la normale varie vite sous le pixel,
    // à énergie constante : reflet net sans scintillement sur les biseaux.
    'float bande(vec2 h, vec2 dir, float l0, float flou) {',
    '  float l = sqrt(l0 * l0 + flou * flou);',
    '  float x = abs(h.x * dir.y - h.y * dir.x) / l;',
    '  x = x * x;',
    '  return exp(-x * x) * step(0.0, dot(h, dir)) * (l0 / l);',
    '}',

    'vec3 studio(vec3 r, float flou) {',
    '  vec3 c = mix(SOL, CIEL, smoothstep(-0.40, 0.70, r.y));',
    '  c += BOITE * smoothstep(0.80, 0.97, dot(r, DIR_BOITE));',
    '  vec2 h = r.xz / max(length(r.xz), 1e-3);',
    '  float v = smoothstep(-0.65, -0.35, r.y) * (1.0 - smoothstep(0.65, 0.92, r.y));',
    '  c += v * (I1 * bande(h, B1, 0.007, flou) + I2 * bande(h, B2, 0.005, flou));',
    '  return c;',
    '}',

    'void main() {',
    '  float m = min(uReso.x, uReso.y);',
    '  vec2 ndc = (gl_FragCoord.xy * 2.0 - uReso) / m;',
    '  float pixAng = 2.0 * uTan / m;',                       // angle couvert par un pixel
    '  vec3 rdW = normalize(vec3(ndc * uTan, -1.0));',        // caméra en (0, 0, D) vers -z
    '  float c = uRot.x;',
    '  float s = uRot.y;',
    // On tourne le rayon plutôt que l'objet (rotation inverse autour de y).
    '  vec3 ro = vec3(-uDist * s, 0.0, uDist * c);',
    '  vec3 rd = vec3(rdW.x * c - rdW.z * s, rdW.y, rdW.x * s + rdW.z * c);',
    '  vec2 tb = boite(ro, rd);',
    '  float t = max(tb.x, 0.0);',
    '  if (tb.y <= t) { gl_FragColor = vec4(0.0); return; }',  // sortie anticipée : hors de la boîte

    // Sphere tracing, 80 pas au plus. On retient le passage le plus proche
    // (en pixels) pour anticréneler la silhouette des rayons manqués.
    // Près du profil, un rayon rasant au-dessus d'une face plate n'avance que
    // d'une fraction de sa distance à chaque pas : sans les deux gardes
    // ci-dessous il épuise ses 80 pas et devient semi-transparent.
    '  float rmin = 1e4;',
    '  float tmin = t;',
    '  float touche = 0.0;',
    '  float sorti = 0.0;',
    '  for (int i = 0; i < 80; i++) {',
    '    vec3 p = ro + rd * t;',
    '    float d = carte(sdf2(p.xy), p.z);',
    '    float pied = t * pixAng;',
    '    float ratio = d / pied;',
    '    if (ratio < rmin) { rmin = ratio; tmin = t; }',
    '    if (ratio < 0.25) { touche = 1.0; break; }',
    '    float pas = d * 0.9;',                                 // 0,9 : SDF interpolée -> prudence
    // Au-dessus de la dalle |z| <= h (et de sa bande d'anticrénelage) : rien à toucher.
    '    float dz = abs(p.z) - uH - 1.3 * pied;',
    '    if (dz > 0.0) {',
    '      if (p.z * rd.z >= 0.0) { sorti = 1.0; break; }',     // s'éloigne de la dalle : raté définitif
    '      pas = max(pas, dz / abs(rd.z));',                    // saut direct jusqu'à la dalle (rd.z != 0 ici)
    '    }',
    '    t += pas;',
    '    if (t > tb.y) { sorti = 1.0; break; }',
    '  }',
    // Budget épuisé DANS la boîte : le rayon rase une surface -> plein, jamais transparent.
    '  if (sorti < 0.5) touche = 1.0;',
    '  float couv = touche > 0.5 ? 1.0 : 1.0 - smoothstep(0.25, 1.25, rmin);',
    '  if (couv < 0.004) { gl_FragColor = vec4(0.0); return; }',
    '  float th = touche > 0.5 ? t : tmin;',
    '  vec3 p = ro + rd * th;',
    '  float pixU = th * pixAng;',                             // taille d'un pixel à cette distance

    // Normale : direction dans le plan par différences centrées de d2 (pas de
    // 2 texels : gomme les micro-ondulations du contour), puis profil du biseau
    // ANALYTIQUE (le gradient exact de l'extrusion arrondie) : biseau parfaitement
    // lisse. d2 ne dépend pas de z : 5 lectures de texture en tout.
    '  float e = 2.0 * uTexel;',
    '  float dc = sdf2(p.xy);',
    '  vec2 g = vec2(sdf2(p.xy + vec2(e, 0.0)) - sdf2(p.xy - vec2(e, 0.0)),',
    '                sdf2(p.xy + vec2(0.0, e)) - sdf2(p.xy - vec2(0.0, e)));',
    '  g = normalize(g + vec2(1e-5, 0.0));',
    '  float sz = p.z < 0.0 ? -1.0 : 1.0;',
    '  float wx = dc + uR;',
    '  float wy = abs(p.z) - uH + uR;',
    '  vec2 wp = max(vec2(wx, wy), 0.0);',
    '  vec3 n = (wp.x + wp.y > 0.0) ? vec3(g * wp.x, sz * wp.y) : (wx > wy ? vec3(g, 0.0) : vec3(0.0, 0.0, sz));',
    '  n = normalize(n);',

    // Matière : couleurs du logo sur les faces (miroir naturel au dos),
    // bleu-vert profond sur le biseau et la tranche, plus sombre au milieu.
    '  vec2 q = p.xy + uCentre;',
    '  vec3 logo = texture2D(uCoul, vec2(0.5 + q.x, 0.5 - q.y)).rgb;',
    '  logo *= logo;',
    '  float kFace = smoothstep(0.62, 0.97, abs(n.z));',
    '  float kz = smoothstep(0.0, 1.0, clamp(abs(p.z) / uH, 0.0, 1.0));',
    '  vec3 albedo = mix(mix(TEAL_SOMBRE, TEAL, kz), logo, kFace);',
    '  float occl = mix(0.85, 1.0, max(kz, kFace));',          // ombrage doux de la tranche

    // Passage en repère monde (lumières fixes : les reflets glissent sur l'objet).
    '  vec3 nw = vec3(n.x * c + n.z * s, n.y, -n.x * s + n.z * c);',
    '  vec3 V = -rdW;',
    '  float ndv = clamp(dot(nw, V), 0.0, 1.0);',
    // Variation angulaire de la normale sous un pixel (courbure 1/r du biseau).
    '  float flou = smoothstep(-0.1, 0.1, min(wx, wy) / uR) * pixU / uR + 0.002;',

    // Couche de base : diffus enveloppant + spéculaire large et doux.
    '  float w1 = clamp((dot(nw, L1) + 0.35) / 1.35, 0.0, 1.0);',
    '  float w2 = clamp((dot(nw, L2) + 0.20) / 1.20, 0.0, 1.0);',
    '  vec3 diff = (mix(AMB_SOL, AMB_CIEL, nw.y * 0.5 + 0.5) + C1 * w1 + C2 * w2) * occl;',
    '  vec3 H1 = normalize(L1 + V);',
    '  vec3 H2 = normalize(L2 + V);',
    '  float nh1 = max(dot(nw, H1), 0.0);',
    '  float nh2 = max(dot(nw, H2), 0.0);',
    '  vec3 base = albedo * diff + (C1 * pow(nh1, 24.0) + C2 * pow(nh2, 24.0)) * 0.10;',

    // Vernis : Fresnel marqué, reflet très net (exposant 900, élargi si besoin
    // à énergie constante), réflexion douce du studio.
    '  float F = 0.04 + 0.66 * pow(1.0 - ndv, 5.0);',
    '  float nNet = 1.0 / (1.0 / 900.0 + flou * flou);',
    '  float eNet = nNet / 900.0;',
    '  float fh1 = 0.04 + 0.96 * pow(1.0 - clamp(dot(H1, V), 0.0, 1.0), 5.0);',   // clamp : jamais de pow(négatif)
    '  float fh2 = 0.04 + 0.96 * pow(1.0 - clamp(dot(H2, V), 0.0, 1.0), 5.0);',
    '  vec3 net = (C1 * pow(nh1, nNet) * fh1 + C2 * pow(nh2, nNet) * fh2) * 28.0 * eNet;',
    '  vec3 env = studio(reflect(-V, nw), 2.0 * flou);',
    '  vec3 col = base * (1.0 - F) + env * F + net;',
    // Mat (Lynk) : même résultat que la maquette validée (col = albedo * diff),
    // sans spéculaire, vernis ni studio. Un seul programme pour les deux aspects.
    '  col = mix(col, albedo * diff, uMat);',

    // Épaule douce au-dessus de 0,85 (tons moyens intacts), retour en sRGB,
    // sortie prémultipliée.
    '  col = max(col, vec3(0.0));',
    '  vec3 hx = max(col - 0.85, 0.0);',
    '  col = min(col, 0.85) + 0.15 * (1.0 - exp(-hx / 0.15));',
    '  gl_FragColor = vec4(sqrt(col) * couv, couv);',
    '}'
  ].join('\n');

  // ------------------------------------------------------------------ SDF (CPU)
  // Transformée de distance euclidienne exacte 1D (Felzenszwalb–Huttenlocher) :
  // enveloppe inférieure de paraboles, en place sur une ligne ou une colonne.
  function edt1d(g, debut, pas, n, f, v, z) {
    var q, k = 0, r, s, q2;
    v[0] = 0; z[0] = -INF; z[1] = INF; f[0] = g[debut];
    for (q = 1; q < n; q++) {
      f[q] = g[debut + q * pas];
      q2 = q * q;
      do {
        r = v[k];
        s = (f[q] - f[r] + q2 - r * r) / (q - r) / 2;
      } while (s <= z[k] && --k > -1);
      k++;
      v[k] = q; z[k] = s; z[k + 1] = INF;
    }
    for (q = 0, k = 0; q < n; q++) {
      while (z[k + 1] < q) k++;
      r = v[k];
      g[debut + q * pas] = f[r] + (q - r) * (q - r);
    }
  }

  function edt2d(g, n, f, v, z) {
    var i;
    for (i = 0; i < n; i++) edt1d(g, i, n, n, f, v, z);      // colonnes
    for (i = 0; i < n; i++) edt1d(g, i * n, 1, n, f, v, z);  // lignes
  }

  function coder(x) {
    if (x < -1) x = -1; else if (x > 1) x = 1;
    return Math.round(x * 127.5 + 127.5);
  }

  // Pixels RGBA de l'image dessinée (proportions gardées) dans un carré `cote`
  // placé en (decal, decal) d'un canvas `taille` × `taille`.
  function pixels(img, taille, decal, cote) {
    var cv = document.createElement('canvas');
    cv.width = cv.height = taille;
    var cx = cv.getContext('2d');
    cx.imageSmoothingEnabled = true;
    if ('imageSmoothingQuality' in cx) cx.imageSmoothingQuality = 'high';
    var w = img.naturalWidth || img.width, h = img.naturalHeight || img.height, k = cote / Math.max(w, h);
    cx.drawImage(img, decal + (cote - w * k) / 2, decal + (cote - h * k) / 2, w * k, h * k);
    return cx.getImageData(0, 0, taille, taille).data;   // SecurityError si l'image est « étrangère »
  }

  // Demi-côté du cadre (dans le plan de l'axe) pour que le logo ne sorte jamais
  // du canvas, quel que soit l'angle, perspective comprise. Seul le bord compte.
  function cadre(dN, cx, cy, h) {
    var N = N_SDF, t = ETENDUE / N, D = DIST_CAM, A = 48, demi = 0;
    var co = [], si = [], a, i, j, s, d, x, y, z, xr, zr, k;
    for (a = 0; a < A; a++) { co.push(Math.cos(a * 2 * Math.PI / A)); si.push(Math.sin(a * 2 * Math.PI / A)); }
    for (j = 0; j < N; j++) {
      for (i = 0; i < N; i++) {
        d = dN[j * N + i];
        if (d > 1 || d < -1.5) continue;
        x = -ETENDUE / 2 + (i + 0.5) * t - cx;
        y = ETENDUE / 2 - (j + 0.5) * t - cy;
        for (a = 0; a < A; a++) {
          for (s = -1; s <= 1; s += 2) {
            z = s * h;
            xr = x * co[a] + z * si[a];
            zr = -x * si[a] + z * co[a];
            k = D / (D - zr);
            if (Math.abs(xr) * k > demi) demi = Math.abs(xr) * k;
            if (Math.abs(y) * k > demi) demi = Math.abs(y) * k;
          }
        }
      }
    }
    return Math.max(0.1, demi * 1.02 + 2 * t);
  }

  // Texture de couleur : opaque partout (alpha forcé à 255) et couleur étendue de
  // 6 px hors de la silhouette, pour qu'aucun liseré blanc ou sombre n'apparaisse
  // au bord des faces (filtrage bilinéaire). En deux temps (étapes courtes).
  function couleurDebut(src) {
    var T = N_COUL, n = T * T;
    var C = { out: new Uint8Array(n * 4), ok: new Uint8Array(n), vu: new Uint8Array(n), front: [] };
    var out = C.out, ok = C.ok, i, o, x, y;
    for (i = 0; i < n; i++) {
      o = i * 4;
      out[o + 3] = 255;
      if (src[o + 3] >= 128) { out[o] = src[o]; out[o + 1] = src[o + 1]; out[o + 2] = src[o + 2]; ok[i] = 1; }
    }
    for (i = 0; i < n; i++) {
      if (ok[i]) continue;
      x = i % T; y = (i - x) / T;
      if ((x > 0 && ok[i - 1]) || (x < T - 1 && ok[i + 1]) || (y > 0 && ok[i - T]) || (y < T - 1 && ok[i + T])) { C.vu[i] = 1; C.front.push(i); }
    }
