// vu : maj de la dernière version de Google reprise par cette tablette ; avis : modification refusée par Google.
function etatGoogle(){return lire(K_GOOGLE)||{statut:'',at:0,erreur:'',vu:0,avis:''}}
function majEtat(o){var e=etatGoogle();for(var k in o)e[k]=o[k];ecrire(K_GOOGLE,e)}
