// Renvoie une promesse : 'recu' (version de Google reprise), 'envoye', 'refuse', 'ok' (rien à faire) ou 'echec'.
// silencieux : vérification automatique de fond (toutes les 30 s) sans le logo « Synchronisation avec Google ».
function synchroniser(silencieux){
  if(enCours){encore=true;return enCours}
  var g=googlePack();
  if(!g.url||!window.fetch)return Promise.resolve('echec');
  if(!g.code){majEtat({statut:'sanscode',erreur:'Code d’accès de l’atelier à saisir'});return Promise.resolve('echec')}
  var post=function(body){
    var ctl=window.AbortController?new AbortController():null,t=setTimeout(function(){if(ctl)ctl.abort()},30000);
    return fetch(g.url,{method:'POST',body:JSON.stringify(Object.assign({},body,{app:'pack',appareil:appareil(),key:g.code,version:versionPack(),zone:zoneTexte(),etat:etatTexte()})),redirect:'follow',cache:'no-store',signal:ctl?ctl.signal:undefined,pkSilencieux:!!silencieux})
      .then(function(r){return r.json()}).catch(function(){return null}).then(function(r){clearTimeout(t);return r});
  };
