    majEtat({statut:r?'erreur':'horsligne',erreur:e});return 'echec';
  };
  var majDe=function(s){return Number(s&&s.maj)||0};
  // maj = version de Google déjà reprise ici (2026-11-12, lot C) : le nouveau script répond {aJour:true} SANS la
  // configuration si rien n'a changé chez lui (lecture sans verrou). L'ancien script ignore ce champ et renvoie site.
  // Sans copie locale de Google (tablette neuve, données effacées) : lecture complète, jamais « à jour ».
  var vu0=lire(K_SITE)?Number(etatGoogle().vu)||0:0;
  enCours=post(vu0?{operation:'pull',maj:vu0}:{operation:'pull'}).then(function(r){
    if(!r||r.status!==200)return echec(r);
    var dist=r.data.site,local=site(),vu=Number(etatGoogle().vu)||0,depart=majDe(local);
    var ok=function(res,o){o.statut='ok';o.at=Date.now();o.erreur='';majEtat(o);return res};
    // « Déjà à jour » : Google a toujours la version vu. Jamais pris pour « Google n'a rien » (sinon push depuis:0).
    if(r.data.aJour&&!dist){
      if(!local||majDe(local)===vu)return ok('ok',{});
      // Modification faite ici depuis : envoyée avec contrôle de version (depuis = la version de Google connue).
      return post({operation:'push',site:local,depuis:vu}).then(function(p){
        if(!p||p.status!==200)return echec(p);
        if(p.data.refuse)return p.data.site?reprendreS(p.data.site,'refuse','Votre dernière modification de l’Administration n’a pas été enregistrée : la configuration avait changé sur une autre tablette ou dans la Google Sheet. Refaites-la.'):ok('refuse',{});
        if(majDe(site())!==depart){majEtat({vu:majDe(p.data.site),avis:''});encore=true;return ok('envoye',{})}
        return p.data.site?reprendreS(p.data.site,'envoye'):ok('envoye',{});
      });
    }
    function reprendreS(s,res,avis){if(majDe(site())!==depart)return ok('ok',{});ecrire(K_SITE,s);return ok(res,{vu:majDe(s),avis:avis||''})}
    // Version de Google reprise seulement si la configuration n'a pas changé sur la tablette pendant l'échange.
    var reprendre=function(s,res,avis){if(majDe(site())!==depart)return ok('ok',{});ecrire(K_SITE,s);return ok(res,{vu:majDe(s),avis:avis||''})};
    var fichierSeul=!lire(K_SITE)&&local===siteFichier();
    if(dist&&(majDe(local)===vu||majDe(local)===majDe(dist)||fichierSeul)){
      // Rien de modifié ici (ou tablette qui n'a que site.js, jamais envoyé quand Google a déjà une configuration) :
      // on prend la version de Google.
      return majDe(local)===majDe(dist)?ok('ok',{vu:majDe(dist)}):reprendre(dist,'recu');
    }
    if(!local)return ok('ok',{});
    return post({operation:'push',site:local,depuis:dist?vu:0}).then(function(p){
      if(!p||p.status!==200)return echec(p);
      if(p.data.refuse)return reprendre(p.data.site,'refuse','Votre dernière modification de l’Administration n’a pas été enregistrée : la configuration avait changé sur une autre tablette ou dans la Google Sheet. Refaites-la.');
