// --- Machines de la Relève ⇒ zone de la Relève -----------------------------------------------
// Toutes les machines de la Relève (sa liste, Réglages de la Relève ou console › Contenus › Relève) sont dans la
// ou les zones qui proposent la Relève (zone « atelier » du frittage). Liste lue dans la copie que la Relève garde
// sur la tablette (atelier-google-cache) ; vérifié après chaque échange avec Google réussi.
// z.machinesReleve = liste de la Relève déjà reprise : une machine retirée ou renommée dans la Relève quitte la zone.
function machinesReleve(){
  try{var c=lire('atelier-google-cache'),p=c&&c.draft&&JSON.parse(c.draft.payload),m=p&&p.catalog&&p.catalog.machines;
    return Array.isArray(m)&&m.length?m.filter(function(x){return typeof x==='string'&&x}):null}catch(e){return null}
}
// Zone(s) qui reçoivent les machines de la Relève : celles marquées z.lienReleve (Administration › Secteurs et zones),
// sinon la zone d'origine du frittage (id « frittage », appelée « atelier »), sinon la première zone qui propose la Relève.
function zonesReleve(s){
  var avec=s.zones.filter(function(z){return (secteurs()[z.secteur]||{}).releve&&applisZone(s,z).indexOf('releve')>=0});
  var l=avec.filter(function(z){return z.lienReleve===true});
  if(!l.length)l=avec.filter(function(z){return z.id==='frittage'});
  if(!l.length)l=avec.slice(0,1);
  return l.map(function(z){return z.id});
}
function lierMachinesReleve(){
  var rel=machinesReleve(),s=site();
  // Parc machines créé : c'est lui qui donne les machines de la Relève (la console les lui envoie), plus l'inverse.
  if(!rel||!s||!Array.isArray(s.zones)||parcDe(s))return false;
  var n=JSON.parse(JSON.stringify(s)),change=false,egal=function(a,b){return JSON.stringify(a)===JSON.stringify(b)};
  var cibles=zonesReleve(n);
  n.zones.forEach(function(z){
    // Zone qui ne suit plus la Relève (lien passé à une autre zone) : elle rend les machines de la Relève.
    if(cibles.indexOf(z.id)<0){
      if(Array.isArray(z.machinesReleve)){var p=z.machinesReleve;z.machines=(z.machines||[]).filter(function(m){return p.indexOf(m)<0});delete z.machinesReleve;change=true}
      return;
    }
    var avant=Array.isArray(z.machinesReleve)?z.machinesReleve:[],garde=function(m){return avant.indexOf(m)<0&&rel.indexOf(m)<0};
    // Zone « toutes les machines du secteur » : la liste du secteur doit contenir celles de la Relève.
    var ex=(n.machinesSecteurs||{})[z.secteur];
    if(z.machines&&z.machines.length){
      var l=rel.concat(z.machines.filter(garde));
      if(!egal(l,z.machines)){z.machines=l;change=true}
    }
    // Liste du secteur (si elle est saisie) : mêmes ajouts et retraits.
    if(Array.isArray(ex)&&ex.length){
      var e2=ex.filter(garde);rel.forEach(function(m){if(e2.indexOf(m)<0)e2.push(m)});
      // Ordre : celles de la Relève d'abord, comme dans la Relève.
      e2=rel.concat(e2.filter(function(m){return rel.indexOf(m)<0}));
      if(!egal(e2,ex)){n.machinesSecteurs[z.secteur]=e2;change=true}
    }
    if(!egal(avant,rel)){z.machinesReleve=rel.slice();change=true}
  });
