  return change;
}

// --- État de la tablette (Administration › Cette tablette ; résumé envoyé à la Sheet pour les alertes de la console) ---
// Données pas encore envoyées à Google : les 4 applis notent « dirty » dans leur liaison Google (une clé par secteur),
// la Relève garde ses relèves / consignes faites hors ligne dans « atelier-google-hors-ligne ».
var NOMS_ATTENTE={lancements:'Lancements',releve:'Relève',taches:'Tâches',fiches:'Fiches réflexes',maintenance:'Maintenance',procedures:'Procédures',fours:'Fours',liaison:'Liaison'};
