var APP_DE_CLE={'taches-atelier':'taches','fiches-reflexes':'fiches','maintenance-n1':'maintenance','procedures':'procedures'};
function enAttente(){
  var l={},ordre=[];
  try{
    var o=lire('atelier-google-hors-ligne');
    // Relève : relèves / consignes faites hors connexion, saisie en cours, photos pas encore envoyées.
    var ph=lire('atelier-photos-a-envoyer');
    var q=(o?(o.queue||[]).length+(o.done||[]).length+(o.draft!=null?1:0):0)+(Array.isArray(ph)?ph.length:0);
    if(q){l.releve=q;ordre.push('releve')}
    var la=lire('lancements-attente');if(Array.isArray(la)&&la.length){l.lancements=la.length;ordre.push('lancements')}
    var lf=lire('fours-attente');if(Array.isArray(lf)&&lf.length){l.fours=lf.length;ordre.push('fours')} // Fours (2026-10-22)
    // Liaison (2026-10-23) : une file d'attente par secteur (« liaison-attente », « liaison-attente-fraisage »…).
    var nli=0;for(var j=0;j<localStorage.length;j++){var kli=localStorage.key(j)||'';if(/^liaison-attente(-[a-z0-9-]+)?$/.test(kli)){var ali=lire(kli);if(Array.isArray(ali))nli+=ali.length}}
    if(nli){l.liaison=nli;ordre.push('liaison')}
    for(var i=0;i<localStorage.length;i++){
      var k=localStorage.key(i),m=CLES_ATTENTE.exec(k||'');if(!m)continue;
      var v=lire(k),a=APP_DE_CLE[m[1]];
