// Nom actuel d'une machine renommée dans le parc (anciens noms gardés dans sa fiche) : opérations, règles, files…
// D'abord une machine dont c'est le nom ACTUEL, ensuite seulement les anciens noms (2026-10-15) : après un échange
// de noms (A↔B), « A » est le nom actuel d'une machine ET un ancien nom de l'autre ; il ne faut pas le traduire.
function actuelDans(l,n){
  var i;l=l||[];
  for(i=0;i<l.length;i++)if(l[i]&&l[i].nom===n)return n;
  for(i=0;i<l.length;i++)if(l[i]&&(l[i].anciens||[]).indexOf(n)>=0)return l[i].nom;
  return n;
}
// Personne renommée (site.personnes[].anciens, 2026-10-17) : son ancien nom (roulement, règles, congés du calendrier de
// maintenance) est lu comme le nouveau. Un nom porté aujourd'hui par quelqu'un n'est jamais traduit.
function nomPersonne(s,n){
  var l=s&&Array.isArray(s.personnes)?s.personnes:[];
  if(typeof n!=='string'||l.some(function(p){return p&&p.nom===n}))return n;
  // Identifiant de la personne (p…, lot5-identifiants, 2026-10-17) : accepté partout où un nom est attendu.
  for(var j=0;j<l.length;j++)if(l[j]&&l[j].id===n&&typeof l[j].nom==='string'&&l[j].nom)return l[j].nom;
  for(var i=0;i<l.length;i++){var p=l[i];if(p&&Array.isArray(p.anciens)&&p.anciens.indexOf(n)>=0)return p.nom}
  return n;
}
function nomActuel(s,n){var p=parcDe(s);return p?actuelDans(p.machines,n):n}
// Nom actuel d'un type de machine renommé (site.parc.types[].anciens, 2026-10-15) : versions et règles par type.
function typeActuel(s,n){var p=parcDe(s);return p?actuelDans(p.types,n):n}
// ÉCHANGE DE NOMS INTERDIT (décision du responsable, 2026-10-15) : une machine ne peut pas prendre un nom porté
// (anciens) par une AUTRE machine, l'historique étant rangé par nom. Renvoie le message de refus, sinon ''.
// Même fonction dans la console (console.html pkConflitAnciens, serveur.mjs parcPropre) : les garder identiques.
function conflitAnciensNoms(l){
  var k=function(v){return String(v==null?'':v).replace(/\s+/g,' ').trim().toLocaleLowerCase('fr')};
  l=l||[];
  for(var i=0;i<l.length;i++){var c=k(l[i]&&l[i].nom);if(!c)continue;
    for(var j=0;j<l.length;j++)if(j!==i&&l[j]&&(l[j].anciens||[]).some(function(a){return k(a)===c}))
      return '« '+String(l[i].nom).trim()+' » a été le nom de la machine « '+l[j].nom+' » : choisissez un nom neuf (l’historique est rangé par nom).';
  }
  return '';
}
// Machines d'un secteur. Parc : celles en service de ce secteur. Sinon : celles ajoutées au secteur dans
// l'Administration (site.machinesSecteurs) + celles de toutes ses zones (z.machines) ; rien du tout : le fichier du secteur.
function machinesSecteur(s,sec){
  var p=parcDe(s);
  if(p)return p.machines.filter(function(m){return enService(m)&&m.secteur===sec}).map(function(m){return m.nom});
  var l=[],add=function(m){if(typeof m==='string'&&m&&l.indexOf(m)<0)l.push(m)};
  ((s&&s.machinesSecteurs||{})[sec]||[]).forEach(add);
  ((s&&s.zones)||[]).forEach(function(z){if(z.secteur===sec)(z.machines||[]).forEach(add)});
  return l.length?l:((secteurs()[sec]||{}).machines||[]).slice();
}
function secteurs(){return window.PACK_SECTEURS||{}}
// Applications choisies pour une zone. Procédures est arrivée après les zones déjà enregistrées sur Google : tant
// qu'aucun administrateur n'a revu la configuration (site.procAjoutee absent), elle est proposée partout où la
// Maintenance l'est. Le drapeau est posé à la première modification de l'Administration : un décochage reste respecté.
function applisZone(s,z){
  var l=((z&&z.applis)||[]).slice();
  if(s&&!s.procAjoutee&&l.indexOf('maintenance')>=0&&l.indexOf('procedures')<0)l.push('procedures');
  // Lancements machines (2026-10-02) : proposée d'office là où il y a la Relève (zones de l'atelier du frittage).
  if(s&&!s.lancAjoutee&&l.indexOf('releve')>=0&&l.indexOf('lancements')<0)l.push('lancements');
  return l;
}
// Applis réservées à certains secteurs (champ « secteurs » de APPLIS, 2026-11-12, campagne testeur B10) : Fours ne
// concerne que le frittage ; cochée par erreur sur une zone du fraisage, sa tuile n'apparaît plus.
function appliPourSecteur(a,sec){return !a.secteurs||a.secteurs.indexOf(sec)>=0}
// Applications proposées à une personne sur une zone : celles choisies pour la zone, permises par son rôle.
function applisPour(s,z,p){
  var sec=secteurs()[z.secteur]||{},cache=droitsPour(s,p,z.secteur).applis,l=applisZone(s,z);
  return applisSite(s).filter(function(a){
    return l.indexOf(a.id)>=0&&a.roles.indexOf(p.role)>=0&&(!a.releve||sec.releve)&&appliPourSecteur(a,z.secteur)&&cache.indexOf(a.id)<0;
  });
}
// Couleur principale choisie dans l'Administration › Apparence (sinon le bleu-vert d'origine).
function couleurSite(s){var c=s&&s.apparence&&s.apparence.couleur;return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#0b8a96'}
// Fond d'un bouton plein à texte blanc (2026-11-12, campagne designer A3) : blanc sur #0B8A96 = 4,1:1, trop peu ; la
// couleur par défaut devient le foncé de la charte #065E66 (7,5:1), une couleur choisie est foncée jusqu'à 4,5:1 au moins.
function fondTexteBlanc(c){
  if(String(c).toLowerCase()==='#0b8a96')return '#065E66';
  var v=[1,3,5].map(function(i){return parseInt(String(c).slice(i,i+2),16)});
  var lum=function(x){return x.map(function(k){k/=255;return k<=0.03928?k/12.92:Math.pow((k+0.055)/1.055,2.4)}).reduce(function(s,k,i){return s+k*[0.2126,0.7152,0.0722][i]},0)};
  for(var n=0;n<30&&1.05/(lum(v)+0.05)<4.5;n++)v=v.map(function(k){return Math.floor(k*0.92)});
  return '#'+v.map(function(k){return ('0'+k.toString(16)).slice(-2)}).join('');
}
// Applications avec les noms, textes et l'ordre choisis dans l'Administration › Apparence (site.apparence.tuiles).
function applisSite(s){
  var t=s&&s.apparence&&s.apparence.tuiles||{};
  return APPLIS.map(function(a,i){
    var o=t[a.id]||{},c={};for(var k in a)c[k]=a[k];
    if(o.nom)c.nom=String(o.nom);if(o.texte)c.texte=String(o.texte);
    c.ordre=isFinite(o.ordre)?Number(o.ordre):i;return c;
  }).sort(function(a,b){return a.ordre-b.ordre});
}

// Personne connectée avec son code (session réelle, fermée après l'inactivité réglée).
function sessionCode(){
  var s=site(),t=tablette(),se=lire(K_SESS);
  if(!s||!t||!se)return null;
  var p=personne(s,se.pid),z=zoneDe(s,t.zone);
  if(!p||!z||!p.code||!voitZone(p,z))return null;
  var max=(Number(s.inactivite)||0)*60000;
  if(max&&Date.now()-(Number(se.vu)||0)>max)return null;
  return {site:s,tablette:t,zone:z,personne:p};
}
// Mode de la tablette (Administration › Cette tablette) : 'code' (chacun s'identifie), 'personne' (tablette
// personnelle, ouverte au nom de t.personne sans code) ou 'libre' (sans code, affichage du profil t.profil = un rôle ;
// dans les applications, chacun choisit son prénom). Sans session par code, la tablette ouvre cette session « de base ».
function sessionTablette(){
  var s=site(),t=tablette();
  if(!s||!t||!t.mode||t.mode==='code')return null;
  var z=zoneDe(s,t.zone);if(!z)return null;
  if(t.mode==='personne'){var p=personne(s,t.personne);return p&&voitZone(p,z)?{site:s,tablette:t,zone:z,personne:p,sansCode:true}:null}
  if(t.mode==='libre'){var r=RANG[t.profil]!=null?t.profil:'operateur';return {site:s,tablette:t,zone:z,personne:{id:'',nom:'',role:r,zones:[]},sansCode:true,libre:true}}
  return null;
}
function session(){return sessionCode()||sessionTablette()}
// Une vraie personne qui donne son code reprend la main : la session « douchette » éventuelle est fermée.
function ouvrirSession(pid){ecrire(K_DOUCH,null);ecrire(K_SESS,{pid:pid,debut:Date.now(),vu:Date.now()})}
// Une session expirée n'est jamais prolongée (sinon toucher l'écran le lendemain la ferait revivre).
// Dernière activité sur la tablette (accueil ou application) : sert aussi à la mise à jour automatique (en-ligne.js),
// qui s'installe après 2 minutes sans aucun toucher même si une application est restée ouverte.
function toucher(){try{localStorage.setItem('pack-activite',String(Date.now()))}catch(e){}var se=lire(K_SESS);if(!se)return;if(!sessionCode()){ecrire(K_SESS,null);return}se.vu=Date.now();ecrire(K_SESS,se)}
function fermerSession(){ecrire(K_SESS,null)}
// Écran télé affiché (Maintenance niveau 1) : la session reste ouverte tant qu'il est à l'écran, sans compter comme une
// activité (la mise à jour automatique peut toujours s'installer). Une session déjà expirée n'est pas prolongée.
function garderSession(){var se=lire(K_SESS);if(se&&sessionCode()){se.vu=Date.now();ecrire(K_SESS,se)}}

// --- Scan à la douchette quand l'appli n'est pas ouverte (2026-11-19) ------------------------------------------------
// Problème réel : la douchette scanne (opérateurs sans la tablette en main) mais Lancements / Fours a été fermée
// (fin d'une session à code, mise à jour, retour à l'accueil) : les scans tombaient sur l'accueil et étaient perdus.
// Désormais l'accueil (ou une autre appli) reconnaît l'étiquette, ouvre l'appli concernée et lui transmet le scan.
// Qui agit : la personne connectée avec son code ; sinon la session de base d'une tablette personnelle ou en accès libre
// (comme si on avait touché la tuile) ; sinon (tablette « chacun son code », personne connecté) une session
// « douchette » : cette appli seulement, au nom « Douchette », retour à l'accueil après 2 min sans nouveau scan.
// Elle est rangée À PART (K_DOUCH) : elle ne prolonge ni ne fait revivre une session à code.
var APPLIS_SCAN=['lancements','fours'];
// Appli permise sur la zone pour quelqu'un sans nom (rôle opérateur) : zone, secteur, « Qui voit quoi ».
// Lancements : ses étiquettes ne servent que dans le frittage (l'appli ignore la douchette ailleurs, HORS_FRITTAGE).
function appliScanPermise(s,z,app,p){
  if(!s||!z||APPLIS_SCAN.indexOf(app)<0)return false;
  if(app==='lancements'&&z.secteur!=='frittage')return false;
  return applisPour(s,z,p||{id:'',role:'operateur'}).some(function(a){return a.id===app});
}
function sessionDouchette(app){
  var s=site(),t=tablette(),d=lire(K_DOUCH);
  if(!s||!t||!d||d.app!==app||(t.mode&&t.mode!=='code')||d.zone!==t.zone)return null;
  if(Date.now()-(Number(d.vu)||0)>DOUCHETTE_MAX)return null;
  var z=zoneDe(s,t.zone);if(!appliScanPermise(s,z,app))return null;
  return {site:s,tablette:t,zone:z,personne:{id:'',nom:'Douchette',role:'operateur',zones:[]},sansCode:true,douchette:true};
}
function finDouchette(){ecrire(K_DOUCH,null)}
// Nom de l'appli tel qu'affiché sur la tuile (Apparence).
function nomAppli(s,id){var a=applisSite(s).filter(function(x){return x.id===id})[0];return a?a.nom:id}
// Que faire d'un scan pour l'appli app ? {ok:true, douchette:bool} ou {ok:false, msg} (message court pour l'écran).
function decisionScan(app){
  var s=site(),t=tablette(),z=t&&zoneDe(s,t.zone);
  if(!z)return {ok:false,msg:'Scan non fait : la tablette n’est pas encore installée.'};
  var nom=nomAppli(s,app),se=sessionCode()||sessionTablette();
  if(se){
    if(appliScanPermise(s,z,app,se.personne))return {ok:true,douchette:false};
    return {ok:false,msg:'Étiquette « '+nom+' » scannée : cette application n’est pas proposée '+(se.libre?'':'pour '+se.personne.nom+' ')+'sur cette tablette. Rien n’a été fait.'};
  }
  if(!appliScanPermise(s,z,app))return {ok:false,msg:'Étiquette « '+nom+' » scannée : cette application n’est pas proposée sur cette tablette. Rien n’a été fait.'};
  return {ok:true,douchette:true};
}
// Prépare l'ouverture : session douchette (ou fin de l'ancienne) et scan à transmettre (lu par l'appli, 1 min au plus).
function preparerScan(x,d){
  if(d.douchette)ecrire(K_DOUCH,{app:x.app,zone:tablette().zone,debut:Date.now(),vu:Date.now()});else finDouchette();
  ecrire(K_SCAN,{app:x.app,texte:x.texte,at:Date.now()});
}
// Appli reprise sous la session de base (tablette en accès libre ou personnelle) quand une session à code finit
// (2026-11-19, cas réel : un administrateur règle la tablette libre, ouvre Lancements, 15 min après l'appli se fermait).
// Seulement Lancements et Fours (écrans qui restent affichés pour la douchette), et si la session de base y a droit.
function repriseBase(app){
  if(APPLIS_SCAN.indexOf(app)<0||sessionCode())return false;
  var b=sessionTablette();return !!(b&&appliScanPermise(b.site,b.zone,app,b.personne));
}

// Lecture des étiquettes Lynk à la douchette (lecteur Bluetooth en « clavier »), pour l'accueil et pour passer d'une appli
// à l'autre. COPIE du bloc <douchette> de Fours / Lancements (même seuils, mêmes conversions de clavier) : les garder
// identiques. Ici on ne fait que reconnaître l'étiquette et son appli ; c'est l'appli qui la lit vraiment ensuite.
var DCH={ecart:60,silence:110,min:5,max:120};
var DCH_TOUCHES=(function(){
  var t={
    Backquote:['`','~','²',''],Digit1:['1','!','&','1'],Digit2:['2','@','é','2'],Digit3:['3','#','"','3'],Digit4:['4','$',"'",'4'],
    Digit5:['5','%','(','5'],Digit6:['6','^','-','6'],Digit7:['7','&','è','7'],Digit8:['8','*','_','8'],Digit9:['9','(','ç','9'],
    Digit0:['0',')','à','0'],Minus:['-','_',')','°'],Equal:['=','+','=','+'],BracketLeft:['[','{','',''],BracketRight:[']','}','$','£'],
    Backslash:['\\','|','*','µ'],Semicolon:[';',':','m','M'],Quote:["'",'"','ù','%'],Comma:[',','<',';','.'],Period:['.','>',':','/'],
    Slash:['/','?','!','§'],IntlBackslash:['\\','|','<','>']
  };
  'abcdefghijklmnopqrstuvwxyz'.split('').forEach(function(l){
    var fr={a:'q',q:'a',z:'w',w:'z',m:','}[l]||l;
    t['Key'+l.toUpperCase()]=[l,l.toUpperCase(),fr,l==='m'?'?':fr.toUpperCase()];
  });
  return t;
})();
function dchTable(de,vers){
  var m={};
  Object.keys(DCH_TOUCHES).forEach(function(k){var x=DCH_TOUCHES[k];for(var s=0;s<2;s++){var a=x[de+s],b=x[vers+s];if(a&&b&&!Object.prototype.hasOwnProperty.call(m,a))m[a]=b}});
  return m;
}
var DCH_CONV=null;
function dchConvertir(txt,m){var o='';for(var i=0;i<txt.length;i++){var c=txt.charAt(i);o+=Object.prototype.hasOwnProperty.call(m,c)?m[c]:c}return o}
function dchCodes(codes,col){var o='';for(var i=0;i<codes.length;i++){var x=DCH_TOUCHES[codes[i][0]],c=x&&x[col+(codes[i][1]?1:0)];if(!c)return '';o+=c}return o}
function dchCasse(t){return t.replace(/[a-zA-Z]/g,function(c){var u=c.toUpperCase();return c===u?c.toLowerCase():u})}
// Étiquettes reconnues : Lancements « DAG-L:<PREP|PRETE|LANCE|FIN>.<id> », Fours « DAG-P:<n°> » et « DAG-M:<id> ».
var DCH_ETIQ=[['lancements',/^DAG-L:(PREP|PRETE|LANCE|FIN)\.[A-Za-z0-9_.-]{1,64}$/i],['fours',/^DAG-P:.{1,60}$/i],['fours',/^DAG-M:[A-Za-z0-9_.-]{1,64}$/]];
// Texte d'une rafale → {app, texte} (texte remis dans la bonne disposition de clavier) ou null.
function appliDuScan(txt,codes){
  txt=String(txt==null?'':txt);
  if(!DCH_CONV)DCH_CONV={frUs:dchTable(2,0),usFr:dchTable(0,2)};
  var e=[txt,dchConvertir(txt,DCH_CONV.frUs),dchConvertir(txt,DCH_CONV.usFr)];
  if(codes&&codes.length===txt.length)e.push(dchCodes(codes,0),dchCodes(codes,2));
  e=e.concat(e.map(dchCasse));
  for(var i=0;i<e.length;i++){var t=String(e[i]||'').trim();
    for(var j=0;j<DCH_ETIQ.length;j++)if(DCH_ETIQ[j][1].test(t))return {app:DCH_ETIQ[j][0],texte:t};
  }
  return null;
}
var DCH_IGNOREES=/^(Shift|CapsLock|NumLock|ScrollLock|Fn|FnLock|Symbol|SymbolLock|Hyper|Super)$/;
// Lecteur : o.lu(x) reçoit chaque étiquette reconnue (renvoie true si elle est prise en charge) ; o.lent() : repli
// « douchette lente » permis (hors champ de saisie) ; o.debut() / o.fin(n) : début et fin d'une rafale rapide (pavé du code).
// touche(e) renvoie {suite:true} pour une touche qui continue une rafale, {fin:true} si l'Entrée / Tab termine une étiquette
// prise en charge (à retenir). champ(texte) : texte lu dans un champ caché (Android : touches sans nom).
function Lecteur(o){
  var r=null,lent={txt:'',codes:[],t:0},minS=0,minL=0,dernier={t:'',at:0};
  function rendre(txt,codes){
    var x=appliDuScan(txt,codes);if(!x)return false;
    if(dernier.t===x.texte&&Date.now()-dernier.at<1500)return true; // même scan déjà lu par un autre chemin
    dernier={t:x.texte,at:Date.now()};
    return !!o.lu(x);
  }
  function finir(){var x=r;r=null;if(!x||x.txt.length<DCH.min)return false;if(o.fin)o.fin(x.txt.length);var ok=rendre(x.txt,x.codes);if(ok)lentVider();return ok}
  function lentVider(){lent.txt='';lent.codes=[];clearTimeout(minL)}
  function lentFin(){var x=lent.txt,c=lent.codes;lentVider();return x.length>=DCH.min&&rendre(x,c)}
  function silence(){if(r&&performance.now()-r.t>=DCH.silence)finir()}
  return {
    touche:function(e){
      var key=String(e.key||''),t=e.timeStamp>0&&e.timeStamp<1e11?e.timeStamp:performance.now(),res={};
      if(e.ctrlKey||e.altKey||e.metaKey){r=null;return res}
      if(DCH_IGNOREES.test(key))return res;
      clearTimeout(minS);
      if(r&&t-r.t>DCH.ecart){if(t-r.t>=DCH.silence)finir();else r=null}
      var lentOk=!o.lent||o.lent();
      if(key==='Enter'||key==='Tab'){
        if(r){if(finir())res.fin=true}
        else if(lentOk&&lent.txt&&t-lent.t<1500&&lentFin())res.fin=true;
        lentVider();return res;
      }
      if(key.length!==1||e.repeat){r=null;return res}
      if(!r){r={txt:'',codes:[],t:t};if(o.debut)o.debut()}else res.suite=true;
      r.txt+=key;r.codes.push([String(e.code||''),!!e.shiftKey]);r.t=t;
      if(r.txt.length>DCH.max)r=null;
      if(r)minS=setTimeout(silence,DCH.silence+15);
      if(lentOk){
        if(t-lent.t>1500)lentVider();
        lent.txt+=key;lent.codes.push([String(e.code||''),!!e.shiftKey]);lent.t=t;clearTimeout(minL);
        minL=setTimeout(function(){if(!r&&lent.txt&&appliDuScan(lent.txt,lent.codes))lentFin()},700);
      }
      return res;
    },
    champ:function(v){v=String(v||'').trim();return v.length>=DCH.min&&rendre(v,null)},
    // Rafale (ou suite lente) en cours : on attend sa fin avant de quitter une appli.
    enCours:function(){return !!r||(!!lent.txt&&performance.now()-lent.t<900)}
  };
}

// Fichier d'un secteur, chargé pendant la lecture de la page (marche aussi en file://, contrairement à fetch).
function chargerSecteur(id,base){
  if(!/^[a-z0-9-]+$/.test(id||'')||secteurs()[id]||!base)return;
  document.write('<script src="'+new URL('secteurs/'+id+'.js',base).href+'"><\/script>');
}
// Pack en un seul fichier (Pack-Tablettes.html, construit par construire-unique.mjs) : tout est déjà dans la page,
