var BASE='';
try{if(!UNIQUE)BASE=new URL('../',me&&me.src?me.src:location.href).href}catch(e){}

// --- « La tablette charge » : logo Lynk qui tourne (logo Lynk 128 px depuis le 2026-11-05) -----------------------
// LOGO_CHARGE sert aussi de logo à l'écran télé de Lancements quand l'Apparence n'a pas de logo.
// Pendant un échange avec Google (synchronisation, enregistrement) qui dure plus de 0,4 s, un petit logo tourne en bas à
// droite de l'écran (accueil et applications). Il ne gêne rien (on peut toucher au travers) et disparaît à la fin.
var LOGO_CHARGE='data:image/png;base64,';
function styleCharge(){
  if(document.getElementById('pk-charge-style')||!document.head)return;
  var st=document.createElement('style');st.id='pk-charge-style';
  // Logo de chargement en 3D (2026-11-10, « tous les logos qui tournent en 3D ») : rotation avec perspective et ombre.
