// Dans le pack, chaque application est reliée d'office à la Google Sheet de son secteur : plus de « Connecter »
// à faire appli par appli (sinon la Relève d'une tablette neuve n'a ni équipes ni opérateurs).
// Une connexion déjà enregistrée vers la même adresse avec le même code n'est pas touchée ; vers une autre adresse
// ou avec un autre code, elle est remplacée (voir plus bas).
function connecterGoogle(){
  var g=window.PACK.google,cles={releve:'atelier-google',taches:'taches-atelier-google',fiches:'fiches-reflexes-google',maintenance:'maintenance-n1-google',procedures:'procedures-google',lancements:'lancements-google',fours:'fours-google',liaison:'liaison-google',tableau:'tableau-bord-atelier-v1-google'};
