  // Lancements : une seule Sheet, l'appli lit « lancements-google » SANS suffixe (Lancements.html K_LIEN, 2026-10-15).
  // Fours (2026-10-22) : une seule Sheet aussi (fours du frittage), « fours-google » sans suffixe.
  if(APPLI!=='releve'&&APPLI!=='tableau'&&APPLI!=='lancements'&&APPLI!=='fours')k+=window.PACK.suffixe;
  // En essai, une liaison restée vers une adresse qui n'est pas localhost (vrai Google) est retirée ; elle compte
  // comme une liaison REMPLACÉE (les données locales viennent du vrai Google : elles ne partent pas dans l'imitation).
  var retiree=null;
  if(essai()){var vieille=lire(k);if(vieille&&vieille.url&&!googleLocal(vieille.url)){retiree=vieille;try{localStorage.removeItem(k);console.warn('[Pack essai] Liaison Google retirée ('+k+') : '+vieille.url)}catch(e){}}}
  if(!g.url||!g.code)return;
  var code=String(g.code).trim().toUpperCase(),deja=lire(k);
  // Déjà reliée à cette Sheet : on n'y touche pas. Autre adresse ou autre code (zone changée, Sheet corrigée
  // dans l'Administration) : la liaison est remplacée. Dans le pack, une appli déconnectée est reliée de nouveau.
  if(deja&&deja.url===g.url&&String(deja.code||deja.key||'').toUpperCase()===code)return;
  if(APPLI==='releve'){ecrire(k,{url:g.url,key:code});return}
  if(APPLI==='tableau'){ecrire(k,{url:g.url,code:code,on:true});return}
  var avant=deja&&deja.url?deja:retiree;
  if(!avant){
    // a) Première liaison de l'appli sur cette tablette : « dirty » (comme avant le 2026-10-15). Un secteur encore
    //    vide chez Google reçoit les contenus de départ ; s'il a déjà des données, la fusion de l'appli les garde.
    ecrire(k,{url:g.url,code:code,rev:0,dirty:true,sent:{},miss:{}});
