// Copies DATÉES « <clé>-avant-changement-sheet-AAAAMMJJ-HHMMSS » (2026-10-15) : un 2e changement n'écrase jamais
// la copie d'avant (les anciennes copies sans date restent lisibles dans Administration › Cette tablette).
// Tout ou rien : si une copie échoue, les copies déjà faites sont retirées, les données restent en place → false.
function mettreDeCote(cles){
  var d=new Date(),p=function(n){return ('0'+n).slice(-2)};
  var date=d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'-'+p(d.getHours())+p(d.getMinutes())+p(d.getSeconds());
  var faites=[];
  try{
    cles.forEach(function(c){
      var v=localStorage.getItem(c);if(v==null)return;
      var dest=c+'-avant-changement-sheet-'+date,n=2;
      while(localStorage.getItem(dest)!=null)dest=c+'-avant-changement-sheet-'+date+'-'+(n++);
      localStorage.setItem(dest,v);
      if(localStorage.getItem(dest)!==v)throw new Error('copie incomplète');
      faites.push([c,dest]);
    });
  }catch(e){
    faites.forEach(function(f){try{localStorage.removeItem(f[1])}catch(x){}});
    console.warn('[Pack] Changement de Google Sheet refusé : copie impossible ('+e.message+')');
    return false;
  }
  faites.forEach(function(f){
    try{localStorage.removeItem(f[0])}catch(e){}
    console.warn('[Pack] Changement de Google Sheet : '+f[0]+' mis de côté dans '+f[1]);
  });
  return true;
}
