else{window.__packConnecter=connecterGoogle;document.write('<script>window.__packConnecter&&window.__packConnecter()<\/script>')}

// Vérifie le droit à l'application une fois le secteur chargé (la relève dépend du secteur).
document.addEventListener('DOMContentLoaded',function(){
  // L'administrateur ouvre le tableau de bord sur toutes les tablettes (il l'a sur son accueil), sauf s'il est masqué.
  var admTableau=APPLI==='tableau'&&S.personne.role==='admin'&&!S.libre&&droitsPour(S.site,S.personne,S.zone.secteur).applis.indexOf('tableau')<0;
  if(!autorisee||!admTableau&&!applisPour(S.site,S.zone,S.personne).some(function(a){return a.id===APPLI})){
    allerAccueil('Cette application n’est pas proposée pour vous sur cette tablette.');return;
  }
  if(INTEGRE)return;
  var bar=document.createElement('div');
  bar.id='pack-bar';
  // Barre collante en haut (2026-11-12, campagne tablette B5) : ⌂ Accueil reste visible quand on fait défiler l'appli ;
  // l'en-tête collant de l'appli (.top) se range juste dessous (--pk-bar-h, mesuré plus bas).
  bar.innerHTML='<style>#pack-bar{position:sticky;top:0;z-index:40;display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:6px 12px;background:#15242b;color:#fff;font:15px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}'+
    '.top{top:var(--pk-bar-h,0px)!important}'+
    '#pack-bar button{border:0;border-radius:10px;padding:8px 14px;min-height:44px;font:inherit;font-weight:600;cursor:pointer}'+
    '#pack-bar .pk-home{background:'+fondTexteBlanc(couleurSite(S.site))+';color:#fff}#pack-bar .pk-out{background:#2c3e46;color:#fff;margin-left:auto}#pack-bar span{opacity:.85}'+
    '@media print{#pack-bar{display:none}}</style>'+
    '<button class="pk-home" type="button"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="vertical-align:-3px;margin-right:6px"><path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"/><path d="M3 10a2 2 0 0 1 .709-1.528l7-6a2 2 0 0 1 2.582 0l7 6A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>Accueil</button><span></span><button class="pk-out" type="button">Se déconnecter</button>';
  bar.querySelector('span').textContent=(S.douchette?'Douchette (scan sans code)':S.libre?'Accès libre':S.personne.nom)+' · '+S.zone.nom+(S.tablette.nom?' · '+S.tablette.nom:'');
  bar.querySelector('.pk-home').onclick=window.PACK.accueil;
  // Tablette sans code : pas de déconnexion (on revient simplement à l'accueil).
  if(S.sansCode)bar.querySelector('.pk-out').remove();else bar.querySelector('.pk-out').onclick=window.PACK.quitter;
  document.body.insertBefore(bar,document.body.firstChild);
  // Hauteur de la barre (une ou deux lignes selon la largeur) : l'en-tête collant de l'appli se place dessous.
  var hauteur=function(){document.documentElement.style.setProperty('--pk-bar-h',(bar.offsetParent?bar.offsetHeight:0)+'px')};
  hauteur();
  if(window.ResizeObserver)new ResizeObserver(hauteur).observe(bar);else window.addEventListener('resize',hauteur);
  // Mode télé (barre cachée, offsetParent null) : l'en-tête revient en haut.
  if(window.MutationObserver)new MutationObserver(hauteur).observe(document.body,{attributes:true,attributeFilter:['class']});
});
// Déconnexion automatique après le temps d'inactivité réglé pour le site.
var dernier=0,sortie=false;
// Session fermée, ou passée à une autre personne (fin d'une connexion par code sur une tablette sans code) : retour.
// Renvoie false si l'application ne doit plus rien faire (retour à l'accueil en cours).
function verifierSession(){
  if(sortie)return false;
  var c=sessionAppli();
  if(c&&c.personne.id===S.personne.id&&c.personne.role===S.personne.role&&!!c.douchette===!!S.douchette)return true;
  // Appli affichée dans l'accueil (INTEGRE) : c'est l'accueil qui se ferme, on ne bloque rien ici.
  if(INTEGRE){fermerSession();return true}
  sortie=true;
  // Une session douchette finie n'a pas de session à code à fermer (une personne a pu se connecter entre-temps).
  if(!S.douchette)fermerSession();
  quitterApp();
  return false;
}
// Sortie de l'appli (2026-11-19). Une rafale de douchette en cours n'est pas coupée : on attend sa fin (2 s au plus) ;
// si c'était une étiquette, elle est transmise à l'appli qui s'ouvre (sinon les touches suivantes tombaient sur
// l'accueil et le scan était perdu). Puis : reprise sous la session de base (tablette libre / personnelle, Lancements
// et Fours), sinon retour à l'accueil.
var attenteSortie=0,scanSortie=null;
function quitterApp(){
  if(lecteurApp&&lecteurApp.enCours()&&attenteSortie++<14){setTimeout(quitterApp,150);return}
  var x=scanSortie;scanSortie=null;
  if(x){var m=ouvrirScan(x);if(m===true)return;if(m){allerAccueil(m);return}}
  if(repriseBase(APPLI)){rouvrirAppli(APPLI);return}
  allerAccueil(S.douchette?'':'Déconnexion après inactivité.');
}
function fichierDe(id){var a=APPLIS.filter(function(x){return x.id===id})[0];return a?BASE+a.fichier:''}
function rouvrirAppli(id){
  if(UNIQUE){try{window.parent.PackUnique.ouvrir(id)}catch(e){allerAccueil('')}return}
  location.replace(fichierDe(id));
}
// Étiquette d'une appli à ouvrir (autre appli, ou appli quittée) : true si elle s'ouvre, sinon le message de refus.
function ouvrirScan(x){
  var d=decisionScan(x.app);
  if(!d.ok)return d.msg;
  preparerScan(x,d);rouvrirAppli(x.app);
  return true;
}
// Scan transmis par l'accueil (K_SCAN, valable 1 min) ou relayé par l'accueil quand le clavier est resté sur lui.
var surScanFn=null;
function scanAttendu(){
  var x=lire(K_SCAN);if(!x)return null;
  if(x.app!==APPLI)return null;
  ecrire(K_SCAN,null);
  return Date.now()-(Number(x.at)||0)<60000&&typeof x.texte==='string'?{app:x.app,texte:x.texte}:null;
}
function surScan(fn){surScanFn=typeof fn==='function'?fn:null;var x=surScanFn&&scanAttendu();if(x)surScanFn(x)}
window.__packScan=function(x){
  if(sortie||!x||x.app!==APPLI||!surScanFn)return false;
  scanFait();surScanFn({app:x.app,texte:String(x.texte||'')});return true;
};
// L'accueil (pack en un fichier) fait vérifier la session par l'appli ouverte : une seule logique de sortie.
window.__packVerifier=function(){verifierSession()};
// Session douchette : retour à l'accueil 2 min après le dernier scan (minuteur précis, relancé à chaque scan).
var minDouchette=0;
function armerDouchette(){
  clearTimeout(minDouchette);if(!S.douchette||sortie)return;
  var d=lire(K_DOUCH),reste=d?(Number(d.vu)||0)+DOUCHETTE_MAX-Date.now():0;
  minDouchette=setTimeout(function(){if(sessionDouchette(APPLI))armerDouchette();else verifierSession()},Math.max(300,reste+50));
}
function scanFait(){
  if(!S.douchette||sortie)return;
  var d=lire(K_DOUCH);if(!d||d.app!==APPLI)return;
  d.vu=Date.now();ecrire(K_DOUCH,d);armerDouchette();
}
armerDouchette();
// Petit message en bas de l'appli (scan d'une appli non proposée ici).
function avisBas(t){
  var el=document.getElementById('pk-avis');
  if(!el){el=document.createElement('div');el.id='pk-avis';el.setAttribute('role','status');
    el.style.cssText='position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:2147483001;max-width:min(560px,calc(100% - 32px));background:#15242b;color:#fff;border-radius:12px;padding:12px 16px;font:600 16px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;box-shadow:0 4px 18px rgba(0,0,0,.3)';
    document.body.appendChild(el)}
  el.textContent='• '+t;el.hidden=false;clearTimeout(avisBas.t);avisBas.t=setTimeout(function(){el.hidden=true},5000);
}
// Étiquette d'une AUTRE appli scannée ici (ex. DAG-L dans Fours) : on bascule vers elle, scan transmis. Pas quand un
// vrai champ de saisie est utilisé (la douchette y a écrit : on ne part pas en laissant ce texte).
function champActif(){var a=document.activeElement;return !!(a&&a.id!=='douchIn'&&(/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName)||a.isContentEditable))}
var lecteurApp=INTEGRE?null:Lecteur({
  lent:function(){return !champActif()},
  lu:function(x){
    if(sortie){scanSortie=x;return true}
    if(x.app===APPLI||champActif())return false;
    var m=ouvrirScan(x);
    if(m===true){sortie=true;return true}
    avisBas(m);return true;
  }
});
// Reprise après la veille (2026-11-12, campagne tablette B2) : avant, le contrôle n'avait lieu que toutes les 20 s ; une
// tablette réveillée restait jusqu'à 20 s au nom de la personne partie et le premier toucher agissait encore pour elle.
// Le contrôle est fait AVANT de noter l'activité : un toucher ne fait jamais revivre une session expirée.
// Touches : la douchette est écoutée d'abord (2026-11-19), même pendant une sortie, pour ne perdre aucun scan.
['pointerdown','keydown'].forEach(function(ev){document.addEventListener(ev,function(e){
  if(ev==='keydown'&&lecteurApp){var r=lecteurApp.touche(e);if(r.fin||sortie){e.preventDefault();e.stopPropagation();if(r.fin)return}}
  // Session douchette : aucune touche bloquée (le scan doit toujours passer) ; sa fin est gérée par son minuteur.
  if(S.douchette){if(!sortie){var t0=Date.now();if(t0-dernier>1000){dernier=t0;toucher()}}return}
  if(!verifierSession()){e.preventDefault();e.stopPropagation();return}
  var t=Date.now();if(t-dernier>1000){dernier=t;toucher()}
},true)});
// Le clic qui suit un toucher refusé ne doit rien déclencher non plus.
document.addEventListener('click',function(e){if(sortie){e.preventDefault();e.stopPropagation()}},true);
document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')verifierSession()});
window.addEventListener('pageshow',verifierSession);
window.addEventListener('focus',verifierSession);
setInterval(verifierSession,20000);
})();

Pack-Tablettes/console/serveur.mjs.t:
// Console du PC — Pack Tablettes.
// Lancée par Console-PC.cmd : petit serveur sur ce PC seulement (http://localhost:8789), qui sert la page
// console.html et fait ce qu'une page seule ne peut pas faire :
//   - construire la nouvelle version (construire-unique.mjs --en-ligne) et la montrer en aperçu (/apercu/) ;
//   - la publier sur le site internet (GitHub Pages) avec le jeton GitHub enregistré sur ce PC ;
//   - revenir à une version précédente ; lire dans la Google Sheet quelle version chaque tablette utilise.
// Le jeton GitHub est gardé dans %APPDATA%\Pack-Tablettes-console\reglages.json, jamais renvoyé à la page.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import {exec,execFile} from 'node:child_process';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {construire,dateSources,logoBrut,DOSSIER_EN_LIGNE,contientCode,assemblerConsole,foursCommun,liaisonCommun,assemblerEssai} from '../construire-unique.mjs';

const ici=path.dirname(fileURLToPath(import.meta.url)),pack=path.dirname(ici);
// PACK_SEUL=lancements : logiciel « Lancements machines » seul (bureau) — seulement l'onglet Lancements, ses
// réglages Google et son mode d'emploi ; ni GitHub, ni aperçu, ni contenus (rien du pack à installer).
const SEUL=process.env.PACK_SEUL==='lancements'?'lancements':'';
const PORT=Number(process.env.CONSOLE_PORT||(SEUL?8791:8789));
// --reglages <dossier> : autre dossier de réglages (essais).
const iR=process.argv.indexOf('--reglages');
const DOSSIER_REGLAGES=iR>0?path.resolve(process.argv[iR+1]):path.join(process.env.APPDATA||os.homedir(),SEUL?'Lancements-machines':'Pack-Tablettes-console');
const FICHIER_REGLAGES=path.join(DOSSIER_REGLAGES,'reglages.json');

// --- Réglages -------------------------------------------------------------------
function googleDuPack(){
  let t='';try{t=fs.readFileSync(path.join(pack,'commun','pack.js'),'utf8')}catch(e){}
  const m=/GOOGLE_DEFAUT=\{url:'([^']*)',code:'([^']*)'\}/.exec(t);
  return m?{url:m[1],code:m[2]}:{url:'',code:''};
}
// Logiciel Windows « clé en main » : console\reglages-defaut.json contient les réglages du PC qui l'a fabriqué
// (compte, dépôt et jeton GitHub, Google). Ceux enregistrés sur ce PC-ci, s'il y en a, passent devant.
function reglagesDefaut(){
  try{const d=JSON.parse(fs.readFileSync(path.join(ici,'reglages-defaut.json'),'utf8'));return {github:d.github||{},google:d.google||{}}}
  catch(e){return {github:{},google:{}}}
}
function reglages(){
  let r={};
  try{r=JSON.parse(fs.readFileSync(FICHIER_REGLAGES,'utf8'))}catch(e){}
  const d=reglagesDefaut();
  r.github=Object.assign({proprietaire:'',depot:'',branche:'main',jeton:''},d.github,r.github);
  if(!r.github.jeton&&d.github.jeton)r.github.jeton=d.github.jeton;
  r.google=Object.assign(googleDuPack(),d.google,r.google);
  return r;
}
// Le jeton fourni par le logiciel n'est pas recopié dans les réglages de ce PC : un logiciel refait avec un
// nouveau jeton (l'ancien expiré) doit l'emporter.
function enregistrer(r){
  // Idem pour tout réglage identique à celui du logiciel : seuls les réglages propres à ce PC sont gardés.
  const d=reglagesDefaut(),x=JSON.parse(JSON.stringify(r));
  for(const s of ['github','google'])for(const k in d[s])if(d[s][k]&&x[s]&&x[s][k]===d[s][k])delete x[s][k];
  fs.mkdirSync(DOSSIER_REGLAGES,{recursive:true});fs.writeFileSync(FICHIER_REGLAGES,JSON.stringify(x,null,1));
}
// Ce que la page peut voir : tout sauf le jeton. Le code de la Google Sheet : seulement « défini oui/non » (relecture
// 2026-10-17, I1 : jamais en clair, ancienne console comprise). projet : dossier du projet (partie « Script Google »).
function reglagesPublics(r,complet){return {github:{proprietaire:r.github.proprietaire,depot:r.github.depot,branche:r.github.branche,jeton:!!r.github.jeton},google:complet===false?{url:r.google.url,code:!!r.google.code}:r.google,logiciel:infoLogiciel(r),
  projet:{reglage:typeof r.projet==='string'?r.projet:'',trouve:dossierProjet(r)}}}
// Console lancée par le logiciel Windows : sa version (= date des applications qu'il contient) et l'origine du jeton.
function infoLogiciel(r){
  if(!process.env.PACK_LOGICIEL)return null;
  const d=reglagesDefaut();
  return {version:process.env.PACK_LOGICIEL,jetonFourni:!!d.github.jeton,jetonDuLogiciel:!!d.github.jeton&&r.github.jeton===d.github.jeton};
}

// --- GitHub -----------------------------------------------------------------------
// PACK_GITHUB_API : imitation de GitHub pour les essais (jamais le vrai site depuis un test).
const GH_API=process.env.PACK_GITHUB_API||'https://api.github.com';
class ErreurGitHub extends Error{constructor(m,status){super(m);this.status=status}}
function gh(r){
  const g=r.github;
  if(!g.proprietaire||!g.depot||!g.jeton)throw new ErreurGitHub('Réglages GitHub incomplets (compte, dépôt, jeton) : onglet Réglages.');
  const base='/repos/'+encodeURIComponent(g.proprietaire)+'/'+encodeURIComponent(g.depot);
  const appel1=async(methode,chemin,corps)=>{
    const rep=await fetch(GH_API+(chemin.startsWith('/repos/')||chemin.startsWith('/user')?chemin:base+chemin),{method:methode,
      headers:{Authorization:'Bearer '+g.jeton,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','User-Agent':'pack-tablettes-console','Content-Type':'application/json'},
      body:corps?JSON.stringify(corps):undefined}).catch(e=>{
        throw new ErreurGitHub('GitHub injoignable depuis ce PC ('+((e.cause&&e.cause.code)||e.message)+') : pas d’internet, ou accès bloqué par le réseau de l’entreprise (pare-feu / proxy).');
      });
    const txt=await rep.text();let j=null;try{j=txt?JSON.parse(txt):null}catch(e){}
    if(!rep.ok)throw new ErreurGitHub(messageGitHub(rep.status,j,chemin),rep.status);
    return j;
  };
  // GitHub répond parfois 502/503/504 (surcharge passagère) : jusqu'à 4 nouveaux essais espacés.
  const appel=async(methode,chemin,corps)=>{
    for(let essai=0;;essai++){
      try{return await appel1(methode,chemin,corps)}
      catch(e){
        if(!(e.status>=502&&e.status<=504)||essai>=4)throw e;
        await new Promise(ok=>setTimeout(ok,[2000,4000,8000,15000][essai]));
      }
    }
  };
  return {appel,branche:g.branche||'main',g};
}
function messageGitHub(status,j,chemin){
  const m=j&&j.message||'';
  if(status===401)return 'Jeton GitHub refusé (faux ou expiré) : créez-en un nouveau (console › Liaisons Google & site ; ancienne console : onglet Réglages).';
  if(status===403&&/\/pages$/.test(chemin))return 'Pages refusé';
  if(status===403)return 'Le jeton GitHub n’a pas le droit d’écrire dans le dépôt ('+m+', étape '+chemin.replace(/^\/repos\/[^/]+\/[^/]+/,'')+'). Modifiez le jeton : Repository access = ce dépôt, Permissions › Contents = Read and write.';
  if(status===404&&/\/pages$/.test(chemin))return 'Pages introuvable';
  if(status>=502&&status<=504&&/\/contents\//.test(chemin))return 'GitHub n’arrive pas à créer le premier fichier du dépôt vide ('+status+' '+m+'). Sur github.com, ouvrez le dépôt et cliquez sur « Add a README » (ou « creating a new file »), validez avec « Commit changes », puis relancez la publication.';
  if(status>=502&&status<=504)return 'GitHub est momentanément indisponible ('+status+' '+m+'). Réessayez dans quelques minutes.';
  if(status===404)return 'Dépôt GitHub introuvable : vérifiez le compte et le nom du dépôt (console › Liaisons Google & site ; ancienne console : onglet Réglages), et que le jeton y a accès.';
  return 'GitHub : '+status+' '+m;
}
async function teteBranche(c){
  try{return (await c.appel('GET','/git/ref/heads/'+c.branche)).object.sha}
  catch(e){if(e.status===404||e.status===409)return null;throw e}
}
// Dépôt encore vide : l'API des commits n'y marche pas, on crée d'abord un premier fichier.
async function initialiser(c){
  await c.appel('PUT','/contents/LISEZ-MOI.md',{message:'Création du site du Pack Tablettes',branch:c.branche,
    content:Buffer.from('# Pack Tablettes\n\nSite publié par la console du PC (Pack-Tablettes\\Console-PC.cmd). Ne pas modifier à la main.\n').toString('base64')});
  return teteBranche(c);
}
// Adresse du site. Si le jeton n'a pas le droit de lire Pages, on la déduit du compte et du dépôt.
async function adresseSite(c,stricte){
  try{const p=await c.appel('GET','/pages');return p.html_url||''}
  catch(e){
    if(e.status===404)return '';
    if(e.status===403&&!stricte)return adresseDeduite(c.g);
    throw e;
  }
}
function adresseDeduite(g){
  const p=g.proprietaire.toLowerCase();
  return g.depot.toLowerCase()===p+'.github.io'?'https://'+p+'.github.io/':'https://'+p+'.github.io/'+g.depot+'/';
}
async function activerPages(c){
  const manuel0='Version envoyée. Le jeton ne peut pas gérer le site (Pages) : si le site n’est pas encore activé, sur github.com, dans le dépôt : Settings › Pages › Branch : « '+c.branche+' » et « / (root) » › Save.';
  let url;
  try{url=await adresseSite(c,true)}catch(e){if(e.status===403)return {url:adresseDeduite(c.g),avis:manuel0};throw e}
  if(url)return {url};
  const manuel='Version envoyée, mais le site n’a pas pu être activé automatiquement. Sur github.com, dans le dépôt : Settings › Pages › Branch : « '+c.branche+' » et « / (root) » › Save. Puis rouvrez la console.';
  // La version est déjà envoyée : un échec ici n'est qu'un avis (activation du site à faire à la main, une fois).
  try{
    const p=await c.appel('POST','/pages',{source:{branch:c.branche,path:'/'}});
    return {url:p.html_url||adresseDeduite(c.g)};
  }catch(e){
    return {url:adresseDeduite(c.g),avis:e.status===422?'GitHub refuse d’activer le site (Pages) : le dépôt doit être « Public » avec un compte gratuit (Settings › General › Change visibility). '+manuel:manuel};
  }
}
// --- Diffusion progressive ----------------------------------------------------------------------------
// Le site garde :
//   - à la racine (index.html, sw.js…) la version DIFFUSÉE : celle des tablettes « normales » ;
//   - dans versions/<id>/ une copie complète de la version diffusée et de la version EN TEST ;
//   - dans version.json : id (version diffusée), test (version en test ou null) et tablettes { appareil: {canal} }
//     avec canal = 'test' (reçoit d'abord les nouvelles versions), 'bloquee' (ne change plus de version) ;
//     les tablettes absentes de la liste sont « normales ».
// Les anciennes tablettes (avant ce système) ne lisent que « id » : elles suivent la version diffusée.
const CANAUX=['normale','test','bloquee'];
async function arbreSite(c,tete){
  if(!tete)return {sha:null,fichiers:[]};
  const commit=await c.appel('GET','/git/commits/'+tete);
  const t=await c.appel('GET','/git/trees/'+commit.tree.sha+'?recursive=1');
  return {sha:commit.tree.sha,fichiers:(t.tree||[]).filter(x=>x.type==='blob')};
}
async function lireFichierArbre(c,arbre,chemin){
  const f=arbre.fichiers.find(x=>x.path===chemin);if(!f)return null;
  const b=await c.appel('GET','/git/blobs/'+f.sha);
  return Buffer.from(b.content||'',b.encoding==='base64'?'base64':'utf8').toString('utf8');
}
async function versionSite(c,arbre){
  try{const j=JSON.parse(await lireFichierArbre(c,arbre,'version.json')||'null');return j&&typeof j==='object'?j:null}catch(e){return null}
}
function tablettesPropres(t){
  const o={};
  if(t&&typeof t==='object')for(const k of Object.keys(t))if(/^[\w-]{1,80}$/.test(k)&&t[k]&&CANAUX.includes(t[k].canal)&&t[k].canal!=='normale')o[k]={canal:t[k].canal};
  return o;
}
async function blob(c,contenu){return (await c.appel('POST','/git/blobs',{content:Buffer.from(contenu).toString('base64'),encoding:'base64'})).sha}
// Un commit : l'arbre actuel + ajouts/remplacements ({path, sha}) − suppressions. versions/ ne garde que « garder ».
async function ecrireSite(c,tete,arbre,{ajouts,garder,message}){
  const chemins=new Set(ajouts.map(a=>a.path));
  const entrees=ajouts.map(a=>({path:a.path,mode:'100644',type:'blob',sha:a.sha}));
  for(const f of arbre.fichiers){
    const m=/^versions\/([^/]+)\//.exec(f.path);
    if(m&&!garder.has(m[1])&&!chemins.has(f.path))entrees.push({path:f.path,mode:'100644',type:'blob',sha:null});
  }
  const t=await c.appel('POST','/git/trees',arbre.sha?{base_tree:arbre.sha,tree:entrees}:{tree:entrees});
  const commit=await c.appel('POST','/git/commits',{message,tree:t.sha,parents:[tete]});
  await c.appel('PATCH','/git/refs/heads/'+c.branche,{sha:commit.sha});
  return commit.sha;
}
function versionConstruite(){
  if(!fs.existsSync(path.join(DOSSIER_EN_LIGNE,'version.json')))throw new Error('Aucune version construite sur ce PC : cliquez d’abord sur « Construire ».');
  return JSON.parse(fs.readFileSync(path.join(DOSSIER_EN_LIGNE,'version.json'),'utf8'));
}
// publie (2026-11-24, « À surveiller » des consoles) : heure où la version part sur le site (date = sa construction) ;
// une tablette vue plus d'1 h après sans l'avoir est signalée. infoV ne sert qu'aux écritures de version.json.
const infoV=v=>Object.assign({id:v.id,date:v.date,notes:v.notes||'',sources:v.sources,publie:Date.now()},v.num?{num:v.num}:{});
// Numéro de version (Version 1, 2, 3…) : donné à la PUBLICATION, le suivant du plus grand déjà publié (dernierNum,
// gardé dans version.json). Une version republiée telle quelle garde son numéro. Il est écrit dans la page (PACK_VERSION.num).
function numeroSuivant(site,v){
  if(site&&site.test&&site.test.id===v.id&&site.test.num)return site.test.num;
  if(site&&site.id===v.id&&site.num)return site.num;
  return Math.max(Number(site&&site.dernierNum)||0,Number(site&&site.num)||0,Number(site&&site.test&&site.test.num)||0)+1;
}
function avecNumero(buf,v,num){
  const t=buf.toString('utf8'),cle='PACK_VERSION={"id":'+JSON.stringify(v.id);
  if(!t.includes(cle))throw new Error('Version construite illisible : reconstruisez-la (« Construire »).');
  return Buffer.from(t.split(cle).join(cle+',"num":'+num),'utf8');
}
