// mode 'test' : seulement sur les tablettes test ; mode 'partout' : version diffusée à toutes les tablettes.
async function publier(r,journal,mode){
  const c=gh(r);let v=versionConstruite();
  const {tete,arbre,site}=await ouvrirSite(c,journal);
  const tabs=tablettesPropres(site&&site.tablettes);
  if(mode==='test'&&!(site&&site.id))throw new Error('Première publication : elle doit aller sur toutes les tablettes (« Publier directement sur toutes les tablettes »).');
  if(mode==='test'&&v.id===site.id)throw new Error('Cette version est déjà diffusée sur toutes les tablettes : construisez-en une nouvelle.');
  if(mode==='test'&&!Object.values(tabs).some(t=>t.canal==='test'))throw new Error('Aucune tablette test : choisissez-en une dans l’onglet « Tablettes » (colonne « Mises à jour »).');
  const fichiers=fs.readdirSync(DOSSIER_EN_LIGNE).filter(f=>f!=='version.json'&&fs.statSync(path.join(DOSSIER_EN_LIGNE,f)).isFile());
  // Console en ligne (2026-10-15) : en-ligne\console\ part avec le reste du site (<site>/console/), même mécanisme.
  // Pages publiques (index.html du pack et console en ligne) : publication arrêtée si un secret s'y trouve — code de la
  // Google Sheet (pack.js et Réglages de cette console), codes des fichiers secteurs, jeton GitHub (le nôtre ou toute
  // chaîne qui en a la forme).
  if(v.consoleErreur)journal('⚠ La console en ligne n’a pas pu être construite ('+v.consoleErreur+') : elle ne part PAS avec cette version ; le site garde la précédente. Corrigez, puis « Construire » à nouveau.');
  const dc=path.join(DOSSIER_EN_LIGNE,'console');
  if(fs.existsSync(dc))for(const f of fs.readdirSync(dc).filter(x=>fs.statSync(path.join(dc,x)).isFile()))fichiers.push('console/'+f);
  const secrets=[r.google&&r.google.code,r.github&&r.github.jeton];
  for(const f of fichiers.filter(x=>x==='index.html'||(x.startsWith('console/')&&!/\.png$/.test(x)))){
    if(contientCode(fs.readFileSync(path.join(DOSSIER_EN_LIGNE,f),'utf8'),secrets))
      throw new Error('La page '+f+' contient un code d’accès ou un jeton : publication arrêtée. Reconstruisez la version (« Construire »).');
  }
  // Programme des télés (2026-11-24, mise à jour des Raspberry par le réseau) : en-ligne\tele\ part avec le reste
  // (<site>/tele/ et versions/<id>/tele/ : une télé « test » prend celui de la version en test). Seulement s'il est de
  // CETTE version et intact ; sinon il ne part pas et les télés gardent leur programme. Ni code, ni jeton, ni adresse
  // du script Google (le Raspberry lit la sienne dans ses réglages) : sinon publication arrêtée.
  const dt=path.join(DOSSIER_EN_LIGNE,'tele');
  if(fs.existsSync(path.join(dt,'manifeste.json'))){
    let mt=null,pq=null;try{mt=JSON.parse(fs.readFileSync(path.join(dt,'manifeste.json'),'utf8'));pq=fs.readFileSync(path.join(dt,'paquet.json'))}catch(e){}
    const intact=mt&&pq&&mt.id===v.id&&mt.paquet&&mt.paquet.taille===pq.length&&crypto.createHash('sha256').update(pq).digest('hex')===mt.paquet.sha256;
    if(!intact)journal('⚠ Programme des télés absent ou d’une autre version : il ne part PAS avec cette version (les télés gardent le leur). « Construire » à nouveau pour l’ajouter.');
    else{
      if(contientCode(pq.toString('utf8'),secrets.concat([r.google&&r.google.url])))
        throw new Error('Le programme des télés contient un code d’accès, un jeton ou l’adresse du script Google : publication arrêtée. Reconstruisez la version (« Construire »).');
      fichiers.push('tele/manifeste.json','tele/paquet.json');
    }
  }
  const num=numeroSuivant(site,v);v=Object.assign({},v,{num});
  journal('Version '+num+' — envoi de '+fichiers.length+' fichiers…');
  const ajouts=[];
  for(const f of fichiers){
    let contenu=fs.readFileSync(path.join(DOSSIER_EN_LIGNE,f));
    if(f==='index.html')contenu=avecNumero(contenu,v,num);
    const sha=await blob(c,contenu);
    ajouts.push({path:'versions/'+v.id+'/'+f,sha});
    if(mode!=='test')ajouts.push({path:f,sha});
  }
  if(mode!=='test')ajouts.push({path:'LISEZ-MOI.md',sha:await blob(c,'# Pack Tablettes\n\nSite publié par la console du PC. Ne pas modifier à la main.\n')});
  const dernierNum=Math.max(num,Number(site&&site.dernierNum)||0);
  const nv=mode==='test'?Object.assign({},site,{test:infoV(v),tablettes:tabs,dernierNum}):Object.assign(infoV(v),{test:null,tablettes:tabs,dernierNum});
  ajouts.push({path:'version.json',sha:await blob(c,JSON.stringify(nv,null,1))});
  const garder=new Set([nv.id,nv.test&&nv.test.id].filter(Boolean));
  const message=(mode==='test'?'Test ':'Version ')+v.id+' (n° '+num+')'+(v.notes?' — '+v.notes:'');
  const sha=await ecrireSite(c,tete,arbre,{ajouts,garder,message});
  journal(mode==='test'?'Version '+num+' envoyée sur les tablettes test.':'Version '+num+' envoyée sur toutes les tablettes.');
  const {url,avis}=await activerPages(c);
  if(avis)journal(avis);
  journal('Site : '+url+' (GitHub met environ 1 minute à le mettre en ligne).');
  return {version:v,url,sha};
}
