// --- Dernier état connu des écrans télé (2026-11-12, testeur B1) ------------------------------------------------------
// Une télé (Raspberry Pi) qui redémarre pendant une panne de Google montrait « Aucun plateau au four ». La dernière
// réponse réussie de chaque écran (fours, liaison d'un secteur, maintenance d'un secteur) est gardée en mémoire et dans
// un petit fichier du dossier de réglages (il survit à un redémarrage) ; Google ne répond pas : elle est renvoyée avec
// perime = {at, erreur}, et l'écran dit « Affichage du HH:MM — pas de connexion avec Google ». Les minuteurs des fours
// se calculent seuls (l'heure renvoyée est l'heure de maintenant, corrigée de l'écart avec Google).
// Rien de secret dedans (ni code, ni adresse Google) : ce que les écrans montrent déjà.
const DERNIER_FICHIER=path.join(DOSSIER_REGLAGES,'ecrans-dernier-etat.json');
const DERNIER={d:null,t:0,attente:null};
function dernierTout(){
  if(!DERNIER.d){try{DERNIER.d=JSON.parse(fs.readFileSync(DERNIER_FICHIER,'utf8'))}catch(e){}if(!DERNIER.d||typeof DERNIER.d!=='object'||Array.isArray(DERNIER.d))DERNIER.d={}}
