  if(!site)throw new Error('Google n’a pas encore de configuration du pack.');
  const conflit=()=>Object.assign(new Error('La configuration a changé entre-temps (sur une tablette ou une autre fenêtre) : rechargez les personnes, puis refaites la modification.'),{status:409});
  if(Number(b.depuis)!==Number(site.maj))throw conflit();
  site.personnes=personnesPropres(b.personnes,site);
