// --- Capture d'écran du plan d'un plateau (Lancements machines) ---------------------------------------------------
// Ouvre l'outil de capture de Windows (ms-screenclip, comme Win+Maj+S), puis attend la nouvelle image du
// presse-papiers (90 s au plus) et la renvoie à la page. outil:false = attendre seulement (capture déjà en cours).
const PS_CAPTURE=`Add-Type -AssemblyName System.Windows.Forms,System.Drawing
function Image64 { $i=[Windows.Forms.Clipboard]::GetImage(); if(-not $i){ return '' }; $ms=New-Object IO.MemoryStream; $i.Save($ms,[Drawing.Imaging.ImageFormat]::Png); $i.Dispose(); [Convert]::ToBase64String($ms.ToArray()) }
$avant=Image64
if($env:PACK_OUTIL -eq '1'){ try{ Start-Process 'ms-screenclip:' }catch{} }
$fin=(Get-Date).AddSeconds(90)
while((Get-Date) -lt $fin){ Start-Sleep -Milliseconds 400; $b=Image64; if($b -and $b -ne $avant){ [Console]::Out.Write($b); exit 0 } }
exit 2`;
let captureEnCours=null;
function capturePlan(outil){
  if(captureEnCours)return captureEnCours;
  const enc=Buffer.from(PS_CAPTURE,'utf16le').toString('base64');
  captureEnCours=new Promise((ok,ko)=>{
    execFile('powershell.exe',['-NoProfile','-STA','-ExecutionPolicy','Bypass','-EncodedCommand',enc],
      {env:Object.assign({},process.env,{PACK_OUTIL:outil===false?'0':'1'}),maxBuffer:60e6,timeout:100000,windowsHide:true},
      (err,sortie)=>{
        const b=String(sortie||'').trim();
        if(b&&/^[A-Za-z0-9+/=]+$/.test(b))ok({data:'data:image/png;base64,'+b});
        else ko(new Error('Aucune capture reçue (annulée, ou plus de 90 s). Réessayez, ou faites Win+Maj+S puis Ctrl+V sur la carte de la machine.'));
      });
  }).finally(()=>{captureEnCours=null});
  return captureEnCours;
}
