  const now=Date.now();
  for(const k of (Array.isArray(b.ajouter)?b.ajouter:[]))if(typeof k==='string'&&k.length<300)o[k]=now;
  for(const k of (Array.isArray(b.retirer)?b.retirer:[]))delete o[k];
