// --- Google : contenus des applications (éditeur « Contenus » de la console) ---------------
// La console parle à Google exactement comme les applications des tablettes (même script, même format) :
// les tablettes reçoivent les modifications à leur prochain échange (moins d'une minute).
async function google(r,body,delai){
  const g=r.google;
  // appli@secteur → app + secteur (le script range ce secteur dans ses propres onglets).
  if(typeof body.app==='string'&&body.app.includes('@')){const s=secteurApp(body.app);body=Object.assign({},body,{app:body.app.split('@')[0]});if(s)body.secteur=s}
  if(!g.url||!g.code)throw new Error('Adresse ou code de la Google Sheet manquant (console › Liaisons Google & site ; ancienne console : onglet Réglages).');
  let rep;const t0=Date.now();
  try{rep=await fetch(g.url,{method:'POST',body:JSON.stringify(Object.assign({},body,{key:g.code})),redirect:'follow',signal:AbortSignal.timeout(delai||60000)})}
  catch(e){const c=(e.cause&&e.cause.code)||e.name;noterGoogleErreur(erreurReseau(c),c);throw googleCoupe(c)}
  const j=await rep.json().catch(()=>null);
  if(!j||typeof j.status!=='number'){noterGoogleErreur('script','réponse illisible (HTTP '+rep.status+')');throw new Error('Réponse inattendue de Google.')}
  noterGoogleReponse(j,Date.now()-t0);
  if(j.status!==200)throw new Error((j.data&&j.data.error)||('Erreur Google '+j.status));
  return j.data;
}
// --- Témoin « Google » de la console et des écrans (2026-10-15) ------------------------------------------------
// Alimenté par les appels déjà faits (aucune charge en plus) ; une petite lecture du pack seulement si rien n'a été
// échangé depuis 2 min 30. Types d'erreur : internet (pas d'internet sur ce PC), injoignable (Google ne répond pas),
// script (le script répond par une erreur), code (code d'accès refusé), occupe (Google occupé, passager).
const etatGoogle={ok:0,duree:0,erreur:null};
const erreurReseau=c=>/ENOTFOUND|EAI_AGAIN|ENETUNREACH|ENETDOWN|EHOSTUNREACH/.test(String(c))?'internet':'injoignable';
// Message affiché (télés, console) quand Google ne répond pas (testeur 2026-11-12, B2) : sans code technique
// (« UND_ERR_SOCKET » ne dit rien à l'atelier) ; le code reste dans le journal du programme et dans le témoin Google.
function googleCoupe(c){console.error('Google injoignable : '+c);return Object.assign(new Error('Google injoignable depuis ce PC.'),{status:503})}
function noterGoogleErreur(type,message){etatGoogle.erreur={type,message:String(message||'').slice(0,200),at:Date.now()}}
// Une réponse de Google : 200, mais aussi 400 / 409 (refus « métier ») = Google répond bien.
function noterGoogleReponse(j,duree){
  const msg=String((j.data&&j.data.error)||'');
  if(j.status===401)return noterGoogleErreur('code',msg||'code refusé');
  if(j.status===503&&/occupé/i.test(msg))return noterGoogleErreur('occupe',msg);
  if(j.status>=500||/Opération inconnue|mettez à jour le script|pas installé/i.test(msg))return noterGoogleErreur('script',msg||('erreur '+j.status));
  etatGoogle.ok=Date.now();etatGoogle.duree=duree;etatGoogle.erreur=null;
}
function resumeGoogle(){
  const e=etatGoogle,now=Date.now(),g=reglages().google||{};
  if(!g.url||!g.code)return {niveau:'gris',type:'reglages',titre:'Google non réglé'};
  if(e.erreur&&e.erreur.type!=='occupe')return {niveau:'rouge',type:e.erreur.type,message:e.erreur.message,depuis:e.erreur.at,dernierOk:e.ok};
  if(e.erreur)return {niveau:'orange',type:'occupe',message:e.erreur.message,depuis:e.erreur.at,dernierOk:e.ok};
  if(!e.ok)return {niveau:'gris',type:'attente',titre:'Pas encore de réponse de Google'};
  if(now-e.ok>5*60000)return {niveau:'orange',type:'ancien',dernierOk:e.ok};
  if(e.duree>8000)return {niveau:'orange',type:'lent',dernierOk:e.ok,duree:e.duree};
  return {niveau:'vert',type:'ok',dernierOk:e.ok,duree:e.duree};
}
