function appliquerListes(p,cible){
  const cat=JSON.parse(JSON.stringify(catalogueDe(p)));p.catalog=cat;
  for(const k of SORTES){
    const cur=cat[k],voulu=cible[k],ren=(cible.renames||{})[k]||{};
    // Renommages : nouveau nom ← ancien nom (encore présent chez Google).
    for(const n of voulu){const o=ren[n];if(o&&o!==n&&cur.includes(o)&&!cur.includes(n)){
      cat[k]=cat[k].map(x=>x===o?n:x);
      if(k==='teams'&&p.outgoing===o)p.outgoing=n;
      if(k==='operators'){if(p.operator===o)p.operator=n;if(p.recipient===o)p.recipient=n}
      if(k==='machines'){p.machines=p.machines.map(m=>m.name===o?{...m,name:n}:m);const rn={...cat.renamed},orig=rn[o]??o;delete rn[o];rn[n]=orig;cat.renamed=rn}
    }}
    // Retraits.
    for(const o of cat[k].filter(x=>!voulu.includes(x))){
      cat[k]=cat[k].filter(x=>x!==o);
      if(k==='teams'&&p.outgoing===o)p.outgoing='';
      if(k==='operators'){if(p.operator===o)p.operator='';if(p.recipient===o)p.recipient=''}
      if(k==='machines'){p.machines=p.machines.filter(m=>m.name!==o);if(cat.renamed){const rn={...cat.renamed};delete rn[o];cat.renamed=rn}}
    }
    // Ajouts, puis l'ordre voulu.
    for(const n of voulu)if(!cat[k].includes(n)){cat[k].push(n);if(k==='machines')p.machines.push(machineVide(n))}
    cat[k]=voulu.filter(n=>cat[k].includes(n));
  }
  p.machines=cat.machines.map(n=>p.machines.find(m=>m.name===n)||machineVide(n));
  return p;
}
APPS.releve={liste:'listes',nom:'liste',vide:'Google n’a encore aucune relève : ouvrez une fois la Relève d’équipe sur une tablette reliée à Google.',
  titre:()=>'Listes de la relève',
  propre(o){
    const x={id:'catalogue'},vus=new Set();
    for(const k of SORTES){
      x[k]=l_(o[k]).map(n=>n.replace(/\s+/g,' ').slice(0,100)).filter(n=>{const c=n.toLocaleLowerCase('fr');if(vus.has(k+c))return false;vus.add(k+c);return true}).slice(0,200);
    }
    if(!x.machines.length)throw new Error('Gardez au moins une machine.');
    x.renames={};for(const k of SORTES){x.renames[k]={};const r=(o.renames||{})[k]||{};for(const n of x[k])if(typeof r[n]==='string'&&r[n]!==n)x.renames[k][n]=r[n]}
    return x;
  },
  photos:()=>[],perdu:()=>false,
  async lire(r){
    const d=await google(r,{operation:'state'}),dr=d.draft;
    if(!dr)return {state:null,rev:0};
    const c=catalogueDe(JSON.parse(dr.payload));
    return {state:{listes:[{id:'catalogue',teams:c.teams,operators:c.operators,machines:c.machines,renames:{}}]},rev:dr.revision};
  },
  async ecrire(r,items){
    const cible=items[0];if(!cible)throw new Error('Rien à envoyer.');
    // Le brouillon commun change à chaque saisie sur une tablette : en cas de conflit, on relit et on recommence.
    for(let essai=0;essai<5;essai++){
      const d=await google(r,{operation:'state'}),dr=d.draft;
      if(!dr)throw new Error(this.vide);
      const p=appliquerListes(JSON.parse(dr.payload),cible);
      try{await google(r,{operation:'save',revision:dr.revision,payload:p});return this.lire(r)}
      catch(e){if(!/modifié|révision|409/i.test(e.message))throw e}
    }
    throw new Error('La relève est en cours de saisie sur une tablette : réessayez dans un instant.');
  }};

// --- Qui voit quoi : site.droits de la configuration du pack (rôles, puis exceptions par personne). Listes = ce qui
// est MASQUÉ. Les noms des tâches, fiches et opérations sont lus dans Google pour être proposés à l'écran.
function droitsPropres(d){
  const bloc=o=>{const x={};if(!o||typeof o!=='object')return x;
    if(Array.isArray(o.applis))x.applis=l_(o.applis).filter(idValide);
    for(const k of ['onglets','contenus'])if(o[k]&&typeof o[k]==='object'){x[k]={};for(const a of Object.keys(o[k]))if(idValide(a)&&Array.isArray(o[k][a]))x[k][a]=l_(o[k][a]).filter(idValide)}
    return x};
  const r={roles:{},personnes:{}};
  for(const k of Object.keys((d&&d.roles)||{}))if(idValide(k))r.roles[k]=bloc(d.roles[k]);
  for(const k of Object.keys((d&&d.personnes)||{}))if(idValide(k)){const b=bloc(d.personnes[k]);if(Object.keys(b).length)r.personnes[k]=b}
  // Secteurs : masqué pour tout le monde sur les tablettes du secteur (en plus du rôle / de la personne).
  r.secteurs={};
  for(const k of Object.keys((d&&d.secteurs)||{}))if(idValide(k)){const b=bloc(d.secteurs[k]);if(Object.keys(b).length)r.secteurs[k]=b}
  return r;
}
// Nom d'un secteur : lu dans Pack-Tablettes\secteurs\<id>.js (nom:'…'), sinon l'identifiant.
function nomSecteur(id){try{const m=/nom\s*:\s*'([^']{1,60})'/.exec(fs.readFileSync(path.join(pack,'secteurs',id+'.js'),'utf8'));return m?m[1]:id}catch(e){return id}}
APPS.droits={liste:'droits',nom:'réglage',vide:'La configuration du pack n’est pas encore sur Google : ouvrez une fois l’accueil du pack sur une tablette reliée à Google.',
  titre:()=>'Qui voit quoi',
  propre:o=>Object.assign({id:'droits'},droitsPropres(o)),
  photos:()=>[],perdu:()=>false,
  async lire(r){
    const d=await google(r,{app:'pack',operation:'pull'}),s=d.site;
    if(!s)return {state:null,rev:0};
    const noms=async(app,liste,titre)=>{try{const x=await google(r,{app,operation:'pull',rev:-1});return ((x.state&&x.state[liste])||[]).filter(o=>!o.archived).map(o=>({id:o.id,nom:o[titre]}))}catch(e){return null}};
    const [taches,fiches,maintenance,procedures]=await Promise.all([noms('taches','tasks','name'),noms('fiches','fiches','title'),noms('maintenance','ops','title'),noms('procedures','procs','titre')]);
    return {state:{droits:[Object.assign({id:'droits'},droitsPropres(s.droits))],
      personnes:(s.personnes||[]).map(p=>({id:p.id,nom:p.nom,role:p.role})),secteurs:(s.secteurs||[]).filter(idValide).map(id=>({id,nom:nomSecteur(id)})),tuiles:(s.apparence&&s.apparence.tuiles)||{},
      contenus:{taches,fiches,maintenance,procedures}},rev:d.rev||0};
  },
  async ecrire(r,items){
    const it=items[0];if(!it)throw new Error('Rien à envoyer.');
    for(let essai=0;essai<4;essai++){
      const d=await google(r,{app:'pack',operation:'pull'}),site=d.site;
      if(!site)throw new Error(this.vide);
      site.droits={roles:it.roles,personnes:it.personnes,secteurs:it.secteurs||{}};
      const p=await google(r,{app:'pack',operation:'push',site,depuis:site.maj});
      if(!p.refuse)return this.lire(r);
    }
    throw new Error('La configuration du pack change sans arrêt sur une tablette : réessayez dans un instant.');
  }};
// « appli@secteur » (ex. taches@resine) : contenus d'un autre secteur que le frittage, rangés à part chez Google.
const secteurApp=x=>{const s=String(x||'').split('@')[1]||'';return /^[a-z0-9-]{1,30}$/.test(s)&&s!=='frittage'?s:''};
function appDe(x){const a=APPS[String(x||'maintenance').split('@')[0]];if(!a)throw new Error('Application inconnue.');return a}
async function lireContenu(r,app){
  const A=appDe(app);if(A.lire)return A.lire(r);
  const d=await google(r,{app:app||'maintenance',operation:'pull',rev:-1});
  if(!d.state&&secteurApp(app)){const v=await secteurVierge(r,app);if(v)return {state:v,rev:0,nouveau:true}}
  return {state:d.state||null,rev:d.rev||0};
}
// Secteur encore vide chez Google (aucune tablette du secteur n'a encore envoyé ses données) : on part de la forme
// des données du frittage, vidée (aucune tâche, fiche, opération, procédure, ni personne, machine ou historique).
// On garde seulement les postes (Matin / Après-midi / Nuit) et les catégories. cfgTs 0 : les listes des tablettes
// du secteur passent devant à leur premier échange.
async function secteurVierge(r,app){
  const base=String(app).split('@')[0],d=await google(r,{app:base,operation:'pull',rev:-1}).catch(()=>null);
  if(!d||!d.state)return null;
  const v={};
  for(const [k,x] of Object.entries(d.state))
    v[k]=k==='v'||k==='postes'||k==='categories'?x:Array.isArray(x)?[]:x&&typeof x==='object'?{}:typeof x==='number'?0:typeof x==='string'?'':x;
  return v;
}
// b.items : éléments à envoyer (plusieurs d'un coup) ; b.supprimer : identifiant d'un élément à retirer.
async function ecrireContenu(r,app,b){
  const A0=appDe(app);
  if(A0.ecrire){
    if(b.supprimer&&!idValide(b.supprimer))throw new Error('Élément inconnu.');
    return A0.ecrire(r,(b.items||[]).map(it=>A0.propre(it)),b.supprimer);
  }
  const A=A0,{state,rev}=await lireContenu(r,app);
  if(!state)throw new Error(A.vide);
  // Brouillons du PC (b.bases = {id: base}) : un élément modifié sur une tablette depuis le début du brouillon n'est
  // PAS écrasé (2026-10-15) ; il est refusé et reste en brouillon. Contrôle fait sur la version de Google lue à l'instant.
  const refuses=[];
  const items=(b.items||[]).filter(it=>{const x=conflitBrouillon(A,state,it,b.bases&&b.bases[it&&it.id]);if(x)refuses.push(x);return !x}).map(A.propre),L=state[A.liste];
  if(!items.length&&!b.supprimer)return {state,rev:rev||0,refuses};
  if(b.supprimer){
    if(!idValide(b.supprimer))throw new Error('Élément inconnu.');
    // Tâche : archivée (les jours déjà enregistrés la gardent), comme dans l'application. Sinon : supprimée partout.
    if(A.liste_){const t=L.find(x=>x.id===b.supprimer);if(t)t.archived=true}
    // Horloge d'une tablette en avance sur ce PC : la suppression doit dater d'après la dernière modification connue,
    // sinon la fusion la ferait revenir.
    else{const v=Number((L.find(o=>o.id===b.supprimer)||{}).updated)||0;
      state[A.liste]=L.filter(o=>o.id!==b.supprimer);state.gone=Object.assign({},state.gone,{[b.supprimer]:Math.max(Date.now(),v)})}
  }
  for(const it of items){
    const l=state[A.liste],i=l.findIndex(o=>o.id===it.id);
    // Même raison : la version envoyée doit être plus récente que celle de Google, sinon la fusion la rejette sans bruit.
    if(i>=0&&typeof it.updated==='number'&&(Number(l[i].updated)||0)>=it.updated)it.updated=Number(l[i].updated)+1;
    if(A.ajuster)A.ajuster(it,i>=0?l[i]:null);
    if(A.liste_&&i>=0&&l[i].archived)it.archived=true;
    if(i<0)l.push(it);else l[i]=it;
  }
  if(A.liste_)state.cfgTs=Math.max(Date.now(),(Number(state.cfgTs)||0)+1);
  const d=await google(r,{app,operation:'sync',state});
  // Relu chez Google : c'est ce que les tablettes recevront.
  const fin=(await lireContenu(r,app)).state||d.state||state;
  if(items.some(it=>A.perdu(it,(fin[A.liste]||[]).find(x=>x.id===it.id)||{})))
    return {state:fin,rev:d.rev||0,refuses,avis:'Le texte est envoyé, mais les photos (ou le « comment faire ») ont été refusés : le script Google doit être mis à jour (recoller Atelier\\Google-Sheet\\Script-Google.txt, installer, puis Gérer les déploiements › Nouvelle version).'};
  return {state:fin,rev:d.rev||0,refuses};
}
// Base d'un brouillon : ce qu'avait Google pour cet élément quand le brouillon a été commencé.
// updated : date de l'élément (maintenance, fiches, procédures) ; empreinte : l'élément entier tel que lu (tâches :
// pas de date par tâche, toute la liste porte un seul cfgTs). null : base inconnue (ancien brouillon) → pas de contrôle.
function basePropre(x){
  if(!x||typeof x!=='object')return null;
  const o={updated:Math.max(0,Number(x.updated)||0)};
  if(typeof x.empreinte==='string'&&x.empreinte.length<=200000)o.empreinte=x.empreinte;
  return o;
}
const empreinte=o=>JSON.stringify(o==null?null:o);
// Renvoie {id, titre, raison} si l'élément a changé chez Google depuis la base du brouillon, sinon null.
function conflitBrouillon(A,state,it,base){
  base=basePropre(base);if(!base||!it||!idValide(it.id))return null;
  const g=(state[A.liste]||[]).find(o=>o&&o.id===it.id),titre=String(A.titre(it)||it.id);
  if(!g){
    // Présent chez Google au début du brouillon, absent maintenant : supprimé sur une tablette entre-temps.
    if(base.updated>0||base.empreinte&&base.empreinte!=='null')return {id:it.id,titre,raison:'supprimé sur une tablette depuis le début de votre brouillon'};
    return null;
  }
  const change=base.empreinte!=null?empreinte(g)!==base.empreinte:(Number(g.updated)||0)>base.updated;
  return change?{id:it.id,titre,raison:'modifié sur une tablette depuis le début de votre brouillon : rechargez-le'}:null;
}
// Base de l'élément tel que Google l'a maintenant (après un envoi incomplet, pour ne pas se refuser soi-même).
function baseActuelle(A,state,id){const g=((state&&state[A.liste])||[]).find(o=>o&&o.id===id);return g?(A.liste_?{updated:0,empreinte:empreinte(g)}:{updated:Number(g.updated)||0}):null}

// --- Brouillons : modifications enregistrées sur ce PC, envoyées aux tablettes plus tard -------------
// brouillons-<appli>.json = {ops:{id:{op,a}}, photos:[ids pas encore envoyées à Google]}
const fichierBrouillons=app=>{const b=String(app||'').split('@')[0],s=secteurApp(app);return path.join(DOSSIER_REGLAGES,'brouillons-'+(APPS[b]?b:'maintenance')+(s?'-'+s:'')+'.json')};
function lireBrouillons(app){
  try{const b=JSON.parse(fs.readFileSync(fichierBrouillons(app),'utf8'));return {ops:b.ops||{},photos:b.photos||[]}}catch(e){return {ops:{},photos:[]}}
}
function ecrireBrouillons(app,b){fs.mkdirSync(DOSSIER_REGLAGES,{recursive:true});fs.writeFileSync(fichierBrouillons(app),JSON.stringify(b))}
function enregistrerBrouillon(app,b){
  const A=appDe(app),op=b.op;
  if(!op||!idValide(op.id))throw new Error('Élément invalide.');
  if(!String(A.titre(op)||'').trim())throw new Error('Donnez un nom à cette '+A.nom+'.');
  // base : version de Google au DÉBUT du brouillon (envoyée par la page), gardée telle quelle aux enregistrements
  // suivants ; elle sert à ne pas écraser une modification faite depuis sur une tablette (envoyerBrouillons).
  const br=lireBrouillons(app),prec=br.ops[op.id];
  const base=prec?(prec.base!==undefined?prec.base:baseAncienne(prec.op)):(basePropre(b.base)||baseAncienne(op));
  br.ops[op.id]={op,a:Date.now(),base};ecrireBrouillons(app,br);
  return br;
}
// Brouillon d'avant le 2026-10-15 (sans base) : la date de l'élément dans le brouillon est celle de Google au moment
// où il a été ouvert (la console ne la change pas) ; sans date, pas de contrôle possible.
const baseAncienne=op=>op&&typeof op.updated==='number'&&op.updated>0?{updated:op.updated}:null;
function abandonnerBrouillon(app,b){const br=lireBrouillons(app);delete br.ops[b.id];ecrireBrouillons(app,br);return br}
// Photo ajoutée dans l'éditeur : gardée sur ce PC, envoyée à Google avec l'élément.
function photoLocale(app,b){
  appDe(app);
  if(!photoValide(b.id))throw new Error('Nom de photo invalide.');
  if(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(b.data||'')||b.data.length>12e6)throw new Error('Photo refusée (format ou taille).');
  fs.mkdirSync(DOSSIER_PHOTOS,{recursive:true});fs.writeFileSync(path.join(DOSSIER_PHOTOS,b.id+'.txt'),b.data);
  const br=lireBrouillons(app);if(!br.photos.includes(b.id))br.photos.push(b.id);ecrireBrouillons(app,br);
  return {ok:true};
}
// Envoi : d'abord les photos des éléments envoyés, puis les éléments en une fois.
async function envoyerBrouillons(r,app,b){
  const A=appDe(app),br=lireBrouillons(app),ids=(b.ids||Object.keys(br.ops)).filter(id=>br.ops[id]);
  if(!ids.length)throw new Error('Rien à envoyer : enregistrez d’abord vos modifications.');
  const items=ids.map(id=>br.ops[id].op);
  const utiles=new Set(items.flatMap(A.photos).filter(Boolean));
  for(const id of br.photos.filter(id=>utiles.has(id))){
    const f=path.join(DOSSIER_PHOTOS,id+'.txt');
    if(fs.existsSync(f))await google(r,{operation:'photo-put',id,data:fs.readFileSync(f,'utf8')},120000);
    const x=lireBrouillons(app);x.photos=x.photos.filter(p=>p!==id);ecrireBrouillons(app,x);
  }
  const bases={};for(const id of ids)bases[id]=br.ops[id].base!==undefined?br.ops[id].base:baseAncienne(br.ops[id].op);
  const res=await ecrireContenu(r,app,{items,bases});
  // Refusés (modifiés sur une tablette depuis le début du brouillon) : gardés en brouillon, rien n'est écrasé.
  const refuses=res.refuses||[],nonEnvoyes=new Set(refuses.map(x=>x.id)),envoyes=ids.filter(id=>!nonEnvoyes.has(id));
  // Envoi incomplet (ancien script Google) : les brouillons sont gardés pour être renvoyés plus tard, avec la base
  // remise sur la version que Google a maintenant (c'est notre envoi : il ne doit pas se refuser lui-même ensuite).
  const x=lireBrouillons(app);
  for(const id of envoyes){if(!x.ops[id])continue;if(!res.avis)delete x.ops[id];else{const nb=baseActuelle(A,res.state,id);if(nb)x.ops[id].base=nb}}
  ecrireBrouillons(app,x);
  if(refuses.length){
    const t=refuses.map(o=>'« '+o.titre+' » : '+o.raison+'.').join('\n');
    res.avis=(envoyes.length?envoyes.length+' élément'+(envoyes.length>1?'s envoyés':' envoyé')+'. ':'')+
      'Non envoyé'+(refuses.length>1?'s':'')+' (gardé'+(refuses.length>1?'s':'')+' en brouillon sur ce PC) :\n'+t+
      '\nPour reprendre la version des tablettes : ouvrez l’élément et cliquez « Annuler » (abandonner le brouillon), puis refaites vos modifications.'+(res.avis?'\n\n'+res.avis:'');
  }
  delete res.refuses;
  return Object.assign(res,{brouillons:x,envoyes:envoyes.length,refuses});
}
// Photos : gardées aussi sur ce PC (dossier des réglages) pour ne pas les retélécharger.
const DOSSIER_PHOTOS=path.join(DOSSIER_REGLAGES,'photos');
const photoValide=id=>/^p[a-z0-9]{6,39}$/.test(id||'');
async function lirePhoto(r,id){
  if(!photoValide(id))throw new Error('Photo inconnue.');
  const f=path.join(DOSSIER_PHOTOS,id+'.txt');
  if(fs.existsSync(f))return {data:fs.readFileSync(f,'utf8')};
  const d=await google(r,{operation:'photo-get',id},90000).catch(e=>{if(/absente/.test(e.message))return null;throw e});
  if(!d||typeof d.data!=='string')return {data:null};
  fs.mkdirSync(DOSSIER_PHOTOS,{recursive:true});fs.writeFileSync(f,d.data);
  return {data:d.data};
}
async function envoyerPhoto(r,b){
  if(!photoValide(b.id))throw new Error('Nom de photo invalide.');
  if(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(b.data||'')||b.data.length>12e6)throw new Error('Photo refusée (format ou taille).');
  await google(r,{operation:'photo-put',id:b.id,data:b.data},120000);
  fs.mkdirSync(DOSSIER_PHOTOS,{recursive:true});fs.writeFileSync(path.join(DOSSIER_PHOTOS,b.id+'.txt'),b.data);
  return {ok:true};
}

// --- Serveur ----------------------------------------------------------------------------
const TYPES={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.json':'application/json; charset=utf-8','.webmanifest':'application/manifest+json','.png':'image/png','.css':'text/css'};
function envoyer(res,code,corps,type){res.writeHead(code,{'Content-Type':type||'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(typeof corps==='string'||Buffer.isBuffer(corps)?corps:JSON.stringify(corps))}
function fichier(res,f){
  if(!fs.existsSync(f)||fs.statSync(f).isDirectory())return envoyer(res,404,'Introuvable','text/plain; charset=utf-8');
  envoyer(res,200,fs.readFileSync(f),TYPES[path.extname(f)]||'application/octet-stream');
}
// Corps des requêtes (correction 2026-11-12, B1 du développeur) : les morceaux réseau sont gardés tels quels et décodés
// UNE seule fois à la fin. Avant, chaque morceau était décodé à part : un « é » coupé entre deux morceaux devenait « �� »
// (texte abîmé en silence dans Google). Au-delà de 15 Mo : refus clair (400) au lieu d'une connexion coupée sans réponse.
function lireCorps(req){return lireCorpsGrand(req,15e6,'Demande trop lourde.')}
// Présentation PowerPoint (2026-11-10) : jusqu'à 30 Mo, soit 40 Mo une fois codée pour l'envoi. Au-delà : la lecture
// continue sans rien garder et la console reçoit un refus clair au lieu d'une connexion coupée.
function lireCorpsGrand(req,max,msgTrop){return new Promise((ok,ko)=>{const l=[];let n=0,trop=false;
  req.on('data',c=>{if(trop)return;n+=c.length;if(n>max){trop=true;l.length=0}else l.push(c)});
  req.on('end',()=>{if(trop)return ko(erreur400(msgTrop||'Fichier trop lourd pour être envoyé (30 Mo au plus).'));try{ok(n?JSON.parse(Buffer.concat(l).toString('utf8')):{})}catch(e){ko(erreur400('Demande illisible.'))}});req.on('error',ko)})}
const hotes=new Set(['localhost:'+PORT,'127.0.0.1:'+PORT]);
// --- Relais Google des pages locales (relecture 2026-10-17, I2) -------------------------------------------------
// L'aperçu des tablettes (/apercu/) et l'appli Maintenance de l'ancienne console (/maintenance-console) ne reçoivent
// JAMAIS le code de la Google Sheet : elles reçoivent un code factice (CODE_RELAIS) et leurs appels à l'adresse du
// script passent par ce serveur (/google-local), qui met le vrai code — seulement avec une session d'ADMINISTRATEUR
// de la console vérifiée (jeton de l'ancienne console ; pour l'aperçu, transmis par l'adresse puis gardé dans l'onglet).
const CODE_RELAIS='RELAIS-CONSOLE';
function scriptRelais(urlG){
  return '<script>(function(){var G='+JSON.stringify(String(urlG||'')).replace(/</g,'\\u003c')+';'+
    'try{var m=/[#&]jeton=([0-9a-f]{64})/.exec(location.hash);if(m){sessionStorage.setItem("apercu-jeton",m[1]);'+
    'var n=function(){try{if(/jeton=/.test(location.hash))history.replaceState(history.state,"",location.pathname+location.search)}catch(e){}};'+
    'n();document.addEventListener("DOMContentLoaded",n);addEventListener("load",n);setTimeout(n,1500);setTimeout(n,4000)}}catch(e){}'+
    'try{if(localStorage.getItem("pack-google-code")!=="'+CODE_RELAIS+'")localStorage.setItem("pack-google-code","'+CODE_RELAIS+'")}catch(e){}'+
    'var f=window.fetch;window.fetch=function(u,o){var s=typeof u==="string"?u:(u&&u.url)||"";'+
    'var a=s.split("?")[0];if((G&&a===G)||/^https:\\/\\/script\\.google\\.com\\/macros\\/s\\/[\\w-]+\\/exec$/.test(a)){var j="";try{j=sessionStorage.getItem("apercu-jeton")||sessionStorage.getItem("console-jeton")||""}catch(e){}'+
    'return f.call(window,"/google-local",{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8","X-Jeton":j},body:o&&o.body,signal:o&&o.signal,cache:"no-store"})}'+
    'return f.apply(window,arguments)}})()</script>';
}
async function relaisGoogle(req,res){
  if(req.method!=='POST'||(req.headers.origin&&!hotes.has(req.headers.origin.replace(/^https?:\/\//,''))))return envoyer(res,403,{status:403,data:{error:'Accès refusé.'}});
  const m=await sessionConsole(String(req.headers['x-jeton']||''));
  if(m===undefined)return envoyer(res,503,{status:503,data:{error:'Google ne répond pas.'}});
  if(!m||!m.admin)return envoyer(res,401,{status:401,data:{error:'Aperçu : ouvrez-le depuis l’ancienne console, connecté en administrateur.'}});
  const g=reglages().google||{};if(!g.url||!g.code)return envoyer(res,503,{status:503,data:{error:'Google Sheet non réglée sur ce PC.'}});
  let b;try{b=await lireCorps(req)}catch(e){return envoyer(res,400,{status:400,data:{error:'Demande illisible.'}})}
  if(!b||typeof b!=='object'||Array.isArray(b))return envoyer(res,400,{status:400,data:{error:'Demande illisible.'}});
  if(b.key===CODE_RELAIS)b.key=g.code;
  // Tablette fantôme (console 2026-11-12, B2) : l'appli Maintenance de l'ancienne console et l'aperçu tournent sur CE PC,
  // pas sur une tablette : leur identifiant d'appareil n'est pas transmis (sinon chaque navigateur du bureau apparaissait
  // dans Tablettes & alertes comme une nouvelle tablette « Maintenance » sans zone).
  delete b.appareil;
  try{const r=await fetch(g.url,{method:'POST',body:JSON.stringify(b),redirect:'follow',signal:AbortSignal.timeout(120000)});return envoyer(res,200,await r.text())}
  catch(e){return envoyer(res,503,{status:503,data:{error:'Google ne répond pas.'}})}
}
// --- Écran tournant (2026-10-21, maquette validée) ---------------------------------------------------------------
// UNE télé montre à tour de rôle les écrans télé existants (/ecran, /ecran-maintenance?secteur=…). Réglage gardé dans
// reglages.json de CE PC (clé « tournant »), pas dans Google : chaque télé a le sien. Aucun secret dedans.
// Catalogue = écrans qui existent sur ce PC (l'atelier + la maintenance de chaque secteur du pack) ; un écran nouveau
// (nouveau secteur, nouvelle appli plus tard) apparaît DÉCOCHÉ à la fin de la liste.
// Par défaut (proposition acceptée) : Lancements 30 s, Maintenance 20 s par page, priorité aux retards, nuit décochée.
// Couleurs (2026-10-21) : UN thème pour tous les écrans du tour (theme=clair|sombre dans chaque cadre), Sombre par défaut.
const TOURNANT_DUREES=[10,15,20,30,45,60,90,120];
function tournantCatalogue(){
  let secs=[];try{secs=fs.readdirSync(path.join(pack,'secteurs')).filter(f=>/^[a-z0-9-]+\.js$/.test(f)&&f!=='modele-vierge.js').map(f=>f.slice(0,-3))}catch(e){}
  secs.sort((a,b)=>a==='frittage'?-1:b==='frittage'?1:a.localeCompare(b));
  // Lancements (2026-10-21) : plusieurs pages quand il y a beaucoup de machines (8 par page) ; c'est l'écran tournant qui les fait défiler.
  // Fours (2026-10-22) : un écran (6 fours) ; un plateau à sortir le fait passer devant les autres (ecran-tournant.html).
  return [{id:'lancements',nom:'Écran de l’atelier (lancements)',court:'Lancements',duree:30,pages:true},{id:'fours',nom:'Fours (minuteurs)',court:'Fours',duree:20,pages:false}]
    .concat(secs.map(s=>({id:'maintenance:'+s,secteur:s,secteurNom:nomSecteur(s),nom:'Maintenance — '+nomSecteur(s),court:'Maintenance '+nomSecteur(s),duree:20,pages:true})))
    // Liaison (2026-10-23) : une page par secteur (messages ouverts : fait, machine, état). Arrive décochée.
    .concat(secs.map(s=>({id:'liaison:'+s,secteur:s,secteurNom:nomSecteur(s),nom:'Cahier de liaison — '+nomSecteur(s),court:'Liaison '+nomSecteur(s),duree:20,pages:true})));
}
function tournantLire(){return tournantDepuis(reglages().tournant||null)}
// Télés pilotées à distance (2026-11-10) : même lecture pour le tour d'UNE télé (site.teles[id].tournant, dans Google).
function tournantDepuis(t){
  const cat=tournantCatalogue(),deja=!!(t&&Array.isArray(t.ecrans));
  // Premier réglage : l'atelier, le frittage et le fraisage cochés (comme la maquette) ; ensuite, ce qui est enregistré.
  const parDefaut=id=>['lancements','maintenance:frittage','maintenance:fraisage'].includes(id);
  const lus=deja?t.ecrans.filter(e=>e&&cat.some(c=>c.id===e.id)):[];
  const ecrans=lus.map(e=>Object.assign({},cat.find(c=>c.id===e.id),{on:!!e.on,duree:TOURNANT_DUREES.includes(e.duree)?e.duree:cat.find(c=>c.id===e.id).duree}))
    .concat(cat.filter(c=>!lus.some(e=>e.id===c.id)).map(c=>Object.assign({},c,{on:deja?false:parDefaut(c.id),nouveau:deja})));
  const n=t&&t.nuit||{},hh=v=>/^([01]\d|2[0-3]):[0-5]\d$/.test(v||'');
  return {ecrans,priorite:t&&typeof t.priorite==='boolean'?t.priorite:true,
    nuit:{on:!!n.on,debut:hh(n.debut)?n.debut:'06:00',fin:hh(n.fin)?n.fin:'21:00'},theme:t&&t.theme==='clair'?'clair':'sombre',maj:t&&t.maj||0,durees:TOURNANT_DUREES,
    messages:tournantMessagesLus(t&&t.messages),messagesMax:TOURNANT_MSG_MAX};
}
// Messages dans le tour (2026-11-10, demande de l'utilisateur : « faire tourner des messages avec Lynk ») : intercalés
// entre les écrans du tour d'une télé (un message après chaque écran, à tour de rôle). 10 au plus ; chacun :
// {titre (80), texte (600), niveau 'info'|'important', duree (TOURNANT_DUREES), on, fin (0 = sans fin, sinon horodatage)}.
// Un message dont l'heure de fin est passée reste dans la liste (la console le dit « terminé ») mais n'est plus affiché.
const TOURNANT_MSG_MAX=10;
const msgTexte=(v,n)=>String(v==null?'':v).replace(/\r\n?/g,'\n').trim().slice(0,n);
// Lecture (réglage déjà vérifié à l'écriture) : on ne garde que les champs connus, sans jamais lever d'erreur.
function tournantMessagesLus(l){
  return (Array.isArray(l)?l:[]).filter(m=>m&&typeof m==='object').slice(0,TOURNANT_MSG_MAX).map(m=>({titre:msgTexte(m.titre,80),texte:msgTexte(m.texte,600),
    niveau:m.niveau==='important'?'important':'info',duree:TOURNANT_DUREES.includes(m.duree)?m.duree:20,on:m.on===undefined?true:!!m.on,fin:Number(m.fin)>0?Math.round(Number(m.fin)):0}))
    .filter(m=>m.titre||m.texte);
}
// Écriture : tout est vérifié, une erreur claire plutôt qu'un message déformé en silence.
function tournantMessagesPropres(l){
  if(!Array.isArray(l))throw Object.assign(new Error('Liste des messages invalide.'),{status:400});
  if(l.length>TOURNANT_MSG_MAX)throw Object.assign(new Error(TOURNANT_MSG_MAX+' messages au plus dans le tour.'),{status:400});
  return l.map((m,i)=>{
    m=m&&typeof m==='object'?m:{};
    const titre=msgTexte(m.titre,80),texte=msgTexte(m.texte,600),fin=Number(m.fin)||0;
    if(!titre&&!texte)throw Object.assign(new Error('Message n° '+(i+1)+' : écrivez son titre ou son texte.'),{status:400});
    if(!TOURNANT_DUREES.includes(m.duree))throw Object.assign(new Error('Message n° '+(i+1)+' : durée non prévue (10 s à 2 min).'),{status:400});
    // Heure de fin : 0 (sans fin) ou une date plausible (après 2024, avant dans 2 ans) ; déjà passée = accepté (il est sauté).
    if(fin!==0&&!(Number.isFinite(fin)&&fin>1704067200000&&fin<Date.now()+2*366*864e5))throw Object.assign(new Error('Message n° '+(i+1)+' : heure de fin invalide.'),{status:400});
    // « on » absent = affiché (comme un message nouveau) ; sinon sa valeur (false, 0… = décoché).
    return {titre,texte,niveau:m.niveau==='important'?'important':'info',duree:m.duree,on:m.on===undefined?true:!!m.on,fin:Math.round(fin)};
  });
}
function tournantEcrire(b){
  const r=reglages(),avant=r.tournant&&r.tournant.maj||0;
  // Contrôle de version : réglage changé ailleurs (autre fenêtre de la console) depuis la lecture → refus, pas d'écrasement.
  if(Number(b.depuis||0)!==avant)throw Object.assign(new Error('Le réglage de l’écran tournant a changé ailleurs : la page est relue.'),{status:409});
  r.tournant=Object.assign(tournantPropre(b,r.tournant),{maj:Math.max(Date.now(),avant+1)});
  enregistrer(r);
  return tournantLire();
}
// Réglage du tour vérifié (écrans connus, durées prévues, horaires) : écran tournant de ce PC et télés (2026-11-10).
// ancien : réglage d'avant (thème gardé si la page ne l'envoie pas).
function tournantPropre(b,ancien){
  const cat=tournantCatalogue(),hh=v=>/^([01]\d|2[0-3]):[0-5]\d$/.test(v||'');
  if(!Array.isArray(b.ecrans))throw Object.assign(new Error('Liste des écrans manquante.'),{status:400});
  const ecrans=[];
  for(const e of b.ecrans){
    if(!e||!cat.some(c=>c.id===e.id)||ecrans.some(x=>x.id===e.id))continue;
    if(!TOURNANT_DUREES.includes(e.duree))throw Object.assign(new Error('Durée non prévue (10 s à 2 min).'),{status:400});
    ecrans.push({id:e.id,on:!!e.on,duree:e.duree});
  }
  const n=b.nuit||{};
  if(n.on&&(!hh(n.debut)||!hh(n.fin)||n.debut===n.fin))throw Object.assign(new Error('Horaires de travail invalides.'),{status:400});
  // Thème absent (console plus ancienne qui ne le connaît pas) : on garde celui qui était enregistré.
  const theme=b.theme==='clair'||b.theme==='sombre'?b.theme:(ancien&&ancien.theme==='clair'?'clair':'sombre');
  // Messages (2026-11-10) : réglés seulement depuis console › Télés. Liste non envoyée (éditeur de l'écran tournant du
  // PC, console plus ancienne) : ceux de l'ancien réglage sont gardés tels quels, jamais perdus par erreur.
  const messages=b.messages==null?tournantMessagesLus(ancien&&ancien.messages):tournantMessagesPropres(b.messages);
  const o={ecrans,priorite:b.priorite!==false,theme,nuit:{on:!!n.on,debut:hh(n.debut)?n.debut:'06:00',fin:hh(n.fin)?n.fin:'21:00'}};
  if(messages.length)o.messages=messages;
  return o;
}

// --- Télés pilotées à distance (2026-11-10, demande de l'utilisateur) -------------------------------------------
// Une télé = un Raspberry Pi qui ouvre /tele?id=<identifiant> (choisi à la préparation de sa carte, ex. tele-fours).
// Ce qu'elle affiche est rangé avec la configuration du pack dans Google (site.teles, comme site.parc) : la console du
// bureau le règle, le Pi le relit (15 s au plus). Rien de secret dedans ; l'adresse d'une page web s'appelle « adresse »
// (pas « url » : règle n° 7, la console en ligne retirerait le champ).
//   site.teles = {<id>: {nom, contenu, tournant?, maj, par}}
//   contenu = {type:'aucun'} | {type:'ecran', ecran:'tournant'|'fours'|'lancements'|'maintenance'|'liaison', secteur?, theme}
//           | {type:'message', titre, texte, niveau:'info'|'important', fin (0 = sans fin), ensuite (contenu repris à la fin)}
//           | {type:'image', nom, images:[photos], duree (s par page)} | {type:'web', adresse, recharger (min)}
//           | {type:'video', videos:[{id, nom, taille, empreinte, ext, duree}] (10 au plus, jouées à la suite, sans fin), son}
// Le script Google garde la configuration du pack telle quelle (traiterPack_). Les vidéos elles-mêmes passent par les
// opérations video-* du script (2026-11-12 : script Google à mettre à jour pour elles, voir « Vidéos des télés »).
const TELE_ID=/^[a-z0-9][a-z0-9-]{0,39}$/;
const TELE_ECRANS=['tournant','fours','lancements','maintenance','liaison'];
const TELE_DUREES_IMG=[5,10,15,20,30,45,60,90,120],TELE_IMAGES_MAX=30,TELE_RECHARGER=[0,5,15,60];
const secteursTele=()=>tournantCatalogue().filter(c=>/^maintenance:/.test(c.id)).map(c=>c.secteur);
const erreur400=m=>Object.assign(new Error(m),{status:400});
// lecture (2026-11-12, développeur B5) : contenu LU dans Google, revérifié avant d'être donné à la télé ; un message
// terminé n'y est pas une erreur (la page /tele passe d'elle-même à ce qui suit).
function teleContenuPropre(c,lecture){
  c=c&&typeof c==='object'?c:{};
  const t=(v,n)=>String(v==null?'':v).replace(/\r\n?/g,'\n').trim().slice(0,n);
  if(c.type==='ecran'){
    if(!TELE_ECRANS.includes(c.ecran))throw erreur400('Écran Lynk inconnu.');
    const o={type:'ecran',ecran:c.ecran,theme:c.theme==='clair'?'clair':'sombre'};
    if(c.ecran==='maintenance'||c.ecran==='liaison'){if(!secteursTele().includes(c.secteur))throw erreur400('Choisissez le secteur de l’écran.');o.secteur=c.secteur}
    return o;
  }
  if(c.type==='message'){
    const titre=t(c.titre,80),texte=t(c.texte,600),fin=Math.round(Number(c.fin)||0);
    if(!titre&&!texte)throw erreur400('Écrivez le titre ou le texte du message.');
    if(!lecture&&fin>0&&fin<Date.now()-60000)throw erreur400('L’heure de fin du message est déjà passée.');
    // À la fin du message, la télé reprend ce qu'elle affichait avant (jamais un autre message).
    const e=c.ensuite&&typeof c.ensuite==='object'&&!['message','aucun'].includes(c.ensuite.type)?teleContenuPropre(c.ensuite,lecture):null;
    return {type:'message',titre,texte,niveau:c.niveau==='important'?'important':'info',fin:fin>0?fin:0,ensuite:e};
  }
  if(c.type==='image'){
    const images=[...new Set(Array.isArray(c.images)?c.images:[])].filter(photoValide).slice(0,TELE_IMAGES_MAX);
    if(!images.length)throw erreur400('Aucune image envoyée.');
    return {type:'image',nom:t(c.nom,80),images,duree:TELE_DUREES_IMG.includes(Number(c.duree))?Number(c.duree):15,remplir:c.remplir===true};
  }
  if(c.type==='web'){
    let u;try{u=new URL(t(c.adresse,500))}catch(e){throw erreur400('Adresse de page invalide : elle commence par https:// ou http://.')}
    if(!/^https?:$/.test(u.protocol))throw erreur400('Adresse de page invalide : https:// ou http:// seulement.');
    return {type:'web',adresse:u.href,recharger:TELE_RECHARGER.includes(Number(c.recharger))?Number(c.recharger):0};
  }
  if(c.type==='video'){
    const l=Array.isArray(c.videos)?c.videos:[];
    if(!l.length)throw erreur400('Ajoutez au moins une vidéo.');
    if(l.length>VIDEOS_MAX)throw erreur400(VIDEOS_MAX+' vidéos au plus.');
    return {type:'video',videos:l.map(videoPropre),son:c.son===true,remplir:c.remplir===true};
  }
  return {type:'aucun'};
}

// --- Vidéos des télés (2026-11-12, demandes : « mettre une vidéo et la faire tourner en boucle », « l'envoyer par la
// console », « plusieurs vidéos qui tournent les unes après les autres ») ----------------------------------------------
// Le PC et les télés sont sur des réseaux séparés : la vidéo passe par Google (opérations video-* du script, dossier
// Drive « Atelier — vidéos »), en morceaux de 2 Mo. La console l'envoie morceau par morceau (/api/tele-video-morceau,
// relayé ici) ; le programme du Raspberry Pi la télécharge en arrière-plan, vérifie son empreinte SHA-256, la garde dans
// <réglages>/videos (lue ensuite sans réseau) et la sert à la page /tele par /video/<id>.<ext> (requêtes Range).
// Identifiant = « v » + début de l'empreinte : le fichier ne porte jamais le nom donné par l'utilisateur (aucun chemin).
const VIDEO_ID=/^v[0-9a-f]{24}$/,VIDEO_EXTS=['mp4','webm','m4v','mov'],VIDEO_MORCEAU=2097152,VIDEO_MAX=314572800,VIDEOS_MAX=10;
// mp3 (2026-11-16) : morceaux de la musique de fond, rangés et servis comme les vidéos (voir « Musique de fond »).
const VIDEO_TYPES={mp4:'video/mp4',m4v:'video/mp4',webm:'video/webm',mov:'video/quicktime',mp3:'audio/mpeg'};
// Pi : pause entre deux morceaux (Google ménagé), marge de place gardée, vidéos plus utilisées gardées au plus.
const VIDEO_PAUSE=1000,VIDEO_MARGE=1024*1024*1024,VIDEOS_ANCIENNES=10;
const DOSSIER_VIDEOS=path.join(DOSSIER_REGLAGES,'videos');
// Nom affiché (celui du fichier choisi sur le PC) : jamais un chemin ; l'extension dit le format.
function videoNom(n){
  n=String(n==null?'':n).trim();
  if(!n||n.length>100||/[\/\\\u0000-\u001f]/.test(n)||n.startsWith('.'))throw erreur400('Nom de vidéo refusé (« '+n.slice(0,60)+' ») : un nom de fichier simple, sans dossier.');
  const m=/\.([a-z0-9]{2,4})$/i.exec(n);
  if(!m||!VIDEO_EXTS.includes(m[1].toLowerCase()))throw erreur400('Format de vidéo refusé (« '+n.slice(0,60)+' ») : MP4, WebM, M4V ou MOV seulement.');
  return n;
}
function videoPropre(v){
  v=v&&typeof v==='object'?v:{};
  const empreinte=String(v.empreinte||'').toLowerCase(),nom=videoNom(v.nom),taille=Math.round(Number(v.taille));
  if(!/^[0-9a-f]{64}$/.test(empreinte)||v.id!=='v'+empreinte.slice(0,24))throw erreur400('Vidéo « '+nom+' » : empreinte invalide.');
  if(!(taille>0&&taille<=VIDEO_MAX))throw erreur400('Vidéo « '+nom+' » trop lourde : 300 Mo au plus.');
  const duree=Math.round(Number(v.duree)||0);
  return {id:v.id,nom,taille,empreinte,ext:/\.([a-z0-9]+)$/i.exec(nom)[1].toLowerCase(),duree:duree>0&&duree<=86400?duree:0};
}
// Vidéos d'un contenu (ou de ce qu'un message remplace) ; un contenu lu dans Google est revérifié avant de servir.
function videosDe(c){
  const l=c&&c.type==='video'?c.videos:c&&c.type==='message'&&c.ensuite&&c.ensuite.type==='video'?c.ensuite.videos:null;
  return (Array.isArray(l)?l:[]).filter(v=>v&&VIDEO_ID.test(v.id)&&VIDEO_EXTS.includes(v.ext)&&v.id==='v'+String(v.empreinte).slice(0,24)&&/^[0-9a-f]{64}$/.test(v.empreinte)&&v.taille>0&&v.taille<=VIDEO_MAX).slice(0,VIDEOS_MAX);
}
// Appel vidéo à Google : un script pas encore mis à jour répond n'importe quoi → message clair.
async function videoGoogle(r,corps,delai){
  try{return await google(r,corps,delai)}
  catch(e){
    if(/vid[ée]o|morceau|injoignable|occupé|manquant|ne répond pas/i.test(e.message))throw e;
    throw new Error('Le script Google n’a pas encore la partie « vidéos » : il faut d’abord le mettre à jour (Apps Script › Déployer › Nouvelle version). Détail : '+e.message);
  }
}
// --- Préparation d'une vidéo sur le PC du bureau (2026-11-12, demande : « les vidéos viendront de YouTube ; vérifier
// la conversion et convertir s'il faut ») -----------------------------------------------------------------------------
// La console donne le fichier choisi à CE programme (POST /api/tele-video-fichier, copie locale, 4 Go au plus), qui :
//   1. le VÉRIFIE (lecture de l'en-tête MP4 : codecs, taille d'image, images/s, débit) ;
//   2. le CONVERTIT si la télé ne saurait pas bien le lire, par Windows lui-même (Windows.Media.Transcoding : rien à
//      installer) en MP4 H.264 + AAC, 1080p au plus (jamais agrandi), 8 Mbit/s au plus ; le résultat est revérifié ;
//   3. calcule son empreinte et l'ENVOIE à Google en morceaux (reprise : seuls les morceaux manquants partent).
// La console suit l'avancement (GET /api/tele-video-etat). Une seule préparation à la fois.
// Cible (Raspberry Pi, Chromium) : MP4 H.264 profil Baseline/Main/High, 1920 × 1080 au plus, 60 i/s au plus, son AAC.
const VIDEO_SOURCE_MAX=4*1024**3,VIDEO_SOURCE_EXTS=['mp4','m4v','mov','webm','mkv'],VIDEO_DEBIT_MAX=8e6,VIDEO_DEBIT_TOLERE=10e6;
const CODECS={avc1:'H.264',avc3:'H.264',hvc1:'H.265 (HEVC)',hev1:'H.265 (HEVC)',av01:'AV1',vp09:'VP9',vp08:'VP8',mp4v:'MPEG-4',
  mp4a:'AAC',Opus:'Opus','ac-3':'Dolby AC-3','ec-3':'Dolby E-AC-3','.mp3':'MP3',encv:'protégée',enca:'protégé'};
