  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'lynk-video-')),f=path.join(dir,'source.'+nom.split('.').pop().toLowerCase());
  try{
    await new Promise((ok,ko)=>{let n=0;const o=fs.createWriteStream(f);
      req.on('data',c=>{n+=c.length;if(n>taille)req.destroy(new Error('trop'))});req.on('error',ko);o.on('error',ko);o.on('finish',()=>n===taille?ok():ko(new Error('copie incomplète')));req.pipe(o)});
  }catch(e){VJOB.cours=null;try{fs.rmSync(dir,{recursive:true,force:true})}catch(x){}throw erreur400('Copie de la vidéo interrompue : réessayez.')}
  for(const [id,j] of VJOB.jobs)if(Date.now()-j.t>3600000)VJOB.jobs.delete(id);
  VJOB.jobs.set(job.id,job);
  videoPreparer(job,f,dir).catch(e=>{job.etape='erreur';job.erreur=e.message||String(e);job.texte='';console.error('Vidéo '+nom+' : '+job.erreur)})
    .finally(()=>{VJOB.cours=null;try{fs.rmSync(dir,{recursive:true,force:true})}catch(e){}});
  return {job:job.id};
}
async function videoPreparer(job,f,dir){
  if(job.musique)return musiquePreparer(job,f);
  job.etape='verification';job.texte='Vérification de la vidéo…';
  const a=videoAnalyse(f),vd=videoVerdict(a);
  job.analyse=videoResume(a);
  if(vd.refus)throw new Error(vd.refus);
  let final=f,nom=job.nom,duree=a.duree||0,cache='';
  if(vd.raisons.length){
    job.verdict='⚠ À convertir : '+vd.raisons.join(', ');
    fs.mkdirSync(DOSSIER_CONVERSIONS,{recursive:true});
    for(const x of fs.readdirSync(DOSSIER_CONVERSIONS))try{const p=path.join(DOSSIER_CONVERSIONS,x);if(Date.now()-fs.statSync(p).mtimeMs>7*864e5)fs.rmSync(p,{force:true})}catch(e){}
    job.texte='Vérification : empreinte de la vidéo…';
    cache=path.join(DOSSIER_CONVERSIONS,(await empreinteFichier(f)).slice(0,32)+'.mp4');
    if(fs.existsSync(cache)){final=cache;job.dejaConvertie=true;job.texte='Conversion déjà faite : reprise de l’envoi.'}
    else{job.texte='Conversion en MP4 H.264 par Windows…';const c=await videoConvertir(job,f,a,dir);fs.renameSync(c,cache);final=cache}
    const b=videoAnalyse(final);
    if(!b.video||!/^avc[13]$/.test(b.video.codec)||(b.audio&&b.audio.codec!=='mp4a')){try{fs.rmSync(cache,{force:true})}catch(e){}throw new Error('Conversion ratée (le résultat n’est pas du MP4 H.264) : téléchargez la vidéo en MP4 H.264.')}
    job.analyseConvertie=videoResume(b);duree=b.duree||duree;
    nom=nom.replace(/\.[a-z0-9]+$/i,'')+'.mp4';
  }else job.verdict='✓ Prête pour la télé';
  const taille=fs.statSync(final).size;
  if(taille>VIDEO_MAX)throw new Error('Vidéo trop lourde pour la télé ('+Math.round(taille/1048576)+' Mo, '+Math.round(VIDEO_MAX/1048576)+' Mo au plus) : coupez-la ou réduisez-la.');
  await envoyerDansGoogle(job,final,nom,taille,duree,videoPropre);
}
// Empreinte puis envoi dans Google en morceaux (opérations video-* du script), commun aux vidéos et à la musique de fond
// (2026-11-16) ; regles : mêmes règles que l'enregistrement d'une télé (videoPropre ou morceauPropre). Le résultat est
// rangé dans job.video (nom gardé pour la console, même pour un morceau de musique).
async function envoyerDansGoogle(job,final,nom,taille,duree,regles){
  job.etape='empreinte';job.texte='Calcul de l’empreinte…';job.pct=null;
  const empreinte=await empreinteFichier(final),id='v'+empreinte.slice(0,24),total=Math.ceil(taille/VIDEO_MORCEAU);
  regles({id,nom,taille,empreinte}); // mêmes règles que l'enregistrement d'une télé
  job.etape='envoi';
  const r=reglages(),info=await videoGoogle(r,{operation:'video-info',id},30000).catch(e=>{throw envoiCoupe(e)});
  const deja=new Set(info&&info.existe&&Array.isArray(info.presents)?info.presents:[]);
  const fd=fs.openSync(final,'r');
  try{
    let faits=deja.size;
    for(let n=0;n<total;n++){
      if(deja.has(n))continue;
      job.pct=Math.floor(100*faits/total);job.texte='Envoi dans Google : '+(faits+1)+' / '+total+(deja.size?' (reprise)':'');
      const lg=Math.min(VIDEO_MORCEAU,taille-n*VIDEO_MORCEAU),b=Buffer.alloc(lg);fs.readSync(fd,b,0,lg,n*VIDEO_MORCEAU);
      for(let k=1;;k++){
        try{await videoGoogle(r,{operation:'video-put',id,n,total,taille,empreinte,nom,data:b.toString('base64'),empreinteMorceau:sha256(b)},180000);break}
        catch(e){if(k>=3||/refus|invalide|lourde|mettre à jour|partie « vidéos »/i.test(e.message))throw envoiCoupe(e);
          await new Promise(ok=>setTimeout(ok,3000*k))}
      }
      faits++;
    }
  }finally{fs.closeSync(fd)}
  // Conversion gardée 7 jours (développeur 2026-11-12, B4 ; effacée par le ménage ci-dessus) : si le suivi de la console
  // a été coupé, la même vidéo remise reprend tout de suite (même empreinte, déjà dans Google) au lieu de 2 h de conversion.
  Object.assign(job,{etape:'fini',pct:100,texte:'« '+nom+' » envoyée ('+total+' / '+total+').',video:{id,nom,taille,empreinte,duree:Math.round(duree)}});
}
// Coupure pendant l'envoi : ce qui est déjà dans Google y reste ; la même vidéo ajoutée de nouveau reprend là.
const envoiCoupe=e=>new Error(/injoignable|ne répond pas|occupé/i.test(e.message)?'Envoi interrompu ('+e.message+') : ajoutez de nouveau la même vidéo, l’envoi reprendra où il s’était arrêté.':e.message);
// GET /api/tele-video-etat?job= : avancement (vérification, conversion, envoi), puis la vidéo prête à mettre dans la liste.
function videoEtatJob(url){
  const j=VJOB.jobs.get(String(url.searchParams.get('job')||''));
  if(!j)throw erreur400('Préparation inconnue (le programme a redémarré ?) : ajoutez de nouveau la vidéo.');
  return {etape:j.etape,pct:j.pct,texte:j.texte,analyse:j.analyse||'',verdict:j.verdict||'',analyseConvertie:j.analyseConvertie||'',dejaConvertie:!!j.dejaConvertie,erreur:j.erreur||'',video:j.video||null};
}
// Enregistrement d'une télé : chaque vidéo doit être ENTIÈRE dans Google (sinon la télé ne pourrait pas la télécharger).
// quoi (2026-11-16) : « Le morceau » pour la musique de fond.
async function videosVerifier(r,l,quoi='La vidéo'){
  const f=quoi==='La vidéo'?['la','celle']:['le','celui'];
  for(const v of l.filter((x,i)=>l.findIndex(y=>y.id===x.id)===i)){
    const i=await videoGoogle(r,{operation:'video-info',id:v.id},30000);
    if(!i||!i.existe||!i.complete)throw erreur400(quoi+' « '+v.nom+' » n’est pas entièrement dans Google : ajoutez-'+f[0]+' de nouveau (l’envoi reprend où il s’était arrêté).');
    if(i.taille!==v.taille||i.empreinte!==v.empreinte)throw erreur400(quoi+' « '+v.nom+' » ne correspond pas à '+f[1]+' rangé'+(f[0]==='la'?'e':'')+' dans Google : ajoutez-'+f[0]+' de nouveau.');
  }
}

// --- Musique de fond des télés (2026-11-16, demande : « possible de diffuser de la musique ? » ; choix de
// l'utilisateur : musique EN FOND, derrière ce que la télé affiche déjà, à partir de SES fichiers MP3 envoyés depuis la
// console, comme les vidéos) ---------------------------------------------------------------------------------------------
// Réglage (console › Télés, champ nouveau, aucune clé existante touchée) :
//   site.teles[id].musique = {actif, morceaux:[{id, nom, taille, empreinte, duree}], aleatoire, volume (5 à 100 %),
//                             horaire, debut:'HH:MM', fin:'HH:MM'}
// Les morceaux suivent EXACTEMENT le chemin des vidéos : envoi par la console (/api/tele-video-fichier&genre=musique),
// rangés dans Google par les opérations video-* (identifiant « v » + empreinte ; le script Google doit accepter le nom
// en .mp3 : mise à jour du script), téléchargés par le programme du Pi (videosVoulues), servis par /video/<id>.mp3.
// La page /tele les joue à la suite (ou au hasard), en boucle, sans s'arrêter quand le contenu change ; elle coupe la
// musique pendant la veille, une vidéo avec le son, un message « Important » et la sirène des fours.
// horaire : musique seulement de debut à fin (fin avant debut = passe minuit), heure de Paris, calculée par le Pi.
// 2026-11-16 « pas de limite pour la taille des MP3 » : plafond = celui du circuit Google (VIDEO_MAX, 300 Mo, fixé par le
// script en ligne) ; au-delà, seul le script pourrait l'accepter.
const MUSIQUE_MAX_OCTETS=VIDEO_MAX,MUSIQUES_MAX=50;
const MUSIQUE_SCRIPT='Le script Google n’accepte pas encore la musique (MP3) : il faut d’abord le mettre à jour (Apps Script › Déployer › Nouvelle version), puis ajouter de nouveau le morceau.';
// Nom affiché (celui du fichier choisi sur le PC) : jamais un chemin, MP3 seulement.
function musiqueNom(n){
  n=String(n==null?'':n).trim();
  if(!n||n.length>100||/[\/\\\u0000-\u001f]/.test(n)||n.startsWith('.'))throw erreur400('Nom de morceau refusé (« '+n.slice(0,60)+' ») : un nom de fichier simple, sans dossier.');
  if(!/\.mp3$/i.test(n))throw erreur400('Format refusé (« '+n.slice(0,60)+' ») : MP3 seulement.');
  return n;
}
function morceauPropre(v){
  v=v&&typeof v==='object'?v:{};
  const empreinte=String(v.empreinte||'').toLowerCase(),nom=musiqueNom(v.nom),taille=Math.round(Number(v.taille));
  if(!/^[0-9a-f]{64}$/.test(empreinte)||v.id!=='v'+empreinte.slice(0,24))throw erreur400('Morceau « '+nom+' » : empreinte invalide.');
  if(!(taille>0&&taille<=MUSIQUE_MAX_OCTETS))throw erreur400('Morceau « '+nom+' » trop lourd : '+Math.round(MUSIQUE_MAX_OCTETS/1048576)+' Mo au plus.');
  const duree=Math.round(Number(v.duree)||0);
  return {id:v.id,nom,taille,empreinte,ext:'mp3',duree:duree>0&&duree<=86400?duree:0};
}
// Lecture (Google, liste de la console, page /tele) : champs connus seulement, jamais d'erreur ; null = pas de réglage.
function musiqueLue(m){
  if(!m||typeof m!=='object')return null;
  const hh=VeilleTele.HH,vol=Math.round(Number(m.volume));
  const morceaux=(Array.isArray(m.morceaux)?m.morceaux:[]).map(v=>{try{return morceauPropre(v)}catch(e){return null}}).filter(Boolean)
    .filter((v,i,l)=>l.findIndex(x=>x.id===v.id)===i).slice(0,MUSIQUES_MAX);
  return {actif:m.actif===true,morceaux,aleatoire:m.aleatoire===true,volume:vol>=5&&vol<=100?vol:50,
    horaire:m.horaire===true,debut:hh.test(m.debut)?m.debut:'08:00',fin:hh.test(m.fin)?m.fin:'17:00'};
}
// Écriture (console › Télés) : tout est vérifié, une erreur claire plutôt qu'un réglage déformé.
function musiquePropre(m){
  if(m==null)return null;
  if(typeof m!=='object')throw erreur400('Réglage de la musique de fond invalide.');
  const l=Array.isArray(m.morceaux)?m.morceaux:[];
  if(l.length>MUSIQUES_MAX)throw erreur400('Musique de fond : '+MUSIQUES_MAX+' morceaux au plus.');
  const morceaux=l.map(morceauPropre).filter((v,i,x)=>x.findIndex(y=>y.id===v.id)===i);
  if(m.actif===true&&!morceaux.length)throw erreur400('Musique de fond : ajoutez au moins un morceau MP3 (ou décochez « Musique de fond »).');
  const hh=VeilleTele.HH;
  if(m.actif===true&&m.horaire===true){
    if(!hh.test(m.debut)||!hh.test(m.fin))throw erreur400('Musique de fond : donnez l’heure de début et l’heure de fin (forme 08:00).');
    if(m.debut===m.fin)throw erreur400('Musique de fond : l’heure de début et l’heure de fin sont les mêmes. Choisissez par exemple de 08:00 à 17:00.');
  }
  const vol=Math.round(Number(m.volume));
  if(!(vol>=5&&vol<=100))throw erreur400('Musique de fond : volume entre 5 et 100 %.');
  return {actif:m.actif===true,morceaux:morceaux.map(({ext,...v})=>v),aleatoire:m.aleatoire===true,volume:vol,
    horaire:m.horaire===true,debut:hh.test(m.debut)?m.debut:'08:00',fin:hh.test(m.fin)?m.fin:'17:00'};
}
// Morceaux d'une télé (pour le ménage de Google), cochée ou non.
const musiqueDe=x=>{const m=musiqueLue(x&&x.musique);return m?m.morceaux:[]};
// Dans les heures de musique ? (toujours, sans « horaire ») ; debut = fin (toléré à la lecture) : jamais.
function musiqueEnHeures(m,t){
  if(!m.horaire)return true;
  const p=VeilleTele.paris(t),mn=s=>Number(s.slice(0,2))*60+Number(s.slice(3,5)),d=mn(m.debut),f=mn(m.fin);
  return d===f?false:d<f?p.m>=d&&p.m<f:p.m>=d||p.m<f;
}
// Ce que la page /tele doit savoir (null : pas de musique) ; les morceaux sont téléchargés en arrière-plan par CE
// programme, comme les vidéos (prêts : adresse /video/<id>.mp3).
function musiquePourPage(x){
  const m=musiqueLue(x&&x.musique);
  if(!m||!m.actif||!m.morceaux.length)return null;
  videosVoulues(m.morceaux);
  return {aleatoire:m.aleatoire,volume:m.volume,horaire:m.horaire,debut:m.debut,fin:m.fin,heures:musiqueEnHeures(m,Date.now()),
    morceaux:m.morceaux.map(v=>Object.assign({nom:v.nom,duree:v.duree},videoEtat(v)))};
}
// MP3 vérifié sur le PC avant l'envoi (aucune conversion) : deux en-têtes de trame MPEG Layer III à la suite, après
// l'étiquette ID3 éventuelle (pochette comprise). Durée : trames comptées (en-tête Xing/Info) sinon débit constant.
const MP3_DEBITS={1:[0,32,40,48,56,64,80,96,112,128,160,192,224,256,320],2:[0,8,16,24,32,40,48,56,64,80,96,112,128,144,160]};
const MP3_FREQ={3:[44100,48000,32000],2:[22050,24000,16000],0:[11025,12000,8000]};
function mp3Trame(b,p){
  if(p+4>b.length||b[p]!==0xFF||(b[p+1]&0xE0)!==0xE0)return null;
  const ver=(b[p+1]>>3)&3,couche=(b[p+1]>>1)&3,ib=b[p+2]>>4,ifr=(b[p+2]>>2)&3;
  if(ver===1||couche!==1||ib===0||ib===15||ifr===3)return null;
  const debit=MP3_DEBITS[ver===3?1:2][ib],freq=MP3_FREQ[ver][ifr],mono=(b[p+3]>>6)===3;
  return {ver,debit,freq,mono,lg:Math.floor((ver===3?144:72)*debit*1000/freq)+((b[p+2]>>1)&1),spf:ver===3?1152:576};
}
function mp3Analyse(f){
  const taille=fs.statSync(f).size,fd=fs.openSync(f,'r');
  try{
    const lire=(pos,n)=>{const b=Buffer.alloc(Math.max(0,Math.min(n,taille-pos)));fs.readSync(fd,b,0,b.length,pos);return b};
    let deb=0;const t=lire(0,10);
    if(t.length===10&&t.toString('latin1',0,3)==='ID3')deb=10+((t[6]&127)<<21|(t[7]&127)<<14|(t[8]&127)<<7|(t[9]&127))+((t[5]&16)?10:0);
    const b=lire(deb,65536);
    for(let p=0;p+4<=b.length;p++){
      const a=mp3Trame(b,p);if(!a)continue;
      const s=mp3Trame(b,p+a.lg);
      if(!s||s.ver!==a.ver||s.freq!==a.freq)continue;
      // Trame Xing/Info (MP3 à débit variable) : nombre de trames exact.
      const x=p+4+(a.ver===3?(a.mono?17:32):(a.mono?9:17)),tag=b.toString('latin1',x,x+4);
      let duree=(taille-deb-p)*8/(a.debit*1000);
      if((tag==='Xing'||tag==='Info')&&x+12<=b.length&&(b.readUInt32BE(x+4)&1))duree=b.readUInt32BE(x+8)*a.spf/a.freq;
      return {duree:Math.round(duree),resume:'MP3 '+(tag==='Xing'?'débit variable':a.debit+' kbit/s')+', '+(a.freq/1000).toLocaleString('fr-FR')+' kHz'+(a.mono?', mono':', stéréo')+(duree>0?', '+Math.floor(duree/60)+' min '+String(Math.round(duree%60)).padStart(2,'0')+' s':'')};
    }
    throw erreur400('Ce fichier n’est pas un MP3 lisible (aucune trame MP3 trouvée au début). Enregistrez-le de nouveau en MP3.');
  }finally{fs.closeSync(fd)}
}
async function musiquePreparer(job,f){
  job.etape='verification';job.texte='Vérification du MP3…';
  const a=mp3Analyse(f);
  job.analyse=a.resume;job.verdict='✓ MP3 lisible';
  try{await envoyerDansGoogle(job,f,job.nom,fs.statSync(f).size,a.duree,morceauPropre)}
  catch(e){if(/Nom de vid[ée]o refusé/i.test(e.message))throw new Error(MUSIQUE_SCRIPT);throw e}
}

// Téléchargement par le programme de la télé : UNE vidéo à la fois, un morceau à la fois avec une pause, reprise après
// une coupure (fichier .part), empreinte vérifiée avant de la rendre visible (renommage). Échec : nouvel essai de plus en
// plus espacé (15 s → 4 min). Vidéos voulues = celles des listes lues dans les 10 dernières minutes.
const VID={voulues:new Map(),cours:'',etat:new Map(),timer:0};
const videoFichier=v=>path.join(DOSSIER_VIDEOS,v.id+'.'+v.ext);
const videoPrete=v=>{try{return fs.statSync(videoFichier(v)).size===v.taille}catch(e){return false}};
const sha256=b=>crypto.createHash('sha256').update(b).digest('hex');
function videosVoulues(l){
  const t=Date.now();
  for(const v of l)VID.voulues.set(v.id,{v,vu:t});
  for(const [id,x] of VID.voulues)if(t-x.vu>10*60000)VID.voulues.delete(id);
  setImmediate(videoSuite);
}
// État d'une vidéo pour la page /tele : prête (adresse), ou avancement du téléchargement, ou dernière erreur.
function videoEtat(v){
  if(videoPrete(v))return {id:v.id,pret:true,src:'/video/'+v.id+'.'+v.ext};
  const e=VID.etat.get(v.id)||{};
  return {id:v.id,pret:false,pct:e.total?Math.floor(100*(e.fait||0)/e.total):0,enCours:VID.cours===v.id,erreur:e.erreur||''};
}
async function videoSuite(){
  if(VID.cours)return;
  const t=Date.now(),l=[...VID.voulues.values()].map(x=>x.v).filter(v=>!videoPrete(v));
  const v=l.find(x=>!((VID.etat.get(x.id)||{}).prochain>t));
  if(!v){
    const p=Math.min(...l.map(x=>(VID.etat.get(x.id)||{}).prochain||Infinity));
    if(isFinite(p)){clearTimeout(VID.timer);VID.timer=setTimeout(videoSuite,Math.max(1000,p-t))}
    return;
  }
  VID.cours=v.id;
  const e=VID.etat.get(v.id)||{essais:0};VID.etat.set(v.id,e);
  try{await videoTelecharger(v,e);Object.assign(e,{erreur:'',essais:0,prochain:0})}
  catch(err){e.essais=(e.essais||0)+1;e.erreur=err.message||String(err);e.prochain=Date.now()+15000*2**Math.min(4,e.essais-1);console.error('Vidéo '+v.nom+' : '+e.erreur)}
  finally{VID.cours='';setTimeout(videoSuite,1000)}
}
async function videoTelecharger(v,e){
  fs.mkdirSync(DOSSIER_VIDEOS,{recursive:true});
  const part=videoFichier(v)+'.part',total=Math.ceil(v.taille/VIDEO_MORCEAU);
  let deja=0;try{deja=fs.statSync(part).size}catch(x){}
  let n=Math.min(total,Math.floor(deja/VIDEO_MORCEAU));
  if(deja&&deja!==n*VIDEO_MORCEAU)fs.truncateSync(part,n*VIDEO_MORCEAU); // dernier morceau incomplet : repris
  e.fait=n;e.total=total;
  const i=await videoGoogle(reglages(),{operation:'video-info',id:v.id},30000);
  if(!i||!i.existe)throw new Error('Vidéo absente de Google : envoyez-la de nouveau depuis la console.');
  if(i.taille!==v.taille||i.empreinte!==v.empreinte)throw new Error('La vidéo rangée dans Google n’est pas celle attendue.');
  if(!i.complete)throw new Error('Vidéo pas encore entièrement envoyée par la console.');
  videoPlace(v.taille-n*VIDEO_MORCEAU);
  const fd=fs.openSync(part,'a');
  try{
    for(;n<total;n++){
      const d=await videoGoogle(reglages(),{operation:'video-get',id:v.id,n},120000);
      const b=Buffer.from(String(d&&d.data||''),'base64'),att=n<total-1?VIDEO_MORCEAU:v.taille-(total-1)*VIDEO_MORCEAU;
      if(b.length!==att||sha256(b)!==String(d.empreinte||''))throw new Error('Morceau '+(n+1)+' / '+total+' abîmé pendant le téléchargement : nouvel essai.');
      for(let o=0;o<b.length;)o+=fs.writeSync(fd,b,o,b.length-o);
      e.fait=n+1;
      if(n<total-1)await new Promise(ok=>setTimeout(ok,VIDEO_PAUSE));
    }
  }finally{fs.closeSync(fd)}
  const h=await new Promise((ok,ko)=>{const x=crypto.createHash('sha256');fs.createReadStream(part).on('data',c=>x.update(c)).on('end',()=>ok(x.digest('hex'))).on('error',ko)});
  if(h!==v.empreinte){fs.rmSync(part,{force:true});throw new Error('Vidéo abîmée (empreinte fausse) : elle est retéléchargée.')}
