// Télé imitée (essais du chantier) : {cec:'ok'|'refus'|'ignore'|'absent'|'debranche', sortie:'wlopm'|'aucune'} ;
// la télé (allumée / en veille) est dans <fichier>.tv, chaque commande est notée dans <fichier>.journal.
function veilleImiter(prog,args){
  const E=VEILLE.essai;let cfg={};try{cfg=JSON.parse(fs.readFileSync(E,'utf8'))}catch(e){}
  try{fs.appendFileSync(E+'.journal',prog+' '+args.join(' ')+'\n')}catch(e){}
  let tv='on';try{tv=fs.readFileSync(E+'.tv','utf8').trim()||'on'}catch(e){}
  const poser=x=>{try{fs.writeFileSync(E+'.tv',x)}catch(e){}},a=args.join(' '),non={code:1,absent:false,sortie:'\tTx, Not Acknowledged (2), Max Retries\n'};
  if(prog==='cec-ctl'){
    if(cfg.cec==='absent')return {code:1,absent:true,sortie:''};
    if(args.length===2)return {code:0,absent:false,sortie:'Driver Info:\n\tDriver Name : vc4_hdmi\nPhysical Address : '+(cfg.cec==='debranche'?'f.f.f.f':'1.0.0.0')+'\n'};
    if(/--playback/.test(a))return {code:0,absent:false,sortie:'Logical Address : 4 (Playback Device 1)\n'};
    if(cfg.cec==='refus')return non;
