    if(/--give-device-power-status/.test(a))return tv==='standby'&&cfg.muette?non:{code:0,absent:false,sortie:'Received from TV to Playback Device 1 (0 to 4):\nREPORT_POWER_STATUS (0x90):\n\tpwr-state: '+(tv==='standby'?'standby (0x01)':'on (0x00)')+'\n'};
