const cecRate=r=>r.absent||r.code!==0||/Tx,\s*(Not Acknowledged|Error|Arbitration Lost|Low Drive|Aborted|Timeout)|Not Acknowledged/i.test(r.sortie);
// Port HDMI où la télé est branchée : /dev/cecN dont l'adresse physique est valable (f.f.f.f = rien de branché).
async function veilleCecTrouver(){
  let devs=[];
  if(VEILLE.essai)devs=['/dev/cec0'];
  else try{devs=fs.readdirSync('/dev').filter(f=>/^cec\d+$/.test(f)).sort().map(f=>'/dev/'+f)}catch(e){}
  if(!devs.length)return {ok:false,raison:'pas de /dev/cec (HDMI-CEC absent de ce Raspberry)'};
  for(const d of devs){
    const r=await veilleCmd('cec-ctl',['-d',d]);
    if(r.absent)return {ok:false,raison:'programme cec-ctl absent (paquet v4l-utils)'};
    if(r.code&&/denied|permission/i.test(r.sortie))return {ok:false,raison:'accès refusé à '+d+' (le compte doit être dans le groupe video)'};
    const m=/Physical Address\s*:\s*([0-9a-f]\.[0-9a-f]\.[0-9a-f]\.[0-9a-f])/i.exec(r.sortie);
    if(m&&m[1].toLowerCase()!=='f.f.f.f')return {ok:true,dev:d,pa:m[1]};
  }
  return {ok:false,raison:'aucune télé vue par HDMI-CEC (télé débranchée, ou HDMI-CEC coupé dans les réglages de la télé)'};
