// État d'alimentation donné par la télé : « on », « standby », « to-on », « to-standby », ou '' (pas de réponse).
async function veillePuissance(c){
  const r=await veilleCmd('cec-ctl',['-d',c.dev,'--to','0','--give-device-power-status']);
  const m=/pwr-state:\s*([a-z-]+)/i.exec(r.sortie);
  return m?m[1].toLowerCase():'';
}
// Session graphique du compte du service (le même que celui du bureau) : Wayland (labwc, wayfire) ou X11.
function veilleSession(){
  if(VEILLE.essai)return {env:{},wayland:true,x11:false};
  const run='/run/user/'+(process.getuid?process.getuid():0);let w='';
  try{w=fs.readdirSync(run).filter(f=>/^wayland-\d+$/.test(f)).sort()[0]||''}catch(e){}
  if(w)return {env:{XDG_RUNTIME_DIR:run,WAYLAND_DISPLAY:w},wayland:true,x11:false};
  if(fs.existsSync('/tmp/.X11-unix/X0'))return {env:{XDG_RUNTIME_DIR:run,DISPLAY:':0',XAUTHORITY:path.join(os.homedir(),'.Xauthority')},wayland:false,x11:true};
