// Sorties allumées d'après « wlr-randr » (nom en début de ligne, puis « Enabled: yes »).
function sortiesWlr(t){
  const l=[];let cur='';
  for(const x of String(t).split('\n')){const m=/^(\S+)/.exec(x);if(m){cur=m[1];continue}if(cur&&/^\s+Enabled:\s*yes/i.test(x)&&!l.includes(cur))l.push(cur)}
