  if(allumer){
    const o=VEILLE.sortie;VEILLE.sortie=null;if(!o)return true;
    if(o.outil==='wlopm')return ok(await veilleCmd('wlopm',['--on','*'],s.env));
    if(o.outil==='xset')return ok(await veilleCmd('xset',['dpms','force','on','-dpms'],s.env));
