    // Ordre refusé par une télé DÉJÀ en veille (2026-11-26 : redémarrage de nuit du Pi pendant la veille) : si elle dit
    // « standby », elle est bien éteinte par HDMI-CEC (avant : repli à tort en « signal coupé »).
    if(cecRate(r)&&await veillePuissance(c)==='standby'){VEILLE.mode='cec';veilleNote('télé déjà en veille (HDMI-CEC, '+c.dev+').');veilleAction('c');return}
