    }else veilleNote('la télé ne répond pas à HDMI-CEC ('+(String(r.sortie).trim().split('\n').pop()||'code '+r.code).slice(0,120)+').');
  }else veilleNote('HDMI-CEC indisponible : '+c.raison+'.');
  if(await veilleSortieHdmi(false)){VEILLE.mode='hdmi';veilleNote('signal HDMI coupé ('+VEILLE.sortie.outil+') : la télé affiche « pas de signal » ou se met en veille d’elle-même.');veilleAction('h');return}
