    const p=await veillePuissance(VEILLE.cec);
    if(p==='on'){await veilleCmd('cec-ctl',['-d',VEILLE.cec.dev,'--to','0','--standby']);veilleNote('télé rallumée pendant la veille : éteinte de nouveau par HDMI-CEC.')}
