// Un réveil HDMI-CEC : « image-view-on », repli en « appareil non enregistré » (15), puis « active-source ». Vrai si
// l'ordre est parti (la télé peut l'avoir ignoré : c'est la demande d'état qui le dit).
async function veilleReveiller(c){
  await veilleCmd('cec-ctl',['-d',c.dev,'--playback','-o','Lynk']);
  let r=await veilleCmd('cec-ctl',['-d',c.dev,'--to','0','--image-view-on']);
  // Certaines télés en veille coupent l'adresse HDMI : réveil envoyé en « appareil non enregistré » (15).
  if(cecRate(r))r=await veilleCmd('cec-ctl',['-d',c.dev,'--from','15','--to','0','--image-view-on']);
