// Contrôle après la veille (essai 1 = le réveil de veilleSortir). S'arrête dès que la veille reprend (VEILLE.en
// n'est plus false) ou qu'un autre contrôle commence (gen).
async function veilleRallumer(c){
  const R=VEILLE.rallumage={gen:(VEILLE.rallumage?VEILLE.rallumage.gen:0)+1,debut:Date.now(),essai:1,fini:false};
  const actif=()=>VEILLE.rallumage===R&&VEILLE.en===false;
  try{
    while(actif()&&Date.now()-R.debut<VEILLE.rallumerDuree){
      await veilleAttendre(Math.min(VEILLE.rallumerPas,Math.max(0,VEILLE.rallumerDuree-(Date.now()-R.debut))));
      if(!actif())return;
      if(!c||!c.ok){const t=await veilleCecTrouver();if(t.ok)c=t}
      if(!actif())return;
      if(await veilleAllumee(c)){
        VEILLE.eteinte=0;R.fini=true;
        // Sans HDMI-CEC (veille en écran noir, ou CEC absent) : rien n'a été envoyé, la télé est simplement vue allumée.
        if(c&&c.ok){veilleNote('télé rallumée par HDMI-CEC (essai '+R.essai+').');veilleAction('r'+R.essai)}else veilleNote('télé allumée après la veille (sortie son HDMI vue).');
        return;
      }
      if(!actif()||Date.now()-R.debut>=VEILLE.rallumerDuree)break;
      if(c&&c.ok){R.essai++;await veilleReveiller(c)}
    }
    if(!actif())return;
    // Dernier regard après le dernier essai.
    if(await veilleAllumee(c)){VEILLE.eteinte=0;R.fini=true;veilleNote('télé rallumée par HDMI-CEC (essai '+R.essai+').');veilleAction('r'+R.essai);return}
    VEILLE.eteinte=Date.now();R.fini=true;
    veilleNote('télé restée éteinte après la veille ('+R.essai+' essai'+(R.essai>1?'s':'')+' en '+Math.round(VEILLE.rallumerDuree/60000)+' min) : à rallumer à la télécommande.');
    veilleAction('e');
    // On regarde seulement (rien n'est envoyé) : dès qu'elle est vue allumée, l'alerte de la console s'en va.
    while(VEILLE.rallumage===R&&VEILLE.en===false&&VEILLE.eteinte){
      await veilleAttendre(VEILLE.observerPas);
      if(VEILLE.rallumage!==R||VEILLE.en!==false)return;
      if(!c||!c.ok){const t=await veilleCecTrouver();if(t.ok)c=t}
      if(await veilleAllumee(c)){VEILLE.eteinte=0;veilleNote('télé vue allumée après la veille (rallumée à la main ?).');veilleAction('m');return}
    }
  }catch(e){veilleNote('contrôle après la veille : erreur '+(e&&e.message||e))}
}
async function veilleTic(){
  if(VEILLE.tache)return VEILLE.tache;
  VEILLE.tache=(async()=>{
    if(!TELES.teles)telesDisque();
    const id=TELES.id||VEILLE.idFichier;
    if(!id)return; // la page /tele de ce Pi n'a pas encore dit quelle télé il est
    VEILLE.id=id;
    // Le réglage est relu par la page (toutes les 6 s) ; sans page (Chromium fermé, démarrage), relu d'ici.
    if(Date.now()-TELES.t>60000)await telesLecture(id).catch(()=>{});
    const x=TELES.teles&&TELES.teles[id];
    VEILLE.regle=VeilleTele.lue(x&&x.veille);VEILLE.etat=VeilleTele.etat(VEILLE.regle,Date.now());
    // Four à sortir pendant la veille (2026-11-12, développeur B2) : la page /tele le signale (POST /api/tele-reveil) ;
    // la veille est suspendue tant qu'elle le redit (2 min après le dernier signal), la télé est rallumée.
    const reveil=VEILLE.reveil>Date.now(),en=VEILLE.etat.en&&!reveil;
    if(VEILLE.etat.en&&reveil&&VEILLE.en===true)veilleNote('four à sortir : veille suspendue, télé rallumée.');
    if(en&&VEILLE.en!==true){
      VEILLE.en=true;VEILLE.mode='';VEILLE.eteinte=0;const c=VEILLE.etat.change; // nouvelle veille : « restée éteinte » oublié
      veilleNote('début de la veille'+(c?' (jusqu’à '+c.jour+' '+c.heure+')':'')+' : écran noir, télé éteinte dans '+Math.round(VEILLE.delai/1000)+' s.');
      await veilleAttendre(VEILLE.delai);
      await veilleEntrer();VEILLE.dernierMode=VEILLE.mode;VEILLE.dernier=Date.now();
    }else if(!en&&VEILLE.en===true){VEILLE.en=false;await veilleSortir()}
    else if(!en&&VEILLE.en===null)VEILLE.en=false; // démarrage hors veille : rien n'est envoyé à la télé
    else if(en&&Date.now()-VEILLE.dernier>=VEILLE.relance){VEILLE.dernier=Date.now();await veilleRelance()}
  })().catch(e=>veilleNote('erreur : '+(e&&e.message||e))).finally(()=>{VEILLE.tache=null});
  return VEILLE.tache;
}
function veilleDemarrer(){
  const essai=process.env.LYNK_VEILLE_ESSAI;
  if(!process.argv.includes('--ecrans-seuls')||(process.platform!=='linux'&&!essai))return;
  VEILLE.moteur=true;
  if(essai){
    VEILLE.essai=path.resolve(essai);
    let c={};try{c=JSON.parse(fs.readFileSync(VEILLE.essai,'utf8'))}catch(e){}
    for(const k of ['tic','delai','relance','attente','rallumerPas','rallumerDuree','observerPas'])if(c[k]!=null&&Number(c[k])>=0)VEILLE[k]=Number(c[k]);
  }
  setTimeout(veilleTic,VEILLE.essai?200:3000); // tout de suite au démarrage (redémarrage pendant la veille)
  setInterval(veilleTic,VEILLE.tic);
}
// POST /api/tele-reveil (2026-11-12, développeur B2) : la page /tele de CE Pi dit qu'un four est à sortir. Seul effet :
// la veille de cette télé est suspendue 2 minutes (renouvelé à chaque signal, toutes les 6 s tant que l'alarme dure).
// Rien d'autre n'est changé ; sans moteur de veille (PC du bureau) : sans effet.
function veilleReveil(){
  if(!VEILLE.moteur)return {ok:true,moteur:false};
  const avant=VEILLE.reveil>Date.now();VEILLE.reveil=Date.now()+120000;
  if(!avant)veilleTic();
  return {ok:true,moteur:true};
}
