// Lecture partagée par les pages /tele de ce programme : une lecture de Google toutes les 15 s au plus. Google ne répond
// pas : le dernier réglage lu est gardé (mémoire, puis fichier de ce Pi : il survit à un redémarrage sans réseau).
const TELES_FICHIER=path.join(DOSSIER_REGLAGES,'teles-derniere-lecture.json');
const TELES={t:0,teles:null,lu:0,erreur:'',id:'',enCours:null};
// Mise en veille (2026-11-12) : le fichier garde aussi l'identifiant de CETTE télé (id), pour que la veille reprenne
// dès le démarrage du Pi, avant même que Chromium n'ouvre la page /tele.
function telesDisque(){try{const o=JSON.parse(fs.readFileSync(TELES_FICHIER,'utf8'));if(o&&typeof o.id==='string'&&TELE_ID.test(o.id))VEILLE.idFichier=TELES.idEcrit=o.id;
  if(o&&o.teles&&typeof o.teles==='object'){TELES.teles=o.teles;TELES.lu=Number(o.lu)||0}}catch(e){}}
async function telesLecture(id,ip){
  if(id){TELES.id=id;if(ip!==undefined)TELES.ip=ip}
  // Allègement de Google (2026-11-12) : réglage des télés relu toutes les 60 s (15 s avant) ; 30 s après une erreur.
  // Un changement fait depuis la console arrive donc en moins d'une minute. Sur un programme qui sert aussi la console
  // (futur serveur de l'entreprise), telesEcrire remet TELES.t à 0 : le changement est pris tout de suite.
  if(TELES.teles&&Date.now()-TELES.t<(TELES.erreur?30000:60000))return TELES;
  if(!TELES.enCours)TELES.enCours=(async()=>{
    const corps={app:'pack',operation:'pull'};
    if(TELES.id)Object.assign(corps,{appareil:teleAppareil(TELES.id),zone:'Télé · '+TELES.id,version:'',etat:teleEtatEnvoye(TELES.teles&&TELES.teles[TELES.id],TELES.ip)});
    // Santé du Raspberry (2026-11-26) : champ à part, seulement quand une mesure existe (Pi). L'ancien script l'ignore.
    if(TELES.id&&SANTE.texte())corps.sante=SANTE.texte();
    // « Déjà à jour » (lot C, 2026-11-13) : la version de la dernière lecture est envoyée ; le nouveau script répond alors
    // {rev, maj, aJour:true} SANS la configuration si rien n'a changé (80 caractères au lieu de 6 000 et plus). L'ancien
    // script ignore rev et renvoie toujours site : rien ne change. Jamais « site absent » pris pour « pas de télé ».
    if(TELES.teles&&TELES.rev!=null)corps.rev=TELES.rev;
    try{
      const d=await google(reglages(),corps,20000);
      if(d&&d.aJour===true&&!d.site&&TELES.teles){Object.assign(TELES,{lu:Date.now(),erreur:''});if(d.rev!=null)TELES.rev=d.rev}
      else{
      if(!d||!d.site)throw new Error('Google n’a pas encore de configuration du pack.');
      TELES.rev=d.rev!=null?d.rev:d.maj!=null?d.maj:d.site.maj!=null?d.site.maj:null;
      const teles=d.site.teles&&typeof d.site.teles==='object'?d.site.teles:{},avant=JSON.stringify(TELES.teles);
      Object.assign(TELES,{teles,lu:Date.now(),erreur:''});
      if(JSON.stringify(teles)!==avant||(TELES.id&&TELES.id!==TELES.idEcrit))try{fs.mkdirSync(DOSSIER_REGLAGES,{recursive:true});
        fs.writeFileSync(TELES_FICHIER,JSON.stringify(Object.assign({lu:TELES.lu,teles},TELES.id?{id:TELES.id}:{})));if(TELES.id)TELES.idEcrit=TELES.id}catch(e){}
      }
    }catch(e){TELES.erreur=e.message;if(!TELES.teles)telesDisque()}
    TELES.t=Date.now();
  })().finally(()=>{TELES.enCours=null});
  await TELES.enCours;
  return TELES;
}
// Page web : refuse-t-elle d'être affichée dans un cadre (X-Frame-Options, CSP frame-ancestors) ? Vérifié par CE
// programme (gardé 10 min ; 1 min si injoignable) pour que la télé dise clairement pourquoi au lieu d'un cadre vide.
const CADRABLE=new Map();
async function pageCadrable(adresse,origine){
  const g=CADRABLE.get(adresse);if(g&&Date.now()-g.t<(g.r.raison==='injoignable'?60000:600000))return g.r;
  let r;
  try{
    const rep=await fetch(adresse,{redirect:'follow',signal:AbortSignal.timeout(8000),headers:{'User-Agent':'Mozilla/5.0 (X11; Linux) Lynk-tele'}});
    const meme=(()=>{try{return new URL(rep.url||adresse).origin===origine}catch(e){return false}})();
    const xfo=String(rep.headers.get('x-frame-options')||'').toLowerCase(),fa=/frame-ancestors([^;]*)/.exec(String(rep.headers.get('content-security-policy')||'').toLowerCase());
    try{if(rep.body)await rep.body.cancel()}catch(e){}
    const refus=/deny/.test(xfo)||(/sameorigin/.test(xfo)&&!meme)||(fa&&!/\*/.test(fa[1])&&!(meme&&/'self'/.test(fa[1]))&&!fa[1].includes(origine));
    r=refus?{ok:false,raison:'refus'}:{ok:true,code:rep.status};
  }catch(e){r={ok:false,raison:'injoignable'}}
  CADRABLE.set(adresse,{t:Date.now(),r});if(CADRABLE.size>50)CADRABLE.delete(CADRABLE.keys().next().value);
  return r;
}
// GET /api/tele?id= : ce que CETTE télé doit afficher (lecture seule, sans connexion : aucun secret).
// apercu : page ouverte depuis la console (« Voir comme la télé ») : ce PC ne se signale pas à la place de la télé.
async function teleLire(id,origine,apercu,ip){
  id=String(id||'').trim().toLowerCase();
  if(!TELE_ID.test(id))throw erreur400('Identifiant de télé invalide (lettres, chiffres et tirets).');
  const s=await telesLecture(apercu?'':id,ip);
  if(!s.teles)throw Object.assign(new Error('Le réglage des télés n’a pas encore pu être lu (Google ne répond pas).'),{status:503});
  const x=s.teles[id]&&typeof s.teles[id]==='object'?s.teles[id]:null;
  // Contenu revérifié (développeur B5) : une cellule de la Sheet abîmée ou d'un ancien format ne bloque plus la page sur
  // « Lecture… » : la télé montre l'écran d'attente et le dit.
  let contenu={type:'aucun'},invalide='';
  if(x&&x.contenu)try{contenu=teleContenuPropre(x.contenu,true)}catch(e){invalide=e.message||'Réglage illisible.'}
  const rep={id,connue:!!x,nom:x?String(x.nom||id):'',contenu,maj:x?Number(x.maj)||0:0,lu:s.lu,erreur:s.erreur?'Pas de connexion avec Google.':'',maintenant:Date.now()};
  if(invalide)rep.invalide='Le réglage de cette télé est illisible ('+invalide+') : réglez-la de nouveau dans la console.';
  // Mise en veille (2026-11-12) : en veille, la page passe au noir et arrête vidéo et page web (calcul à l'heure de Paris).
  // Les vidéos continuent de se télécharger pendant la veille (la nuit, le réseau est libre).
  const veille=veillePourPage(x);if(veille)rep.veille=veille;
  const web=rep.contenu.type==='web'?rep.contenu:rep.contenu.type==='message'&&rep.contenu.ensuite&&rep.contenu.ensuite.type==='web'?rep.contenu.ensuite:null;
  if(web&&web.adresse)rep.web=await pageCadrable(web.adresse,origine);
  // Vidéos : téléchargées en arrière-plan par CE programme ; la page reçoit l'état de chacune (prête ou avancement).
  const vl=videosDe(rep.contenu);
  if(vl.length){videosVoulues(vl);rep.videos=vl.map(videoEtat)}
  // Musique de fond (2026-11-16) : morceaux téléchargés comme les vidéos (aussi pendant la veille), état de chacun.
  const mu=musiquePourPage(x);if(mu)rep.musique=mu;
  return rep;
}
// GET /api/ecran-tournant?tele=<id> : le tour de cette télé (son réglage, ou un seul écran choisi). Sans réglage de tour
// pour cette télé : celui gardé sur ce programme (réglage local d'avant, rien ne casse).
async function teleTournant(id){
  id=String(id||'').trim().toLowerCase();
