  let c=x&&x.contenu;if(c&&c.type==='message')c=c.ensuite;
  if(!c||c.type!=='ecran'||c.ecran==='tournant')return x&&x.tournant&&Array.isArray(x.tournant.ecrans)?Object.assign(tournantDepuis(x.tournant),{maj:Number(x.maj)||0}):tournantLire();
  // Un seul écran : affiché seul (sans barre de suite), ses pages défilent ; ni priorité ni nuit.
