  return {ecrans:cat.map(k=>Object.assign({},k,{on:k.id===cle})),priorite:false,nuit:{on:false,debut:'06:00',fin:'21:00'},theme:c.theme==='clair'?'clair':'sombre',maj:Number(x.maj)||0,durees:TOURNANT_DUREES,messages:[],messagesMax:TOURNANT_MSG_MAX};
