// GET /api/teles (console) : toutes les télés, leur dernière visite et le réglage qu'elles ont reçu ; les télés qui se
// sont présentées sans réglage arrivent en « nouvelle télé ».
// --- Droits des télés par secteur (2026-11-12, console B1 : un manager changeait ou retirait n'importe quelle télé et
// pouvait signer au nom d'un autre). Les écritures des télés partent avec le code de CE PC : aucun contrôle du script
// Google ne les rattrape, tout est donc vérifié ici, avec la session.
// Secteurs d'une télé = ceux de ce qu'elle montre : écran Maintenance / Liaison → son secteur ; Fours et Lancements →
// frittage (ce sont des applis du frittage) ; écran tournant → secteurs des écrans cochés dans son tour. Image, page,
// vidéo ou rien : les secteurs notés à l'enregistrement (ceux du manager qui l'a réglée) ; sinon aucun = télé commune.
// Manager : voit les télés de ses secteurs et les communes ; change ou retire seulement celles dont TOUS les secteurs
// sont les siens (une télé commune : administrateur seulement) ; ce qu'il y met doit rester dans ses secteurs.
function secteursEcranTele(id){const m=/^(maintenance|liaison):([a-z0-9-]{1,30})$/.exec(String(id||''));return m?[m[2]]:id==='fours'||id==='lancements'?['frittage']:[]}
function teleSecteurs(contenu,tournant,notes){
  const s=new Set(),c0=contenu&&typeof contenu==='object'?contenu:{},c=c0.type==='message'&&c0.ensuite?c0.ensuite:c0;
  if(c.type==='ecran'){
    if(c.ecran==='tournant'){for(const e of (tournant&&Array.isArray(tournant.ecrans)?tournant.ecrans:[]))if(e&&e.on)secteursEcranTele(e.id).forEach(x=>s.add(x))}
    else secteursEcranTele(c.ecran==='maintenance'||c.ecran==='liaison'?c.ecran+':'+c.secteur:c.ecran).forEach(x=>s.add(x));
  }
  if(!s.size)for(const x of (Array.isArray(notes)?notes:[]))if(/^[a-z0-9-]{1,30}$/.test(String(x)))s.add(String(x));
  return [...s];
}
const toutSecteur=moi=>!moi||moi.admin||(moi.secteurs||[]).includes('*');
const teleModifiable=(moi,l)=>toutSecteur(moi)||(l.length>0&&l.every(x=>moi.secteurs.includes(x)));
const teleVisible=(moi,l)=>toutSecteur(moi)||!l.length||l.some(x=>moi.secteurs.includes(x));
const refusTele=m=>Object.assign(new Error(m),{status:403});
async function telesListe(r,ctx){
  const moi=ctx&&ctx.moi;
  const d=await google(r,{app:'pack',operation:'pull'}),s=d.site;
  if(!s)throw new Error('Google n’a pas encore de configuration du pack : ouvrez une fois l’accueil d’une tablette reliée à Google.');
  let appareils=[],avisVu='';
  try{appareils=await tablettes(r)}catch(e){avisVu='Dernière visite des télés illisible : '+e.message}
  const vus={};
  for(const a of appareils){const m=/^Télé · ([a-z0-9][a-z0-9-]{0,39})$/.exec(String(a.zone||'').trim());if(m&&a.id===teleAppareil(m[1]))vus[m[1]]={appareil:a.id,vu:a.vu,etat:a.etat,sante:a.sante}}
  // Santé des Raspberry (2026-11-26) : un script Google plus ancien ne rend pas « sante » (colonne absente) ; la console
  // le dit (« script Google à mettre en ligne ») au lieu d'une santé vide. null = aucun appareil lu.
  const santeScript=appareils.length?appareils.some(a=>a&&typeof a==='object'&&'sante' in a):null;
  const teles=s.teles&&typeof s.teles==='object'?s.teles:{};
  const secsDe=x=>teleSecteurs(x.contenu,x.tournant,x.secteurs);
  const l=Object.keys(teles).filter(id=>TELE_ID.test(id)&&teles[id]&&typeof teles[id]==='object'&&teleVisible(moi,secsDe(teles[id]))).map(id=>{const x=teles[id],v=vus[id]||{},secs=secsDe(x);
    return {id,nom:String(x.nom||id),contenu:x.contenu||{type:'aucun'},secteurs:secs,modifiable:teleModifiable(moi,secs),tournant:tournantDepuis(x.tournant||null),tournantPropre:!!(x.tournant&&Array.isArray(x.tournant.ecrans)),maj:Number(x.maj)||0,par:String(x.par||''),
      vu:v.vu||'',recu:teleRecu(v.etat,x),ip:teleIp(v.etat),demarre:teleDemarre(v.etat),programme:teleProgramme(v.etat),appareil:v.appareil||'',
      // Mise en veille (2026-11-12) : réglage, et ce que la télé en dit (« veilleEtat », null si son programme est plus ancien).
      veille:VeilleTele.lue(x.veille),veilleEtat:teleVeille(v.etat),veilleCalcul:VeilleTele.etat(x.veille,Date.now()),
      // Musique de fond (2026-11-16) : réglage relu (null si jamais réglée).
      musique:musiqueLue(x.musique),musiqueEtat:teleMusique(v.etat),
      // Santé du Raspberry (2026-11-26) : chaîne brute envoyée par la télé (lue par Surveillance.sante dans la console).
      sante:typeof v.sante==='string'?v.sante.slice(0,400):''}})
    .concat(Object.keys(vus).filter(id=>!teles[id]).map(id=>({id,nom:'',nouvelle:true,secteurs:[],modifiable:true,contenu:{type:'aucun'},tournant:tournantDepuis(null),tournantPropre:false,maj:0,par:'',vu:vus[id].vu,recu:false,ip:teleIp(vus[id].etat),programme:teleProgramme(vus[id].etat),appareil:vus[id].appareil,sante:typeof vus[id].sante==='string'?vus[id].sante.slice(0,400):''})));
  l.sort((a,b)=>(b.nouvelle?1:0)-(a.nouvelle?1:0)||String(a.nom||a.id).localeCompare(String(b.nom||b.id),'fr'));
  return {teles:l,catalogue:tournantCatalogue(),durees:TOURNANT_DUREES,dureesImages:TELE_DUREES_IMG,imagesMax:TELE_IMAGES_MAX,recharger:TELE_RECHARGER,
    secteurs:secteursTele().map(id=>({id,nom:nomSecteur(id)})),avisVu,maintenant:Date.now(),santeScript};
