const TELE_PDF_PAGES=20;
function telePdf(b){
  const m=/^data:application\/pdf;base64,([A-Za-z0-9+/=]+)$/.exec(b&&b.data||'');
  if(!m)throw erreur400('Ce fichier n’est pas un PDF.');
