  if(process.platform!=='win32')throw erreur400('Les PDF se convertissent sur le PC du bureau (Windows).');
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'lynk-pdf-')),f=path.join(dir,'document.pdf');
