    {env:Object.assign({},process.env,{PACK_PDF:f,PACK_SORTIE:dir,PACK_PAGES:String(TELE_PDF_PAGES)}),maxBuffer:1e6,timeout:120000,windowsHide:true},(err,sortie)=>{
