// PowerPoint → une image PNG par diapo (2026-11-10, demande de l'utilisateur : « faire tourner un PowerPoint »), par le
// PowerPoint installé sur le PC du bureau (COM PowerPoint.Application) : rien à installer. Ouverture en lecture seule,
// SANS fenêtre ; diapos masquées sautées ; 1920 px de large (hauteur selon le format de la présentation) ; 30 diapos au
// plus. Animations, vidéos et sons ne sont pas gardés (une image fixe par diapo).
// Prudence : un PowerPoint déjà ouvert par l'utilisateur n'est jamais fermé (seule NOTRE présentation est fermée ; Quit
// seulement si c'est nous qui l'avons lancé et qu'il n'a rien d'autre d'ouvert) ; mot de passe factice « ::…:: » dans le
// nom : une présentation protégée échoue au lieu d'ouvrir une fenêtre de mot de passe qui bloquerait tout ; alertes
// coupées le temps de la conversion (réglage remis ensuite).
// Sortie : « ABSENT » (PowerPoint introuvable), « ILLISIBLE » (abîmée, protégée), sinon le nombre de diapos montrables.
const PS_PPTX=`$ErrorActionPreference='Stop'
# PowerPoint ouvert par l'utilisateur = un POWERPNT lancé sans « -Embedding » (celui lancé par un programme, comme ce
# script, porte « /automation -Embedding » et peut traîner quelques secondes après sa fermeture, sans fenêtre).
# WMI indisponible (cas de ce PC, essai du 2026-11-10) : celui de l'utilisateur est celui qui a une fenêtre.
$deja=$false
foreach($p in @(Get-Process POWERPNT -ErrorAction SilentlyContinue)){
  $ligne=$null;try{$ligne=(Get-CimInstance Win32_Process -Filter ('ProcessId='+$p.Id) -ErrorAction Stop).CommandLine}catch{}
  if($ligne){if($ligne -notmatch '-Embedding'){$deja=$true}}
  elseif($p.MainWindowHandle -ne 0){$deja=$true}
