if(-not $deja){$ids=@(Get-Process POWERPNT -ErrorAction SilentlyContinue|ForEach-Object{$_.Id});if($ids.Count){[IO.File]::WriteAllText((Join-Path $env:PACK_SORTIE 'pid.txt'),($ids -join ' '))}}
