$pres=$null;$code=0
try{
  try{$pres=$app.Presentations.Open($env:PACK_PPT+'::lynk-sans-mot-de-passe::',-1,-1,0)}catch{[Console]::Out.Write('ILLISIBLE');$code=4}
  if($pres){
    # Attention : PowerShell ne distingue pas majuscules et minuscules dans les noms de variables.
    $larg=[double]$pres.PageSetup.SlideWidth;$haut=[double]$pres.PageSetup.SlideHeight
