  if($pres){try{$pres.Close()}catch{};try{[void][Runtime.InteropServices.Marshal]::ReleaseComObject($pres)}catch{}}
  if($alertes -ne $null){try{$app.DisplayAlerts=$alertes}catch{}}
  if(-not $deja){try{if($app.Presentations.Count -eq 0){$app.Quit()}}catch{}}
  try{[void][Runtime.InteropServices.Marshal]::ReleaseComObject($app)}catch{}
