const feuillesDe=s=>{const o={};for(const m of String(s||'').matchAll(/\b(\w*FEUILLES\w*)\s*=\s*(\{[^{}]*\})/g))o[m[1]]=m[2].replace(/\s+/g,'');return o};
function fichierPret(m){try{const st=fs.statSync(m.SOURCE);return {taille:st.size,date:st.mtimeMs}}catch(e){return null}}
async function sgEtat(){
  const {m,dossier}=await moduleSG();
  const e={projet:dossier,fichier:fichierPret(m),autorisation:m.autorisation(),deploiement:null,identique:null,erreur:'',ongletsChanges:[],
    sauvegardes:m.sauvegardes().slice(0,40),operation:SG.op,controles:SG.controles,occupe:sgOccupe()};
  if(e.autorisation&&!sgOccupe()){
    // Lecture gardée 30 s (la page se redessine souvent) ; vidée après chaque opération.
    try{let x;if(SG.cache&&Date.now()-SG.cache.t<30000)x=SG.cache.x;else{x=await m.etat();SG.cache={t:Date.now(),x}}e.deploiement=x.deploiement;e.identique=x.identique;
      if(e.fichier&&x.deploye){const a=feuillesDe(x.deploye),b=feuillesDe(fs.readFileSync(m.SOURCE,'utf8'));e.ongletsChanges=[...new Set(Object.keys(a).concat(Object.keys(b)))].filter(k=>a[k]!==b[k])}}
    catch(x){e.erreur=x.message}
