}
const lancer=(prog,args,o)=>new Promise(ok=>execFile(prog,args,Object.assign({windowsHide:true,maxBuffer:20e6,timeout:180000},o),(err,out,errs)=>ok({ok:!err,code:err?err.code:0,sortie:(err?String(out||'')+String(errs||''):String(out||'')).slice(-4000)})));
// Contrôles avant envoi : fichier prêt = régénéré depuis les sources ? tests automatiques (tests/google.ts au minimum).
async function sgControles(){
  sgVerrou();SG.op={type:'controles',debut:Date.now(),etapes:[],fini:false};
  const note=(e,t)=>SG.op.etapes.push({e,t,at:Date.now()});
  try{
    const {m,dossier}=await moduleSG(),src=path.join(dossier,'Atelier','Atelier-tablettes','Sources-application'),res={at:Date.now(),reconstruit:null,tests:[]};
    if(!fichierPret(m))res.reconstruit={ok:false,texte:'Fichier prêt (Script-Google.txt) absent.'};
    else if(!fs.existsSync(path.join(src,'google','build.mjs'))||!fs.existsSync(path.join(src,'node_modules','esbuild')))res.reconstruit={ok:null,texte:'Sources ou outils absents sur ce PC : contrôle impossible ici (faites-le sur le PC du projet).'};
    else{
      note('reconstruit','Script reconstruit depuis les sources…');
      const tmp=path.join(os.tmpdir(),'pack-script-'+process.pid+'-'+Date.now()+'.txt');
      const r=await lancer(process.execPath,['google/build.mjs',tmp],{cwd:src});
      let pareil=false;try{pareil=r.ok&&m.norm(fs.readFileSync(tmp,'utf8'))===m.norm(fs.readFileSync(m.SOURCE,'utf8'))}catch(e){}
      try{fs.rmSync(tmp,{force:true})}catch(e){}
      res.reconstruit=!r.ok?{ok:false,texte:'Reconstruction impossible : '+r.sortie.split('\n').filter(Boolean).slice(-2).join(' ')}:{ok:pareil,texte:pareil?'Le fichier prêt est bien celui régénéré depuis les sources.':'Le fichier prêt est DIFFÉRENT de celui régénéré depuis les sources : régénérez-le avant de l’envoyer.'};
      for(const t of ['google']){
        note('tests','Tests automatiques : '+t+'…');
        const out=path.join(os.tmpdir(),'pack-test-'+t+'-'+process.pid+'-'+Date.now()+'.mjs');
        const b=await lancer(process.execPath,[path.join(src,'node_modules','esbuild','bin','esbuild'),'tests/'+t+'.ts','--bundle','--platform=node','--format=esm','--alias:cloudflare:workers=./tests/env.ts','--alias:@=.','--outfile='+out,'--log-level=error'],{cwd:src,env:Object.assign({},process.env,{NODE_PATH:path.join(src,'node_modules')})});
        const x=b.ok?await lancer(process.execPath,[out],{cwd:src}):b;
        try{fs.rmSync(out,{force:true})}catch(e){}
        res.tests.push({nom:'tests/'+t+'.ts',ok:x.ok,texte:x.sortie.split('\n').filter(Boolean).slice(-2).join(' ').slice(0,300)});
      }
    }
    SG.controles=res;note('fin','Contrôles terminés.');
  }catch(e){SG.op.erreur=e.message;throw e}
  finally{SG.op.fini=true}
  return SG.controles;
}
// Mise en ligne (ou retour à une sauvegarde) : en arrière-plan ; la page suit SG.op (GET /api/script-google).
function sgPublier(note,dossier){
  sgVerrou();
  const op=SG.op={type:dossier?'revenir':'publier',debut:Date.now(),etapes:[],fini:false};
  const j=(e,t)=>op.etapes.push({e,t:String(t).slice(0,300),at:Date.now()});
  (async()=>{
    try{
      const {m}=await moduleSG();
      if(!m.autorisation())throw new Error('Pas d’autorisation Google sur ce PC : lancez « clasp login ».');
      const r=await m.publier(String(note||'').slice(0,90),dossier||undefined,j);
      j('verification','Vérification : relecture de la version déployée…');
      const x=await m.etat();
      const bon=x.deploiement&&String(x.deploiement.version)===String(r.version)&&m.norm(x.deploye)===m.norm(r.attendu);
      if(!bon)throw new Error('Vérification : la version déployée ne correspond pas à ce qui a été envoyé (version '+(x.deploiement?x.deploiement.version:'?')+').');
      j('verifie','Vérifié : la version '+r.version+' est en ligne'+(dossier?' (retour à '+dossier+').':' et identique au fichier prêt.'));
      op.resultat={version:r.version,description:r.description,sauvegarde:r.sauvegarde};
    }catch(e){op.erreur=e.message;j('erreur','Échec : '+e.message)}
    finally{op.fini=true;SG.cache=null}
  })();
  return {ok:true};
}
async function sessionConsole(jeton){
  if(!/^[0-9a-f]{64}$/.test(jeton))return null;
  const k=crypto.createHash('sha256').update(jeton).digest('hex'),x=SESSIONS_PC.get(k),now=Date.now();
  if(x&&now-x.t<60000)return x.moi;
  const g=reglages().google||{};
  if(!g.url)return undefined;
  let j=null;
  try{const rep=await fetch(g.url,{method:'POST',body:JSON.stringify({console:{op:'moi',jeton}}),redirect:'follow',signal:AbortSignal.timeout(30000)});j=await rep.json().catch(()=>null)}
  catch(e){return undefined}
  if(!j||typeof j.status!=='number'||j.status>=500)return undefined;
  if(j.status!==200||!j.data){SESSIONS_PC.delete(k);return null}
  for(const [c,v] of SESSIONS_PC)if(now-v.t>=60000)SESSIONS_PC.delete(c);
  // nom et secteurs (2026-11-12, console B1) : auteur des changements et secteurs permis pris dans la SESSION, jamais
  // dans la requête (télés).
  const moi={admin:!!j.data.admin,parties:j.data.parties&&typeof j.data.parties==='object'?j.data.parties:{},
    nom:String(j.data.nom||'').slice(0,60),secteurs:Array.isArray(j.data.secteurs)?j.data.secteurs.map(String):[]};
  SESSIONS_PC.set(k,{t:now,moi});
  return moi;
}

