// --- Préparation au démarrage -----------------------------------------------------------------
// Avant d'ouvrir la console : aperçu construit, puis tout ce que la console affiche est lu d'avance (site internet,
// GitHub, Google Sheet : tablettes et contenus des 6 applications). La page reçoit ensuite ces réponses tout de suite.
const PREPA={pret:false,etape:'Démarrage…',fait:0,total:0,avis:[]};
const PRECHARGE=new Map(); // « /api/…?… » → {t, p} : réponse lue d'avance, servie une seule fois (2 minutes au plus)
function precharger(cle){
  const u=new URL('http://console'+cle),p=routes['GET '+u.pathname]({},u);
  PRECHARGE.set(cle,{t:Date.now(),p});
  return p.then(()=>{},e=>{PREPA.avis.push(e.message||String(e))}).finally(()=>{PREPA.fait++});
}
async function preparerConsole(){
  await new Promise(ok=>setImmediate(ok));
  // --ecrans-seuls (2026-11-10, Raspberry Pi d'une télé) : ni aperçu du pack ni lectures d'avance des applis au
  // démarrage ; les écrans lisent eux-mêmes ce qu'il leur faut.
  if(process.argv.includes('--ecrans-seuls')){PREPA.etape='Tout est prêt.';PREPA.pret=true;console.log('Écrans seuls : prêt.');return}
  if(!SEUL){
    PREPA.etape='Préparation de l’aperçu des tablettes…';
    try{apercuAJour()}catch(e){console.error('Aperçu : '+e.message);PREPA.avis.push('Aperçu : '+e.message)}
  }
  PREPA.etape=SEUL?'Lecture des machines dans la Google Sheet…':'Lecture du site internet, de GitHub et de la Google Sheet…';
  const cles=SEUL?['/api/etat','/api/lancements']:['/api/etat','/api/historique','/api/tablettes',...Object.keys(APPS).map(a=>'/api/maintenance?app='+a)];
  PREPA.total=cles.length;
  const tout=Promise.all(cles.map(precharger));
  // Au plus 90 secondes : un service lent ne doit pas bloquer l'ouverture (la console relira elle-même).
  await Promise.race([tout,new Promise(ok=>setTimeout(ok,90000))]);
  PREPA.etape=PREPA.fait<PREPA.total?'Ouverture (certaines lectures continuent)…':'Tout est prêt.';
  PREPA.pret=true;
  console.log('Console prête'+(PREPA.avis.length?' — avis : '+PREPA.avis.join(' | '):'.'));
}
// Réponse lue d'avance pour cette adresse (sinon null). Une modification (POST) les périme toutes.
async function dejaLu(cle){
  const x=PRECHARGE.get(cle);if(!x)return null;
  PRECHARGE.delete(cle);
  if(Date.now()-x.t>120000)return null;
  try{return {r:await x.p}}catch(e){return null}
}

