});

async function traiter(req,res){
  // Seulement depuis ce PC, et seulement par la page de la console (protège le jeton GitHub).
  if(!hotes.has(req.headers.host||''))return envoyer(res,403,{erreur:'Accès refusé.'});
  const url=new URL(req.url,'http://'+req.headers.host),route=routes[req.method+' '+url.pathname];
  if(url.pathname==='/google-local'&&!SEUL)return relaisGoogle(req,res);
  if(route){
    if(req.headers['x-console']!=='1'||(req.headers.origin&&!hotes.has(req.headers.origin.replace(/^https?:\/\//,''))))return envoyer(res,403,{erreur:'Accès refusé.'});
    // Nouvelle console (relecture du lot 7, I1) : session de la console vérifiée auprès du script Google ; parties du PC
    // (version, publier, revenir, construire, liaisons) réservées à l'administrateur. L'ancienne console n'envoie pas
    // cet en-tête : elle marche comme avant (secours si Google ne répond pas ; la session Windows reste sa protection).
    const cle=req.method+' '+url.pathname;let ctx=null;
    if(req.headers['x-console-nouvelle']==='1'){
      const m=await sessionConsole(String(req.headers['x-jeton']||''));
      if(m===undefined)return envoyer(res,503,{erreur:'Google ne répond pas : votre session ne peut pas être vérifiée. En secours : ancienne console (/ancienne).'});
      if(!m)return envoyer(res,401,{erreur:'Session terminée : reconnectez-vous.'});
      const exige=DROITS_ROUTES_PC[cle];
      if(!m.admin&&(ROUTES_ADMIN_PC.has(cle)||!exige||!((m.parties||{})[exige[0]]==='modif'||(exige[1]==='lecture'&&(m.parties||{})[exige[0]]==='lecture'))))
        return envoyer(res,403,{erreur:'Vous n’avez pas le droit de faire cela.'});
      ctx={nouvelle:true,moi:m};
    }else if(!SEUL&&!routeLibre(cle,url)){
      // Ancienne console (campagne de tests 2026-10-17, défaut grave) : plus de lecture ni d'écriture sans une session
      // d'ADMINISTRATEUR de la console (jeton envoyé par l'ancienne console, ouverte depuis la nouvelle dans le même
      // onglet). Secours : si Google ne répond pas (session impossible à vérifier), elle reste utilisable comme avant.
      const j=String(req.headers['x-jeton']||''),m=j?await sessionConsole(j):(googleEnPanne()?undefined:null);
      if(m===null)return envoyer(res,401,{erreur:'Ancienne console : ouvrez-la depuis la console, connecté en administrateur (lien en bas du menu).',code:'ancienne'});
      if(m&&!m.admin)return envoyer(res,403,{erreur:'L’ancienne console est réservée à l’administrateur.',code:'ancienne'});
      if(m===undefined&&!routeSecours(cle))return envoyer(res,503,{erreur:'Google ne répond pas : en secours, l’ancienne console permet seulement de lire et de garder des brouillons sur ce PC. Réessayez quand Google répond.',code:'secours'});
    }
    if(req.method!=='GET')PRECHARGE.clear();
    else if(!ctx){const d=await dejaLu(url.pathname+url.search);if(d)return envoyer(res,200,d.r)}
    try{envoyer(res,200,await route(req.method==='POST'?await (cle==='POST /api/tele-pptx'?lireCorpsGrand(req,42e6):cle==='POST /api/tele-video-fichier'?{}:lireCorps(req)):{},url,ctx,req))}
    // Codes justes (développeur 2026-11-12, B7) : 4xx / 5xx voulus gardés (403 droits, 503 Google ne répond pas) ;
    // corps JSON illisible = 400 (lireCorpsGrand).
    catch(e){console.error(e);envoyer(res,e instanceof ErreurGitHub?502:e.status>=400&&e.status<600?e.status:500,{erreur:e.message||String(e)})}
    return;
  }
  // Console du PC (lot 7, 2026-10-15) : la NOUVELLE interface = la page de la console en ligne, assemblée ici avec l'adresse
  // Google des Réglages de ce PC ; connexion par nom et code console (script Google). L'ancienne console reste en secours
  // à /ancienne. Le logiciel « Lancements machines » seul garde l'ancienne page.
  // Tablette d'essai (2026-10-26) : page publique sans secret (voir pageEssai), lue par la partie « Tablette d'essai ».
  if(!SEUL&&url.pathname==='/tablette-essai.html'){
    try{return envoyer(res,200,pageEssai(),TYPES['.html'])}
    catch(e){console.error(e);return envoyer(res,500,'Tablette d’essai indisponible : '+e.message,'text/plain; charset=utf-8')}
  }
  if(!SEUL&&(url.pathname==='/'||url.pathname==='/index.html')){
    let page;const g=reglages().google||{};
    try{page=assemblerConsole({pc:true,urlGoogle:g.url||'',autres:[g.code]})}
    catch(e){console.error(e);return envoyer(res,500,'Nouvelle console indisponible ('+e.message+') : ouvrez l’ancienne console : http://localhost:'+PORT+'/ancienne','text/plain; charset=utf-8')}
    return envoyer(res,200,page,TYPES['.html']);
  }
  if(!SEUL&&(url.pathname==='/ancienne'||url.pathname==='/console.html'))return fichier(res,path.join(ici,'console.html'));
  if(url.pathname==='/'||url.pathname==='/console.html'){
    if(!SEUL)return fichier(res,path.join(ici,'console.html'));
    // La page sait qu'elle est le logiciel « Lancements machines » seul.
    return envoyer(res,200,fs.readFileSync(path.join(ici,'console.html'),'utf8').replace('<head>','<head><script>window.CONSOLE_SEULE=\''+SEUL+'\'</script>'),TYPES['.html']);
  }
  // Écran de l'atelier (télé) : fichiers à lancer en temps réel. Son code d'affichage et la liste des machines viennent de
  // l'appli Lancements (/lancements-commun.js, 2026-10-21) : la même présentation que l'onglet « Écran atelier » des tablettes.
  if(url.pathname==='/ecran')return fichier(res,path.join(ici,'ecran.html'));
  if(url.pathname==='/lancements-commun.js'){try{return envoyer(res,200,lancementsCommun().js,'text/javascript; charset=utf-8')}catch(e){return envoyer(res,500,'// '+String(e.message).replace(/\n/g,' '),'text/javascript; charset=utf-8')}}
  // Écran télé de la maintenance niveau 1 d'un secteur (?secteur=fraisage) et logo 3D de l'accueil des tablettes.
  if(url.pathname==='/ecran-maintenance'&&!SEUL)return fichier(res,path.join(ici,'ecran-maintenance.html'));
  // Écran tournant (2026-10-21) : une télé qui montre les écrans ci-dessus à tour de rôle (lecture seule, sans connexion).
  if(url.pathname==='/ecran-tournant'&&!SEUL)return fichier(res,path.join(ici,'ecran-tournant.html'));
  // Télé pilotée à distance (2026-11-10) : page unique ouverte en plein écran par le Raspberry Pi (/tele?id=tele-fours).
  if(url.pathname==='/tele'&&!SEUL)return fichier(res,path.join(ici,'tele.html'));
  // Vidéos gardées sur ce programme (2026-11-12), lues par la page /tele (requêtes Range).
  if(url.pathname.startsWith('/video/')&&!SEUL)return videoServir(req,res,url);
  // Écran télé des Fours (2026-10-22) et son code commun (pris dans Fours\Fours.html).
  if(url.pathname==='/ecran-fours'&&!SEUL)return fichier(res,path.join(ici,'ecran-fours.html'));
  // Écran télé du cahier de liaison (2026-10-23), ?secteur=…
  if(url.pathname==='/ecran-liaison'&&!SEUL)return fichier(res,path.join(ici,'ecran-liaison.html'));
  if(url.pathname==='/fours-commun.js'&&!SEUL){try{return envoyer(res,200,foursCode().js,'text/javascript; charset=utf-8')}catch(e){return envoyer(res,500,'// '+String(e.message).replace(/\n/g,' '),'text/javascript; charset=utf-8')}}
  if(url.pathname==='/logo-premium.js')return fichier(res,path.join(pack,'commun','logo-premium.js'));
  // Bibliothèque publique du code QR de l'ancienne console (QRCode.js, MIT, commun\vendeur\) : servie depuis ce PC pour
  // marcher sans internet (2026-10-21). Ressource statique sans secret → pas de session ; un seul fichier nommé.
  if(url.pathname==='/vendeur/qrcode.min.js')return fichier(res,path.join(pack,'commun','vendeur','qrcode.min.js'));
  // Fiche « Que faire si… » (Pack-Tablettes\Que-faire-si.html), ouverte depuis le témoin « Google ».
  if(url.pathname==='/que-faire-si')return fichier(res,path.join(pack,'Que-faire-si.html'));
  // Calendrier de maintenance : l'appli Maintenance niveau 1 elle-même, en mode console (secteur choisi, Google de la
  // console), et son moteur de calendrier seul (bloc <calendrier>) pour l'écran fraisage.
  if(!SEUL&&(url.pathname==='/maintenance-console'||url.pathname==='/maintenance-calendrier.js')){
    let src='';try{src=fs.readFileSync(path.join(path.dirname(pack),'Maintenance niveau 1','Maintenance-niveau-1.html'),'utf8')}catch(e){return envoyer(res,404,'Application Maintenance introuvable.','text/plain; charset=utf-8')}
    if(url.pathname==='/maintenance-calendrier.js'){
      const m=/\/\/ <calendrier>[^\n]*\n([\s\S]*?)\/\/ <\/calendrier>/.exec(src);
      return m?envoyer(res,200,m[1]+'\nwindow.CalMaint=CalMaint;\n','text/javascript; charset=utf-8'):envoyer(res,404,'Moteur introuvable.','text/plain; charset=utf-8');
    }
    const sec=(url.searchParams.get('secteur')||'fraisage').replace(/[^a-z0-9-]/g,'').slice(0,30)||'fraisage',g=reglages().google;
    // Machines du secteur (Administration › Secteurs et zones des tablettes, dans Google) : machines du secteur + celles
    // de ses zones, ajoutées à la liste de l'appli comme sur les tablettes (2026-10-14).
    // Parc machines : machines en service du secteur + anciens noms (renommages). Sans parc : la liste de l'appli.
    // Fiches (lecture seule : type, axes…) et types du parc, pour les versions par type et les étapes par axe.
    // typesRenommes (2026-10-15) : ancien nom de type → nom actuel, comme renommes pour les machines.
    // personnes (2026-10-15) : celles du secteur (personnesSecteur), proposées dans l'appli avec la liste des Réglages.
    let machines=null,renommes={},typesRenommes={},fiches=[],types=[],personnes=[],personnesNoms={};
    try{const d=await google(reglages(),{app:'pack',operation:'pull'}),s=d&&d.site||{};personnes=personnesSecteur(s,sec);personnesNoms=personnesNomsDe(s);if(s.parc){machines=parcSecteur(s,sec);renommes=parcRenommes(s);typesRenommes=parcTypesRenommes(s);
      fiches=(s.parc.machines||[]).filter(m=>m.secteur===sec).map(({nom,type,marque,modele,serie,axes,nomsAxes,broches,photo})=>({nom,type,marque,modele,serie,axes,nomsAxes,broches,photo}));types=(s.parc.types||[]).map(t=>t.nom)}}catch(e){}
    // Relecture 2026-10-17 (I2) : code factice ; les appels à Google passent par le relais (session administrateur).
    const branche='<head>\n'+scriptRelais(g.url)+'<script>window.CONSOLE_MAINT='+JSON.stringify({secteur:sec,url:g.url||'',code:g.code?CODE_RELAIS:'',machines,renommes,typesRenommes,fiches,types,personnes,personnesNoms}).replace(/</g,'\\u003c')+';</script><script src="/logo-premium.js"></script>';
    return envoyer(res,200,src.replace('<head>',()=>branche),TYPES['.html']);
  }
  if(SEUL&&url.pathname.startsWith('/apercu'))return envoyer(res,404,'Introuvable','text/plain; charset=utf-8');
  // Logo du logiciel (celui de l'accueil des tablettes) : icône de la fenêtre de la console et en-tête.
  if(url.pathname==='/logo.png'){const l=logo();return l?envoyer(res,200,l,'image/png'):envoyer(res,404,'Introuvable','text/plain; charset=utf-8')}
  // Aperçu de la version construite (avant de la publier).
  if(url.pathname==='/apercu')return res.writeHead(302,{Location:'/apercu/'}).end();
  if(url.pathname.startsWith('/apercu/')){
    let nom;try{nom=decodeURIComponent(url.pathname.slice(8))}catch(e){return envoyer(res,400,'Adresse invalide','text/plain; charset=utf-8')}
    // L'aperçu montre toujours les applications telles qu'elles sont sur ce PC.
    if(!nom||nom==='index.html'){
      try{apercuAJour()}catch(e){console.error(e);return envoyer(res,500,'Aperçu impossible : '+e.message,'text/plain; charset=utf-8')}
    }
    // Pas de copie hors ligne dans l'aperçu (elle montrerait l'ancienne version) : celle-ci s'efface toute seule.
    if(nom==='sw.js')return envoyer(res,200,SW_APERCU,'text/javascript; charset=utf-8');
    const f=path.normalize(path.join(DOSSIER_EN_LIGNE,nom||'index.html'));
    if(f!==DOSSIER_EN_LIGNE&&!f.startsWith(DOSSIER_EN_LIGNE+path.sep))return envoyer(res,403,'Refusé','text/plain');
    // Aperçu (relecture 2026-10-17, I2) : chaque page HTML reçoit le relais (scriptRelais) et un code FACTICE ; le vrai
    // code de la Sheet n'est jamais envoyé à la page. Les appels à Google passent par /google-local (session
    // d'administrateur exigée). Servi à 127.0.0.1 (ancienne console) comme à localhost : même règle.
    const fh=f.endsWith(path.sep)?path.join(f,'index.html'):f;
    if(/\.html?$/i.test(fh)&&fs.existsSync(fh)&&!fs.statSync(fh).isDirectory()){
      const g=reglages().google||{};
      // Les applis du pack unique sont des cadres « srcdoc » (PACK_APPS, chaînes JSON où « < » est écrit <) : le
      // relais est posé aussi dans chacune, sinon leurs appels partiraient vers Google avec le code factice.
      const sr=scriptRelais(g.url),srJ=JSON.stringify(sr).slice(1,-1).replace(/</g,'\\u003c');
      const page=fs.readFileSync(fh,'utf8').replace('<head>',()=>'<head>'+sr).split('\\u003chead>').join('\\u003chead>'+srJ);
      return envoyer(res,200,page,TYPES['.html']);
    }
    return fichier(res,f.endsWith(path.sep)?path.join(f,'index.html'):f);
  }
  envoyer(res,404,'Introuvable','text/plain; charset=utf-8');
}
