// Reconstruit la version de ce PC si elle manque ou si une application a été modifiée depuis (5 s de marge :
// les dates des fichiers du logiciel Windows sont arrondies à 2 s).
function apercuAJour(){
  let v=null;try{v=JSON.parse(fs.readFileSync(path.join(DOSSIER_EN_LIGNE,'version.json'),'utf8'))}catch(e){}
  if(fs.existsSync(path.join(DOSSIER_EN_LIGNE,'index.html'))&&v&&v.sources&&v.sources>=dateSources()-5000)return;
  console.log('Aperçu : construction de la version à jour…');
  construire({enLigne:true,notes:'',journal:t=>console.log(t)});
}
// Service worker de l'aperçu : remplace celui des tablettes, vide la copie gardée et ne garde plus rien (pas de
// gestion des requêtes : tout vient du PC). Il ne change jamais, donc il ne s'installe (et ne recharge la page) qu'une fois.
const SW_APERCU=`// Aperçu du PC : pas de copie hors ligne (toujours la version à jour du PC).
self.addEventListener('install',function(){self.skipWaiting()});
self.addEventListener('activate',function(e){
  e.waitUntil(caches.keys().then(function(l){return Promise.all(l.map(function(k){return caches.delete(k)}))})
    .then(function(){return self.clients.claim()})
    .then(function(){return self.clients.matchAll({type:'window'})})
    .then(function(l){l.forEach(function(c){c.navigate(c.url)})}));
});
`;

