// Assemble le Pack Tablettes en UN SEUL fichier.
//   node construire-unique.mjs                     → Pack-Tablettes.html (à copier sur une tablette, comme avant)
//   node construire-unique.mjs --en-ligne "notes"  → dossier en-ligne\ : le site internet à publier (console du PC)
//   node construire-unique.mjs --console-en-ligne  → en-ligne\console\index.html seulement (console en ligne, lot 3)
// Contenu : Accueil.html + commun/site.js + secteurs/*.js + commun/pack.js, et les 6 applications prises dans
// leurs dossiers d'origine (comme construire-pack.ps1), rangées dans window.PACK_APPS et ouvertes dans un cadre.
// À relancer après toute modification d'une application ou du pack.
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import crypto from 'node:crypto';
import vm from 'node:vm';
import {fileURLToPath,pathToFileURL} from 'node:url';
const ici=path.dirname(fileURLToPath(import.meta.url)),racine=path.dirname(ici);
const lire=f=>fs.readFileSync(f,'utf8');
const APPLIS=[
 {id:'releve',source:'Atelier/Atelier-tablettes/Apercu-atelier.html'},
 {id:'taches',source:'Prod tache atelier/Taches-atelier.html'},
 {id:'fiches',source:'Fiches reflexes/Fiches-reflexes.html'},
 {id:'maintenance',source:'Maintenance niveau 1/Maintenance-niveau-1.html'},
 {id:'procedures',source:'Procedures/Procedures.html'},
 {id:'lancements',source:'Lancements/Lancements.html'},
 {id:'fours',source:'Fours/Fours.html'},
 {id:'liaison',source:'Liaison/Liaison.html'},
 {id:'tableau',source:'Tableau de bord/Tableau-de-bord.html'}
];
export const DOSSIER_EN_LIGNE=path.join(ici,'en-ligne');
// Un texte mis dans <script> ne doit pas contenir « </script » (il fermerait la balise).
const sur=(nom,js)=>{if(/<\/script/i.test(js))throw new Error(nom+' contient </script : impossible de l’intégrer tel quel.');return js};

// Bibliothèques extérieures acceptées par l'utilisateur (2026-10-21), rangées dans commun\vendeur\ (LICENCES.txt) :
// seules celles-ci, et seulement avec cette empreinte SHA-256 (un fichier changé n'est jamais publié en silence).
export const BIBLIOTHEQUES={
 'jsQR.js':{nom:'jsQR 1.4.0',licence:'Apache-2.0',source:'https://github.com/cozmo/jsQR',sha256:'BC40C8A15196236B2314DB0856F72CA0B49980CD5413B8C852A7349F5FEE0859'},
 'qrcode.min.js':{nom:'QRCode.js 1.0.0',licence:'MIT',source:'https://github.com/davidshimjs/qrcodejs',sha256:'C541EF06327885A8415BCA8DF6071E14189B4855336DEF4F36DB54BDE8484F36'}
};
// Remplace chaque <script src="vendeur/X"></script> d'une page par le contenu vérifié de commun\vendeur\X : la page
// publiée reste UN fichier, sans rien à charger (marche hors ligne, aucun site extérieur). Erreur si une bibliothèque
// est inconnue, absente ou modifiée, ou s'il reste une ressource à charger.
export function integrerBibliotheques(html){
 const page=html.replace(/<script src="vendeur\/([^"]+)"><\/script>/g,(t,nom)=>'<script>'+bibliotheque(nom)+'\n</script>');
 if(/<script[^>]*\ssrc\s*=/i.test(page)||/\s(?:src|href)\s*=\s*["']?(?:https?:)?\/\//i.test(page))throw new Error('ressource extérieure restante dans la page');
 return page;
}
// Contenu vérifié d'une bibliothèque de commun\vendeur\ (empreinte contrôlée), à mettre tel quel dans un <script>.
// QR machines (2026-10-21) : sert aussi à l'appli Maintenance (jsQR) et à la console (QRCode.js, étiquettes).
export function bibliotheque(nom){
 const b=Object.prototype.hasOwnProperty.call(BIBLIOTHEQUES,nom)&&BIBLIOTHEQUES[nom];
 if(!b)throw new Error('bibliothèque inconnue « '+nom+' »');
 const f=path.join(ici,'commun','vendeur',nom);
 if(!fs.existsSync(f))throw new Error('bibliothèque absente : commun\\vendeur\\'+nom);
 const brut=fs.readFileSync(f),h=crypto.createHash('sha256').update(brut).digest('hex').toUpperCase();
 if(h!==b.sha256)throw new Error('empreinte de commun\\vendeur\\'+nom+' différente ('+h.slice(0,16)+'… au lieu de '+b.sha256.slice(0,16)+'…)');
 const js=sur(nom,brut.toString('utf8'));
 if(js.includes('<!--'))throw new Error(nom+' contient « <!-- » : impossible de l’intégrer tel quel.');
 return '/* '+b.nom+' — licence '+b.licence+' — '+b.source+' (commun/vendeur/LICENCES.txt) */\n'+js;
}

// Fours (2026-10-22) : code commun de Fours\Fours.html (bloc fusion : données, liste des fours du parc, alarmes ; bloc
// <ecran-fours> : écran télé, sirène), en UNE expression « (function(){…})() » → objet. Sert à la console (assemblerConsole :
// var FoursCommun) et au PC de la télé (serveur.mjs /fours-commun.js, /api/fours). Appli absente : null.
export function foursCommun(){
 const f=path.join(racine,'Fours','Fours.html');if(!fs.existsSync(f))return null;
 const src=lire(f),bloc=(a,b)=>{const i=src.indexOf(a),j=src.indexOf(b,i);if(i<0||j<0)throw new Error('Bloc '+a+' introuvable dans Fours.html');return src.slice(src.indexOf('\n',i)+1,j)};
 const code=bloc('// <fusion>','// </fusion>')+'\n'+bloc('// <ecran-fours>','// </ecran-fours>');
 const expo='{normalizeState:normalizeState,appliquer:appliquer,foursListe:foursListe,etatFour:etatFour,alarmes:alarmes,normNum:normNum,formeNum:formeNum,lireEtiquette:lireEtiquette,propositions:propositions,normReglages:normReglages,FOURS_RAPPELS:FOURS_RAPPELS,FOURS_DUREE:FOURS_DUREE,EcranFours:EcranFours,Sirene:Sirene,Sonneur:Sonneur}';
 const js='(function(){\n'+code+'\nreturn '+expo+';\n})()';
 if(js.includes('<!--'))throw new Error('Fours.html : « <!-- » dans le code commun.');
 return sur('Fours.html',js);
}
// Liaison (2026-10-23) : code commun de Liaison\Liaison.html (bloc fusion : données, droits, récurrence, équipes ; bloc
// <garde-fou> : relecture de la charte), en UNE expression « (function(){…})() » → objet. Sert à la console (assemblerConsole :
// var LiaisonCommun) et au PC de la télé (serveur.mjs /api/liaison). Appli absente : null.
export function liaisonCommun(){
 const f=path.join(racine,'Liaison','Liaison.html');if(!fs.existsSync(f))return null;
 const src=lire(f),bloc=(a,b)=>{const i=src.indexOf(a),j=src.indexOf(b,i);if(i<0||j<0)throw new Error('Bloc '+a+' introuvable dans Liaison.html');return src.slice(src.indexOf('\n',i)+1,j)};
 const code=bloc('// <fusion>','// </fusion>')+'\n'+bloc('// <garde-fou>','// </garde-fou>');
 const expo='{'+['normalizeState','appliquer','aLire','aLireParEquipe','recurrences','ranger','normPlateau','formePlateau','normCatalogue','garderArchives','faitDe','causeDe','precisDe','faitsDuSecteur','nomFait','nomCause','equipeDe','nomEquipe','normReglages','equipesA','equipeArrivee','debutEquipe','durableOuvert','durablesDuMessage',
  'LIAISON_ETATS','LIAISON_ORDRE','LIAISON_REC','LIAISON_TXT','LIAISON_MAX','LIAISON_LIM','LIAISON_ICONES','LIAISON_CATALOGUE_DEFAUT','GardeFou'].map(k=>k+':'+k).join(',')+'}';
 const js='(function(){\n'+code+'\nreturn '+expo+';\n})()';
 if(js.includes('<!--'))throw new Error('Liaison.html : « <!-- » dans le code commun.');
 return sur('Liaison.html',js);
}
// Version en ligne : la page est publique. Le code d'accès de la Google Sheet en est retiré (tapé une fois sur
// chaque tablette) et la configuration de départ ne contient aucune personne (elle vient de Google).
function siteEnLigne(js){
 const m=/window\.PACK_SITE\s*=\s*([\s\S]*?);?\s*$/.exec(js.trim());
 const s=JSON.parse(m[1]);s.personnes=[];s.maj=1;delete s.google;
 return '// Configuration de départ du pack en ligne (personnes et codes : Google).\nwindow.PACK_SITE='+JSON.stringify(s,null,1)+';\n';
}
function codeGoogle(pack){const m=/GOOGLE_DEFAUT=\{url:'[^']*',code:'([^']+)'\}/.exec(pack);return m?m[1]:''}
function idVersion(d){const p=n=>String(n).padStart(2,'0');return d.getFullYear()+p(d.getMonth()+1)+p(d.getDate())+'-'+p(d.getHours())+p(d.getMinutes())}

// Date des sources (la plus récente modification des 6 applications et du pack) : rangée dans chaque version
// pour savoir si la version en ligne contient des applications plus récentes que celles de ce PC (logiciel ancien).
export function dateSources(){
 const f=[...APPLIS.map(a=>path.join(racine,a.source)),path.join(ici,'Accueil.html'),
  ...['commun','secteurs'].flatMap(d=>fs.readdirSync(path.join(ici,d)).filter(x=>x.endsWith('.js')&&x!=='essai-tablette.js').map(x=>path.join(ici,d,x)))];
 return Math.max(...f.map(x=>{try{return fs.statSync(x).mtimeMs}catch(e){return 0}}));
}

export function construire({enLigne=false,notes='',journal=console.log}={}){
 let site=sur('site.js',lire(path.join(ici,'commun','site.js')));
 const pack=sur('pack.js',lire(path.join(ici,'commun','pack.js')));
 const secteurs=fs.readdirSync(path.join(ici,'secteurs')).filter(f=>f.endsWith('.js')&&f!=='modele-vierge.js').sort()
  .map(f=>sur(f,lire(path.join(ici,'secteurs',f)))).join('\n');
 if(enLigne)site=siteEnLigne(site);

 const apps={};
 // QR machines (2026-10-21) : lecteur de secours jsQR (commun\vendeur\, empreinte contrôlée) intégré à l'appli
 // Maintenance, pour lire les étiquettes sans le lecteur du navigateur, hors ligne. Bibliothèque absente ou modifiée :
 // le pack se construit quand même ; la Maintenance ne lit alors qu'avec le lecteur du navigateur (s'il existe).
 let jsqr='';
 try{jsqr='<script>\n'+bibliotheque('jsQR.js')+'\n</script>'}catch(e){journal('⚠ Maintenance : lecteur jsQR NON intégré ('+e.message+').')}
 // Fours (2026-11-10) : QRCode.js pour imprimer les étiquettes par four (onglet Étiquettes).
 let qrgen='';
 try{qrgen='<script>\n'+bibliotheque('qrcode.min.js')+'\n</script>'}catch(e){journal('⚠ Fours : QRCode.js NON intégré ('+e.message+').')}
 for(const a of APPLIS){
  const html=lire(path.join(racine,a.source)),i=html.indexOf('<head>');
  if(i<0)throw new Error('Pas de <head> dans '+a.source);
  // Dans le cadre, la configuration et les secteurs viennent de l'accueil (window.parent).
  const branchement='<head>\n<script>window.PACK_UNIQUE=true;window.PACK_SITE=parent.PACK_SITE;window.PACK_SECTEURS=parent.PACK_SECTEURS;window.PACK_VERSION=parent.PACK_VERSION;</script>'+
   '<script data-appli="'+a.id+'">'+pack+'</script>'+
   // Maintenance : logo 3D de l'accueil (commun/logo-premium.js) pour son écran télé, et lecteur de QR jsQR.
   // Lancements (2026-10-21) : le même logo 3D pour son écran télé (onglet « Écran atelier »).
   (a.id==='maintenance'?'<script>\n'+sur('logo-premium.js',lire(path.join(ici,'commun','logo-premium.js')))+'\n</script>'+jsqr:a.id==='fours'?jsqr+qrgen+'<script>\n'+sur('logo-premium.js',lire(path.join(ici,'commun','logo-premium.js')))+'\n</script>':a.id==='liaison'?jsqr:a.id==='lancements'?'<script>\n'+sur('logo-premium.js',lire(path.join(ici,'commun','logo-premium.js')))+'\n</script>':'');
  apps[a.id]=html.slice(0,i)+branchement+html.slice(i+6);
  journal('  '+a.id.padEnd(12)+' <- '+a.source+' ('+Math.round(html.length/1024)+' Ko)');
 }
 // JSON sans « < » brut : rien ne peut fermer la balise <script> qui le contient.
 const json=JSON.stringify(apps).replace(/</g,'\\u003c').replace(new RegExp('\\u2028','g'),'\\u2028').replace(new RegExp('\\u2029','g'),'\\u2029');

 let accueil=lire(path.join(ici,'Accueil.html'));
 const liens='<script src="commun/site.js"></script>\n<script src="commun/pack.js"></script>';
 if(!accueil.includes(liens))throw new Error('Accueil.html : liens vers commun/site.js et commun/pack.js introuvables.');
 const version=enLigne?{id:idVersion(new Date()),date:Date.now(),notes:String(notes||'').slice(0,500),sources:Math.round(dateSources())}:null;
 const enTete=enLigne?'<link rel="manifest" href="manifest.webmanifest">\n<link rel="icon" href="icone-192.png">\n<link rel="apple-touch-icon" href="icone-192.png">\n'+
  '<meta name="mobile-web-app-capable" content="yes">\n<script>window.PACK_VERSION='+JSON.stringify(version).replace(/</g,'\\u003c')+';</script>\n':'';
 // Logo 3D de l'accueil (commun/logo-premium.js) : intégré dans la page comme le reste.
 const lienLogo='<script src="commun/logo-premium.js"></script>';
 if(!accueil.includes(lienLogo))throw new Error('Accueil.html : lien vers commun/logo-premium.js introuvable.');
 const logo3d=sur('logo-premium.js',lire(path.join(ici,'commun','logo-premium.js')));
 accueil=accueil.replace(lienLogo,()=>'<script>\n'+logo3d+'\n</script>');
 accueil=accueil.replace(liens,()=>enTete+'<script>\n'+site+'\n</script>\n<script>\n'+secteurs+'\n</script>\n<script>\n'+pack+'\n</script>\n<script>window.PACK_APPS='+json+';</script>'+
   (enLigne?'\n<script>\n'+sur('en-ligne.js',lire(path.join(ici,'commun','en-ligne.js')))+'\n</script>':''))
  .replace('<title>Accueil — Lynk</title>','<title>Lynk</title>');

 if(!enLigne){
  const sortie=path.join(ici,'Pack-Tablettes.html');
  fs.writeFileSync(sortie,accueil);
  journal('Pack en un seul fichier : '+sortie+' ('+Math.round(accueil.length/1024)+' Ko)');
  return {sortie};
 }
 // Retire le code d'accès Google partout (pack.js, secteur frittage, valeurs préremplies des applications).
 const code=codeGoogle(pack);
 if(code){accueil=accueil.split(code).join('');if(accueil.toUpperCase().includes(code.toUpperCase()))throw new Error('Le code d’accès Google est encore dans la page en ligne.')}
 fs.mkdirSync(DOSSIER_EN_LIGNE,{recursive:true});
 const ecrire=(f,d)=>fs.writeFileSync(path.join(DOSSIER_EN_LIGNE,f),d);
 ecrire('index.html',accueil);
 ecrire('version.json',JSON.stringify(version,null,1));
 ecrire('sw.js',lire(path.join(ici,'commun','sw.js')));
 ecrire('.nojekyll','');
 // Nom de l'application installée sur les tablettes : « Lynk » (2026-11-05). Le nom du site reste en description.
 const nom=(/"nom":\s*"([^"]*)"/.exec(site)||[])[1]||'Dent All Group';
 ecrire('manifest.webmanifest',JSON.stringify({name:'Lynk',short_name:'Lynk',description:'Lynk · '+nom+' · Atelier',start_url:'./',scope:'./',display:'standalone',
  orientation:'any',background_color:'#ffffff',theme_color:'#0b8a96',lang:'fr',
  icons:[{src:'icone-192.png',sizes:'192x192',type:'image/png'},{src:'icone-512.png',sizes:'512x512',type:'image/png',purpose:'any maskable'}]},null,1));
 ecrire('icone-192.png',icone(192));
 ecrire('icone-512.png',icone(512));
 // Essai caméra QR (2026-10-20, étape 1 des QR machines) : page autonome, sans bibliothèque ni envoi, publiée avec le
 // site (<site>/essai-camera.html). Le service worker du pack (commun\sw.js, NON modifié) remplace toute page du site
 // par la copie gardée du pack, SAUF une adresse qui porte « maj » : on l'ouvre donc avec « essai-camera.html?maj=1 ».
 // Facultative : fichier source absent ou contenant un code → l'ancienne copie est retirée (jamais publiée).
 // 2026-10-21 : ses bibliothèques (commun\vendeur\ : jsQR, QRCode.js) y sont intégrées ici (integrerBibliotheques) ;
 // bibliothèque manquante ou modifiée → page NON publiée, le reste du site se construit normalement.
 const essaiCamera=path.join(ici,'commun','essai-camera.html');
 let pageEssai='',refusEssai='';
 if(fs.existsSync(essaiCamera)){try{pageEssai=integrerBibliotheques(lire(essaiCamera))}catch(e){refusEssai=e.message}}
 if(pageEssai&&!contientCode(pageEssai))ecrire('essai-camera.html',pageEssai);
 else{fs.rmSync(path.join(DOSSIER_EN_LIGNE,'essai-camera.html'),{force:true});
  if(refusEssai)journal('⚠ essai-camera.html : '+refusEssai+' — page d’essai NON publiée.');
  else if(pageEssai)journal('⚠ essai-camera.html contient un code : page d’essai NON publiée.')}
 // Essai télé connectée (2026-10-26) : page autonome (aucune bibliothèque, rien envoyé) ouverte dans le navigateur
 // d'une télé : <site>/essai-tele.html?maj=1. Facultative ; absente ou contenant un code → non publiée.
 const essaiTele=path.join(ici,'commun','essai-tele.html');
 const pageTele=fs.existsSync(essaiTele)?lire(essaiTele):'';
 if(pageTele&&!contientCode(pageTele))ecrire('essai-tele.html',pageTele);
 else{fs.rmSync(path.join(DOSSIER_EN_LIGNE,'essai-tele.html'),{force:true});if(pageTele)journal('⚠ essai-tele.html contient un code : page NON publiée.')}
 journal('Site en ligne prêt : '+DOSSIER_EN_LIGNE+' — version '+version.id+' ('+Math.round(accueil.length/1024)+' Ko)');
  // La console en ligne ne doit jamais empêcher la construction du pack (console du PC inchangée). En cas d'échec :
 // l'ancienne copie est retirée (jamais publiée par erreur) et l'erreur est notée dans version.json (consoleErreur,
 // jamais publiée) pour que « Publier » le dise clairement.
 try{construireConsoleEnLigne({journal})}
 catch(e){
  journal('⚠ Console en ligne NON construite : '+e.message);
  fs.rmSync(path.join(DOSSIER_EN_LIGNE,'console'),{recursive:true,force:true});
  ecrire('version.json',JSON.stringify(Object.assign({},version,{consoleErreur:String(e.message).slice(0,300)}),null,1));
 }
 // Programme des télés (2026-11-24) : en-ligne\tele\ (manifeste.json + paquet.json), que le Raspberry de chaque télé va
 // chercher seul. Même règle que la console en ligne : un échec n'empêche jamais la construction du pack ; l'ancienne
 // copie est retirée (jamais publiée par erreur) et les télés gardent leur programme.
 try{const t=construireTele({dossier:path.join(DOSSIER_EN_LIGNE,'tele'),id:version.id,date:version.date});
  journal('Programme des télés prêt : '+t.nb+' fichiers, '+Math.round(t.taille/1024)+' Ko (empreinte '+t.empreinte.slice(0,12)+').')}
 catch(e){
  journal('⚠ Programme des télés NON construit : '+e.message+' — les télés gardent leur programme.');
  fs.rmSync(path.join(DOSSIER_EN_LIGNE,'tele'),{recursive:true,force:true});
 }
 return {sortie:DOSSIER_EN_LIGNE,version};
}

// --- Programme de l'écran télé (Raspberry Pi), 2026-11-24 : « mise à jour des télés par le réseau » ------------------
// UNE liste des fichiers dont le Raspberry d'une télé a besoin (console\serveur.mjs lancé avec --ecrans-seuls : les
// écrans, le code commun que le serveur lit dans 4 applis, le logo, les secteurs). Elle sert à la fois :
//   - à la carte SD (Raspberry-tele\preparer-kit.ps1 appelle « --programme-tele <dossier> ») ;
//   - au paquet publié avec le site (en-ligne\tele\manifeste.json + paquet.json), que la télé va chercher seule.
// Relevé fait dans serveur.mjs le 2026-11-24 : import de construire-unique.mjs ; /ecran, /ecran-maintenance,
// /ecran-tournant, /ecran-fours, /ecran-liaison, /tele ; /lancements-commun.js (Lancements.html), /maintenance-calendrier.js
// (Maintenance-niveau-1.html), /fours-commun.js (Fours.html), /api/liaison (Liaison.html) ; /logo.png (logo-lynk.png),
// /logo-premium.js ; noms des secteurs (secteurs\*.js) ; GOOGLE_DEFAUT (pack.js, vidé ici) ; /que-faire-si.
// VOLONTAIREMENT ABSENTS (copiés sur la carte jusqu'ici, inutiles à une télé) : Script-Google.txt (source complète du
// script Google), console.html et console en ligne, Accueil.html, applis Relève / Tâches / Fiches / Procédures /
// Tableau de bord, pages et fichiers d'essai, sw.js, site.js, en-ligne.js, bibliothèques jsQR / QRCode.js.
// Le site est PUBLIC : adresse et code Google réels effacés (comme preparer-kit.ps1 le faisait), contrôle final.
const PROGRAMME_TELE=[
 'Pack-Tablettes/construire-unique.mjs',
 'Pack-Tablettes/console/serveur.mjs','Pack-Tablettes/console/tele.html','Pack-Tablettes/console/ecran.html',
 'Pack-Tablettes/console/ecran-maintenance.html','Pack-Tablettes/console/ecran-tournant.html',
 'Pack-Tablettes/console/ecran-fours.html','Pack-Tablettes/console/ecran-liaison.html',
 'Pack-Tablettes/commun/pack.js','Pack-Tablettes/commun/logo-lynk.png','Pack-Tablettes/commun/logo-premium.js',
 'Pack-Tablettes/Que-faire-si.html',
 'Maintenance niveau 1/Maintenance-niveau-1.html','Lancements/Lancements.html','Fours/Fours.html','Liaison/Liaison.html'
];
// Chemin permis dans le paquet : relatif, lettres/chiffres/espace/point/tiret, aucun « . » ou « .. » (relu sur la télé).
export const CHEMIN_TELE=/^[A-Za-z0-9_-][A-Za-z0-9 ._-]*(\/[A-Za-z0-9_-][A-Za-z0-9 ._-]*)*$/;
const sha256=b=>crypto.createHash('sha256').update(b).digest('hex');
// Adresse et code Google RÉELS (pack.js GOOGLE_DEFAUT et fichiers secteurs) : lus en mémoire seulement, pour être effacés.
function secretsGoogle(){
 const l=[],pk=lire(path.join(ici,'commun','pack.js')),m=/GOOGLE_DEFAUT=\{url:'([^']*)',code:'([^']*)'\}/.exec(pk);
 if(m)l.push(m[1],m[2]);
 for(const f of fs.readdirSync(path.join(ici,'secteurs')).filter(x=>x.endsWith('.js')))
  for(const x of lire(path.join(ici,'secteurs',f)).matchAll(/google\s*:\s*\{\s*url\s*:\s*'([^']*)'\s*,\s*code\s*:\s*'([^']*)'\s*\}/g))l.push(x[1],x[2]);
 return [...new Set(l.filter(s=>s&&s.length>=6))];
}
// Les fichiers du programme télé, secrets effacés : {chemin: Buffer}. Erreur si un secret reste.
export function programmeTele(){
 const secteurs=fs.readdirSync(path.join(ici,'secteurs')).filter(f=>/^[a-z0-9-]+\.js$/.test(f)&&f!=='modele-vierge.js').sort().map(f=>'Pack-Tablettes/secteurs/'+f);
 const secrets=secretsGoogle(),out={};
 for(const rel of [...PROGRAMME_TELE,...secteurs]){
  if(!CHEMIN_TELE.test(rel))throw new Error('chemin refusé : '+rel);
  const f=path.join(racine,...rel.split('/'));
  if(!fs.existsSync(f))throw new Error('fichier introuvable : '+rel);
  if(/\.png$/.test(rel)){out[rel]=fs.readFileSync(f);continue}
  let t=lire(f);
  if(rel==='Pack-Tablettes/commun/pack.js')t=t.replace(/GOOGLE_DEFAUT=\{url:'[^']*',code:'[^']*'\}/,"GOOGLE_DEFAUT={url:'',code:''}");
  if(rel.startsWith('Pack-Tablettes/secteurs/'))t=t.replace(/google\s*:\s*\{\s*url\s*:\s*'[^']*'\s*,\s*code\s*:\s*'[^']*'\s*\}/g,"google:{url:'',code:''}");
  // Valeurs « de secours » des applis (GOOGLE_URL / GOOGLE_CODE) : la chaîne exacte entre guillemets est vidée.
  for(const s of secrets)for(const q of ["'",'"'])t=t.split(q+s+q).join(q+q);
  if(secrets.some(s=>t.includes(s))||contientCode(t)||/script\.google(?:usercontent)?\.com\/macros\/s\/[\w-]{20,}/.test(t))
   throw new Error('un secret (adresse ou code Google, jeton) reste dans '+rel+' : arrêt');
  out[rel]=Buffer.from(t,'utf8');
 }
 return out;
}
// Manifeste : empreinte SHA-256 et taille de chaque fichier ; « empreinte » = celle de l'ensemble (liste triée), pour
// savoir sans rien télécharger si la télé a déjà exactement ce programme.
function manifesteTele(fichiers,{id,date}){
 const liste={};for(const k of Object.keys(fichiers).sort())liste[k]={sha256:sha256(fichiers[k]),taille:fichiers[k].length};
 const empreinte=sha256(Object.keys(liste).map(k=>k+'\n'+liste[k].sha256+'\n').join(''));
 return {format:1,id:String(id||''),date:Number(date)||0,empreinte,fichiers:liste};
}
// Paquet publié (en-ligne\tele\) : paquet.json = tous les fichiers (texte tel quel « t », image en base64 « b »), sans
// date ni numéro : le même programme donne exactement le même paquet (GitHub ne le stocke qu'une fois) ;
// manifeste.json = numéro de version, empreintes, taille et SHA-256 du paquet. Le dossier est refait en entier.
export function construireTele({dossier,id,date=Date.now()}={}){
 const fichiers=programmeTele(),m=manifesteTele(fichiers,{id,date});
 const p={format:1,fichiers:{}};
 for(const k of Object.keys(m.fichiers))p.fichiers[k]=/\.png$/.test(k)?{b:fichiers[k].toString('base64')}:{t:fichiers[k].toString('utf8')};
 const paquet=Buffer.from(JSON.stringify(p),'utf8');
 if(contientCode(paquet.toString('utf8')))throw new Error('un code se trouve dans le paquet : arrêt');
 m.paquet={taille:paquet.length,sha256:sha256(paquet)};
 fs.rmSync(dossier,{recursive:true,force:true});fs.mkdirSync(dossier,{recursive:true});
 fs.writeFileSync(path.join(dossier,'paquet.json'),paquet);
 fs.writeFileSync(path.join(dossier,'manifeste.json'),JSON.stringify(m,null,1));
 return {nb:Object.keys(m.fichiers).length,taille:paquet.length,empreinte:m.empreinte,manifeste:m};
}
// Programme écrit en fichiers (carte SD : Raspberry-tele\kit\programme), avec version-tele.json (numéro, empreinte,
// liste) : la télé le lit pour dire sa version (console › Télés) et savoir si une mise à jour est nécessaire.
export function ecrireProgrammeTele(dest,{id=idVersion(new Date()),date=Date.now(),source='carte'}={}){
 const fichiers=programmeTele(),m=manifesteTele(fichiers,{id,date});
 for(const k of Object.keys(fichiers)){const f=path.join(dest,...k.split('/'));fs.mkdirSync(path.dirname(f),{recursive:true});fs.writeFileSync(f,fichiers[k])}
 fs.writeFileSync(path.join(dest,'version-tele.json'),JSON.stringify(Object.assign({},m,{source}),null,1));
 return {nb:Object.keys(fichiers).length,empreinte:m.empreinte,id:m.id};
}

// Codes d'accès connus de ce PC (code de la Google Sheet de pack.js, codes des fichiers secteurs, codes donnés en plus,
// par exemple celui des Réglages de la console) : aucun ne doit se trouver dans une page publique.
// Jetons GitHub reconnus à leur forme (ghp_, gho_, ghu_, ghs_, ghr_, github_pat_), même inconnus de ce PC.
export function contientCode(texte,autres=[]){
 const pack=lire(path.join(ici,'commun','pack.js'));
 const codes=[codeGoogle(pack),...autres].concat(fs.readdirSync(path.join(ici,'secteurs')).filter(f=>f.endsWith('.js'))
  .flatMap(f=>[...lire(path.join(ici,'secteurs',f)).matchAll(/code\s*:\s*['"]([^'"]{4,})['"]/g)].map(x=>x[1])))
  .map(c=>String(c||'').trim()).filter(c=>c.length>=4);
 const t=String(texte),T=t.toUpperCase();
 if(/\bgh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}/.test(t))return true;
 return codes.some(c=>T.includes(c.toUpperCase()));
}
// Console en ligne (lot 3, 2026-10-15) : console-en-ligne\index.html → en-ligne\console\index.html.
// On y range l'ADRESSE du script Google (celle de pack.js), jamais son code, et le moteur du calendrier de l'appli
// Maintenance (bloc <calendrier>, recopié tel quel comme pour l'écran fraisage). Rien n'est publié ici.
// essai : version pour les essais sur ce PC (imitation de Google) : la politique de sécurité (CSP) accepte aussi
// localhost ; la version publiée n'accepte que Google (script.google.com et sa redirection script.googleusercontent.com).
export function construireConsoleEnLigne({dossier=path.join(DOSSIER_EN_LIGNE,'console'),journal=console.log,essai=false}={}){
 const page=assemblerConsole({essai});
 // Application installable (2026-10-17) : manifeste, icônes (logo de l'atelier) et service worker PROPRES à /console/.
 // Le service worker ne garde que la page et ses fichiers statiques (jamais un appel à Google, jamais une donnée) ;
 // sa version suit la page : chaque publication est vue comme une mise à jour (bandeau « Nouvelle version »).
 const versionPage=crypto.createHash('sha256').update(page).digest('hex').slice(0,12);
 const manifeste=JSON.stringify({name:'Console de l’atelier',short_name:'Console atelier',description:'Console de l’atelier Dent All Group',lang:'fr',
  id:'./',start_url:'./',scope:'./',display:'standalone',orientation:'any',background_color:'#f3f6f7',theme_color:'#065E66',
  icons:[{src:'icone-192.png',sizes:'192x192',type:'image/png',purpose:'any'},{src:'icone-512.png',sizes:'512x512',type:'image/png',purpose:'any'},
   {src:'icone-512.png',sizes:'512x512',type:'image/png',purpose:'maskable'}]},null,1);
 const sw=lire(path.join(ici,'console-en-ligne','sw-console.js')).replace("var VERSION='';",()=>'var VERSION='+JSON.stringify(versionPage)+';');
 if(!sw.includes(versionPage))throw new Error('console-en-ligne\\sw-console.js : VERSION introuvable.');
 // Contrôle anti-secret : aussi sur le service worker et le manifeste.
 if(contientCode(sw)||contientCode(manifeste))throw new Error('Un code d’accès se trouve dans le service worker ou le manifeste de la console : construction arrêtée.');
 fs.mkdirSync(dossier,{recursive:true});
 const ecrire=(f,d)=>fs.writeFileSync(path.join(dossier,f),d);
 ecrire('index.html',page);ecrire('sw.js',sw);ecrire('manifest.webmanifest',manifeste);ecrire('icone-192.png',icone(192));ecrire('icone-512.png',icone(512));
 // Tablette d'essai (2026-10-26) : page à part, chargée par la partie « Tablette d'essai ». Échec : la console part
 // quand même, sans la page d'essai (la partie le dit) ; l'ancienne copie est retirée (jamais une page périmée).
 // Interrupteur ESSAI_EN_LIGNE (false) : page non publiée sur le site, seulement servie par la console du PC.
 if(!ESSAI_EN_LIGNE){fs.rmSync(path.join(dossier,'tablette-essai.html'),{force:true});journal('Tablette d’essai : non publiée sur le site (ESSAI_EN_LIGNE = false) ; console du PC seulement.')}
