// Lecture d'un PNG RGBA 8 bits non entrelacé (le logo de l'accueil) : {l, h, px} (4 octets par point).
function lirePng(buf){
 let p=8,l=0,h=0,idat=[];
 while(p<buf.length){
  const n=buf.readUInt32BE(p),type=buf.toString('latin1',p+4,p+8),d=buf.subarray(p+8,p+8+n);
  if(type==='IHDR'){l=d.readUInt32BE(0);h=d.readUInt32BE(4);if(d[8]!==8||d[9]!==6||d[12]!==0)throw new Error('Logo : PNG RGBA 8 bits non entrelacé attendu.')}
  else if(type==='IDAT')idat.push(d);
  p+=12+n;
 }
 const brut=zlib.inflateSync(Buffer.concat(idat)),ligne=l*4,px=Buffer.alloc(ligne*h);
 for(let y=0;y<h;y++){
  const f=brut[y*(ligne+1)],src=y*(ligne+1)+1,o=y*ligne;
  for(let i=0;i<ligne;i++){
   const a=i>=4?px[o+i-4]:0,b=y?px[o+i-ligne]:0,c=i>=4&&y?px[o+i-ligne-4]:0,x=brut[src+i];
