}

if(import.meta.url===pathToFileURL(process.argv[1]).href){
 const i=process.argv.indexOf('--en-ligne'),c=process.argv.indexOf('--console-en-ligne');
 // --console-en-ligne [dossier] : seulement la console en ligne (par défaut en-ligne\console\), sans rien publier.
 const e=process.argv.indexOf('--console-en-ligne-essai');
 // --console-en-ligne-essai <dossier> : version d'essai (CSP avec localhost), hors du dossier publié.
 // --programme-tele <dossier> (2026-11-24) : programme de l'écran télé en fichiers (carte SD, preparer-kit.ps1) ;
 // --paquet-tele <dossier> [id] : paquet de mise à jour des télés seul (essais), sans construire le reste du site.
 const pt=process.argv.indexOf('--programme-tele'),qt=process.argv.indexOf('--paquet-tele');
 if(pt>=0){if(!process.argv[pt+1])throw new Error('Donnez le dossier du programme télé.');const r=ecrireProgrammeTele(path.resolve(process.argv[pt+1]));console.log('Programme télé : '+r.nb+' fichiers, version '+r.id+', empreinte '+r.empreinte.slice(0,12)+'.')}
 else if(qt>=0){if(!process.argv[qt+1])throw new Error('Donnez le dossier du paquet télé.');const r=construireTele({dossier:path.resolve(process.argv[qt+1]),id:process.argv[qt+2]||idVersion(new Date())});console.log('Paquet télé : '+r.nb+' fichiers, '+Math.round(r.taille/1024)+' Ko, empreinte '+r.empreinte.slice(0,12)+'.')}
 else if(e>=0){if(!process.argv[e+1])throw new Error('Donnez le dossier de la version d’essai.');construireConsoleEnLigne({dossier:path.resolve(process.argv[e+1]),essai:true})}
 else if(c>=0)construireConsoleEnLigne(process.argv[c+1]?{dossier:path.resolve(process.argv[c+1])}:{});
 else construire(i>=0?{enLigne:true,notes:process.argv[i+1]||''}:{});
}

